// 自动生成：npm run quran:all（scripts/fetch-quran-all.mjs）。请勿手改经文。
export default {"52":["Tur bilan qasam.","Satrlangan kitob bilan qasam.","Yoyilgan teriga. (satrlangan)","Va obod uy bilan qasam.","Va koʻtarilgan bilan shift qasam.","Va toʻlgan dengiz bilan qasam.","Albatta, Robbing azobi roʻy berajak.","Uni hech bir qaytaruvchi yoʻqdir.","U kunda osmon larzaga kelib chayqalur.","Va togʻlar sayr etib yurur.","Bas, oʻsha kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","(Botilga) shoʻngʻib oʻynaydiganlarga! («vayl» soʻzi gohida «halokat», gohida «doʻzax» maʼnosida ishlatiladi va ikkalasi ham bu oyatga mosdir.)","U kunda jahannam oʻtiga (kuch bilan) itarilurlar.","Mana bu, sizlar yolgʻonga chiqargan oʻt boʻladir!","Bu sehrmi?! Yoki sizlar koʻrmayapsizlarmi?!","Kiringlar unga! Chidaysizlarmi, chidamaysizlarmi - baribir. Qilib yurgan amallaringizning jazosini olursizlar, xolos.","Albatta, taqvodorlar jannatlar va nozu neʼmatlar ichidadirlar.","Robbilari ularga bergan narsalardan lazzatdadirlar. Robbilari ularni jahannam azobidan saqlar.","Yenglar, ichinglar, osh boʻlsin. (Bular)qilgan amallaringiz uchundir.","Ular qator tizilgan soʻrilarga yonboshlagan holdalar. Va ularni goʻzal koʻzli hurlarga uylab qoʻyganmiz.","Oʻzlari iymon keltirib, zurriyotlari ularga iymon bilan ergashganlarning zurriyotini ularga qoʻshdik va ularning amallaridan hech narsani kamaytirmadik. Har bir kishi oʻz kasbi garovidir. (Bu dunyoda iymonu islom bilan oʻtgan kishilarning agar zurriyotlari ham iymon bilan oʻtgan boʻlsa, darajalari uncha yuqori boʻlmasa ham, Alloh ularni otalariga qoʻshib qoʻyar ekan. Lekin, shu bilan birga otalarning amalidan hech bir narsa kamaytirilmas ekan. Yaʼni, bolalariga olib berilib, ularning darajasi tenglatilmas ekan. Chunki har kim oʻzi qilgan kasb-amalning garovidir, amali yaxshi boʻlsa, oqibati ham yaxshi boʻladi. Alloh koʻrsatmasin, amali yomon boʻlsa, oqibati ham...)","Va Biz ularga xohlagan mevalari va goʻshtlarini muhayyo qilib qoʻydik.","Ular unda qadahlarni bir-birlariga uzaturlar. U yerda behuda sergaplik va gunoh yoʻq. (Oxirat sharobida noxush ishlarning birontasi roʻy bermas ekan.)","Va atroflarida xuddi sadafdagi durdek gʻulomlari aylanib, xizmatda yurishadir.","Baʼzilari boshqalaridan oʻgrilib soʻrasha boshladilar.","Albatta, biz ilgari oʻz ahlimiz davrasida U zotdan qoʻrquvchilardan edik.","Bas, Alloh bizga marhamat qildi va bizni doʻzax azobidan saqladi.","Albatta, biz ilgari Unga duo qilardik. Albatta, Uning Oʻzi yaxshilik qiluvchi va rahmlidur.","Bas, eslatgin: sen Robbing neʼmati ila folbin ham emassan, majnun ham emassan. (Oyatdagi «kohin» soʻzini biz folbin deb tarjima qildik. Aslida, Arabiston yarim orolida kohin alohida tushunchadir. U jinlar bilan aloqasi borligini va gʻoyibdan xabar berishni daʼvo qiluvchi shaxsdir. Shuningdek, kohinlar ruhlar, xudolar bilan ham aloqamiz bor deyishadi va baʼzan tabiblik daʼvosini ham qilishadi.)","Balki ular: «U shoir, biz unga oʻlim yetishini kutamiz», derlar?","Sen: «Kutinglar, albatta, men ham sizlar bilan birga kutuvchidirman», deb ayt.","Yo aqllari shunga buyurarmi yoki ular tugʻyonga ketgan qavmlarmi?","Balki, u(Qurʼon)ni oʻzi toʻqidi, derlar? Yoʻq, ular iymon keltirmaslar.","Agar ularning gapi rost boʻlsa, u(Qurʼon)ga oʻxshash soʻzni keltirsinlar.","Balki, ular hech narsadan hech narsa yoʻq oʻzlari yaralgandirlar?! Yoki ular yaratuvchilarmi?","Balki, ular osmonlaru yerni yaratgandirlar?! Yoʻq, ular ishonmaslar.","Balki ularning huzurida Robbingning xazinalari bordir?! Yoki ular boshqaruvchilarmi?","Balki ularning (xabar) eshitadigan narvonlari bordir?! Undoq boʻlsa, eshituvchilari ravshan hujjat keltirsinlar. (Mushriklar Muhammad alayhissalomni yolgʻonchiga chiqarganlar. Xoʻsh, nimaga asoslanib bunday qilishgan? Yoki ularning osmonga qoʻygan narvonlari bor-u unga chiqib, Muhammad Paygʻambar emas, unga vahiy yuborilayotgani yoʻq, degan xabarni eshitishdimi? Agar haqiqatda eshitgan boʻlsalar, ochiq-oydin dalil koʻrsatsinlar.)","Yoki U zotga qizlaru sizlarga oʻgʻillarmi?!","Yoki sen ulardan haq soʻrayapsan-u, ular toʻlovdan qiynalayaptilarmi?!","Balki ularning ixtiyorida gʻayb (ilmi) boʻlib, ular yozib olayotgandirlar?!","Balki hiyla koʻrsatishni xohlarlar?! Bas, kofirlar hiylalarining jazosini torturlar.","Balki, ularning Allohdan boshqa xudolari bordir?! Alloh ular keltirayotgan shirkdan pok boʻldi.","Agar ular boshlariga tushayotgan parchani koʻrsalar ham, toʻplangan bulut, derlar.","Ularni halokatga uchraydigan kunlariga yoʻliqqunlarigacha tek qoʻy. (Mushrik va dinsizlarni qiyomat kunigacha qoʻyib ber, nima qilishsa qilishaversin.)","U kunda hiylalari ularga hech qanday foyda bermas va ularga yordam ham berilmas.","Va, albatta, zulm qilganlarga undan oʻzga azob ham bor, lekin koʻplari bilmaslar. (Yaʼni, kofir, zolimlarga oxirat azobidan oʻzga bu dunyoning azobi ham bor yoki qabr azobi boʻlishi ham mumkin.)","Bas, Robbing hukmiga sabr qil. Albatta, sen koʻz oʻngimizdasan, oʻringdan turganingda Robbingga tasbih ayt!","Va kechasi ham. Bas, yulduzlar botgandan keyin ham tasbih ayt. (Demak, har doim Allohga bogʻliq boʻlmoq zarur. Imom Molik Zuhriydan qilgan rivoyatlarida Ibn Matʼamning otasi aytadiki, «Paygʻambar alayhissalomni shom namozida «Vat-Tur» surasini oʻqiyotganlarini eshitdim. U kishidan koʻra ovozi shirinroq va qiroati yaxshiroq odamni koʻrmaganman».)"],"53":["Botayotgan yulduz bilan qasam.","Sizning birodaringiz adashgani ham, yoʻldan ozgani ham yoʻq.","U havodan nutq qilmas.","U (Qurʼon) vahiydan oʻzga narsa emas.","Unga shiddatli quvvat egasi oʻrgatdi.","Mirrat egasi. Bas koʻtarildi.","Va u oliy ufqda edi.","Soʻngra yaqinlashdi va juda ham yaqin boʻldi.","Bas, ikki kamon miqdoriday joygda boʻldi. Balki undan ham yaqinroq keldi.","Va U zot bandasiga nimani vahiy qilgan boʻlsa, yetkazdi.","Qalb (koʻz) koʻrganini yolgʻonga chiqarmadi.","U bilan oʻzi koʻrgan narsa ustida tortishasizlarmi?!","Va darhaqiqat, uni boshqa safar koʻrdi.","Tugash daraxti oldida.","U(daraxt)ning huzurida maʼvo jannati bor.","Oʻshanda, daraxtni oʻraydigan narsa oʻrab turibdi.","Nigoh burilmadi ham, haddidan oshmadi ham.","Darhaqiqat, Oʻz Robbisining ulkan belgilaridan koʻrdi. (Muhammad alayhissalom meʼroj kechasida, jannatni, doʻzaxni, Baytul maʼmurni, oʻtgan Paygʻambarlarni, Jabroil alayhissalomning asl holatlarini va boshqalarni koʻrdilar.)","Lot va Uzzoni oʻylab koʻrdingizmi?","Va boshqasi-uchinchisi Manotni ham?","Sizlarga erkag-u, U zotga ayolmi?","Undoq boʻlsa, bu notoʻgʻri taqsim-ku!","U(but)lar siz va ota-bobolaringiz qoʻygan nomlardan oʻzga hech narsa emas. Alloh bunga hech hujjat tushirgan emas. U (mushrik)lar Robbilaridan hidoyat kelganiga qaramay gumon va havoyi nafs xohishiga ergasharlar, xolos.","Yoki har inson nimani xohlasa, shu boʻlurmi?","Zero, oxirat ham, dunyo ham Allohnikidir.","Osmonlarda qanchadan-qancha farishtalar mavjud, ularning shafoati hech foyda bermas. Magar Alloh Oʻzi xohlagan va rozi boʻlganlarga izn bersagina.","Albatta, oxiratga iymon keltirmaganlar farishtalarni ayol nomi bilan nomlarlar.","Ularda bu haqda hech qanday ilm yoʻq. Gumondan boshqa narsaga ergashmaslar. Albatta, gumon haqiqat oʻrniga oʻtmas.","Bizning zikrimizga orqa oʻgirgan, hayoti dunyodan boshqani xohlamaydiganlardan yuz oʻgir.","Ularning erishgan ilmlari mana shu. Albatta, Robbing Uning yoʻlidan adashganlarni bilguvchidir va hidoyatdagilarni ham bilguvchidir.","Osmonlaru yerdagi barcha narsalar Allohnikidir. U yomonlik qilganlarni amaliga yarasha jazolar va yaxshilik qilganlarni goʻzal(mukofot)ila mukofotlar.","Ular kichik gunohlardan boshqa katta gunohlar va fahsh ishlardan chetda boʻladiganlardir. Albatta, Robbing magʻfirati keng zotdir. U sizlarni tuproqdan paydo qilganda ham, onalaringiz qorinlarida homilalik chogʻingizni ham yaxshi biluvchidir. Shundoq ekan, oʻzingizni oqlamang, U kim taqvodorligini yaxshi biladir. (Oyatdagi «Lamam» soʻzini biz «kichik gunohlar» deb tarjima qildik. Aslida, «lamam» soʻzi «oz», «kichik» maʼnolarini anglatadi. «Kichik gunoh» iborasi eng munosib maʼnodir. «Fahsh ishlar» iborasi qabihligi katta ish va soʻzlarga nisbatan ishlatiladi. Shariatda «katta gunoh» deb Alloh haromligini bayon qilgan va yoki jazosi belgilangan gunohlarga aytiladi. Oʻgʻrilik, odam oʻldirish va zino kabilar.)","Yuz oʻgirib ketganni koʻrmadingmi?!","U ozgina berdi va toʻxtatdi.","Uning huzurida gʻayb ilmi boru, u koʻrib turibdimi?! (Gʻaybni faqat Alloh bilib, boshqa hech kim bilmasligi aniq. Oxiratning gʻamini yemay yurganlar nimaga suyanishadi? Gʻaybni bilmagandan keyin inson doimo oʻziga oxiratda foyda beradigan ishlarni koʻproq bajarishga harakat qilmogʻi lozim.)","Yoki Musoning sahifalaridagi soʻzlar xabari unga berilmadimi?","Va vafo qilgan Ibrohimning?","«Hech bir gunohkor jon boshqaning gunohini koʻtarmas.","Har bir insonga oʻz qilganidan boshqa narsa yoʻq.","Va, albatta, uning qilmishi tezda koʻrinar.","Soʻngra jazo yoki mukofoti toʻliq berilar», deb. (Ushbu zikr etilgan maʼnolar Muso a. s. ning Tavrotlarida va Ibrohim a. s. ning sahifalarida kelgandir.)","Va, albatta, intiho Robbing huzuridadir.","Va, albatta, kuldirgan ham Oʻzi, yigʻlatgan ham Oʻzi.","Albatta, oʻldirgan ham Oʻzi, tiriltirgan ham Oʻzi.","Albatta, ikki juftni; erkak va ayolni yaratgan ham Oʻzi.","Nutfadan, oqib tushganda.","Va, albatta, keyingi paydo qilish zimmasidagi zot ham Oʻzi.","Va, albatta, behojat qilgan ham Oʻzi, badavlat qilgan ham Oʻzi.","Va, albatta Sheʼroning Robbisi ham Uning Oʻzi.","Va, albatta, birinchi Odni halok qilgan ham Oʻzi.","Va Samudni boqiy qoldirmagan ham Oʻzi.","Va bundan oldin Nuh qavmini (halok qilgan ham Oʻzi). Chunki ular oʻta zolim va oʻta tugʻyonga ketgan edilar.","Va toʻntarilganni qulatgan (ham Oʻzi).","Bas, ularni oʻragan narsa oʻrab oldi.","Shunday ekan, Robbingning qaysi neʼmatlariga shak keltirasan?","Bu avvalgi ogohlantiruvchilar kabi bir ogohlantiruvchidir. (Ogoh boʻlinglar: avvalgi ogohlantiruvchilarga dushman boʻlganlarning kuni sizlarning boshingizga tushib qolmasin!)","Yaqinlashuvchi yaqinlashdi.","Uni Allohdan boshqa kashf qiluvchi yoʻq.","Bu soʻzdan sizlar ajablanasizlarmi?","Va kulasizlar-u, yigʻlamaysizlarmi?","Va holbuki, sizlar beparvosizlar.","Bas, llohga sajda va ibodat qilinglar."],"54":["Soat (qiyomat) yaqinlashdi va oy boʻlindi.","Agar bir oyat-moʻjizani koʻrsalar, yuz oʻgirarlar, bu oʻtkinchi sehr, derlar.","Va yolgʻonga chiqardilar hamda havoyi nafslariga ergashdilar. Holbuki, har bir ish oʻz oʻrnini topuvchidir.","Va, darhaqiqat, ularga zajri bor xabarlardan kelgan edi.","(Bu Qurʼon) yetuk hikmatdir. Bas, ogohlantiruvchilar foyda bermas.","Bas, ulardan yuz oʻgir! Chaqiruvchi munkar narsaga chaqirgan kunda. qabrlardan, koʻzlari qoʻrqinchga toʻlgan holda, xuddi yoyilgan chigirtkaga oʻxshab chiqib keladilar.","Ular qabrlardan, koʻzlari qoʻrqinchga toʻlgan holda, xuddi yoyilgan chigirtkaga oʻxshab chiqib kelurlar.","Chaqiruvchiga qarab boʻyinlarini choʻzib, shoshilib borurlar. Kofirlar, bu qiyin kun-ku, derlar.","Bulardan oldin Nuh qavmi ham yolgʻonchi qilgan edi. Bas bandamizni yolgʻonchiga chiqarishdi va, majnun, deyishdi. Hamda unga toʻsiqlar qoʻyishdi.","Bas, u Robbisiga duo qilib: «Albatta, men magʻlub boʻldim, yordam ber», dedi.","Osmon eshiklarini sharros suv bilan ochib yubordik.","Va yerdan otiltirib, buloqlar chiqardik. Bas, suvlar taqdir qilingan ish uchun birlashdilar.","Va u(Nuh)ni taxtalari va mixlari bor narsa ustiga koʻtardik.","U(kema) inkor qilingan shaxs (Nuh)ga mukofot boʻlib, Bizning inoyatimiz ila yuradir.","Va u(hodisa)ni belgi qilib qoldirdik. Qani, ibrat oluvchi bormi?","Bas, Mening azobim va ogohlantirishim qandoq boʻldi?!","Darhaqiqat, Biz Qurʼonni zikr uchun oson qildik. Bas, zikr qiluvchi bormi?!","Od (Hudni) yolgʻonchiga chiqardi. Bas, Mening azobim va ogohlantirishim qandoq boʻldi?","Biz davomli mashʼum kunda ular ustiga sorsor shamolini yubordik. («Sorsor» deb nomlangan shamol oʻzi oʻta sovuq boʻlib, ovozi juda ham kuchli boʻlar ekan.)","U odamlarni, xuddi xurmo daraxtini tomiri bilan qoʻporgandek, (yerdan) uzib-uchirib tashlardi.","Bas, Mening azobim va ogohlantirishim qandoq boʻldi?!","Darhaqiqat, Biz Qurʼonni zikr uchun oson qildik. Bas, zikr qiluvchi bormi?!","Samud ogohlantiruvchilarni yolgʻonga chiqardi.","Ular: «Biz oʻzimizdan boʻlgan bir odamga ergashamizmi? Agar shunday boʻlsa, albatta, adashuvda va jinnilikda boʻlamiz.","Bizlarning oramizdan (kelib-kelib) unga zikr (vahiy) tushirilibdimi; Yoʻq, u yolgʻonchi va kekkaygandir», dedilar.","Ertaga kim yolgʻonchi va kekkaygan ekanini bilurlar.","Biz ularni sinash uchun tuyani yuboruvchimiz. Ularni kuzatib tur va sabr qil.","Va ularga, albatta, suv oralarida taqsimlanganining xabarini ber. Har bir ichishga (oʻz vaqtida) hozir boʻlinar. (Tuya bilan Samud qavmi suvning kunma-kun taqsimlangani toʻgʻrisida gap borayotibdi.)","Bas, ular oʻz sheriklarini chaqirdilar. U (tuyani) tutdi va soʻyib yubordi.","Bas, Mening azobim va ogohlantirishim qandoq boʻldi?!","Albatta, Biz ularga bir ovoz yubordik. Va ular qoʻra quruvchi (yiqqan) quruq shox-shabbalarga oʻxshab qoldilar.","Darhaqiqat, Biz Qurʼonni zikr uchun oson qildik. Bas, zikr qiluvchi bormi?!","Lut qavmi ogohlantiruvchilarni yolgʻonchiga chiqardi.","Albatta, Biz ularning ustiga (tosh) boʻron yubordik. Faqat Lut xonadoniga sahar chogʻi najot berdik.","Bu Biz tarafimizdan neʼmat boʻldi. Kimki shukr qilsa, xuddi shunday mukofotlarmiz.","Darhaqiqat, u(Lut) ularni Bizning (azobga) tutishimizdan ogohlantirgan edi. Bas, ular ogohlantirishlarga ishonmadilar.","Ular undan mehmonlarini topshirishni soʻradilar. Bas, koʻzlarini koʻr qildik. Mening azobim va ogohlantirishlarimni totib koʻrsinlar.","Batahqiq, erta tongda ularni sobit, davomli azob tutdi.","Bas, Mening azoblarimni va ogohlantirishlarimni tatib koʻringlar!","Darhaqiqat, Biz Qurʼonni zikr uchun oson qildik. Bas, zikr qiluvchi bormi?!","Darhaqiqat, Firʼavn ahliga ogohlantirishlar keldi.","Ular Bizning oyatlarimizning barchasini yolgʻonga chiqarishdi. Bas, Biz ularni gʻolib, qudratli oluvchining olishi bilan oldik.","Sizning kofirlaringiz avvalgilaringizdan yaxshiroqmi?! Yoki samoviy kitoblarda sizlarga oqlov bormi?!","Yoki, Biz nusratga erishuvchi jamoatmiz, deyishadimi?!","U jamoa tezda yengilar va orqalariga qarab qocharlar.","Yoʻq! Ularga vaʼda qilingan vaqt, soat(qiyomat)dir. Va soat (azobi) ulkanroq va achchiqroqdir.","Albatta, jinoyatkorlar adashuvda va olov-otashdadirlar.","Yuztuban doʻzaxga sudraladigan kunlarida: «Jahannam azobini tatib koʻring!» (deyilur).","Albatta, Biz har narsani oʻlchov bilan yaratdik.","Bizning farmonimiz bir soʻzdan oʻzga emas. Koʻz yumguncha boʻlur.","Darhaqiqat, Biz sizga oʻxshaganlarni halok qildik. Bas, buni eslovchi bormi oʻzi?!","Va ularning har bir ishi kitoblardadir.","Har bir kichigu katta satrlangandir. (Makka mushriklari, qanday qilib insonning ishlarini satrlarga yozib, hujjat toʻplab borish mumkin, deb oʻsha vaqtda ajablangan boʻlishlari mumkin. Ammo biz hozirgi hisob-kitoblarni, yozish asboblarini koʻrib-bilib turib, qandoq qilib bu haqiqatni inkor eta olamiz?)","Albatta, taqvodorlar jannatu anhorlarda.","Sidq oʻrindiqda, qudratli Podshoh huzuridadirlar."],"55":["Rohman.","Qurʼoni oʻrgatdi.","Insonni yaratdi.","Unga bayonni oʻrgatdi.","Quyosh va oy hisobdadir.","Oʻt-oʻlan ham, daraxtlar ham sajda qilurlar. (Dunyodagi jonliyu jonsiz barcha narsa Allohning irodasidan tashqari chiqa olmasligiga, hammasi olam Parvardigoriga bogʻliq ekaniga dalolat qilmoqda.)","Osmonni baland koʻtardi va tarozuni oʻrnatdi.","Tortishda haddan oshmasligingiz uchun. (Agar ushbu tarozuni Islom dini, Qurʼon kitobi, Muhammad alayhissalom Paygʻambari orqali oʻrnatmaganida, adolat mezoni buzilardi, haqdan botil ustun kelardi. Yer yuzini fisqu fasod bosardi.)","Adolat ila oʻlchang va tarozudan urib qolmang.","Va yerni haloyiq uchun qoʻydi.","U(yer)da mevalar va gulkosali xurmolar bor.","Va somonli donlar hamda rayhon bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Insonni sopolga oʻxshash qurigan loydan yaratdi.","Va jinlarni alangadan yaratdi.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz.","U ikki mashriq va ikki magʻribning Robbisidir. (Ikki mashriq deganda, quyoshning yozdagi va qishdagi chiqish joylarini hamda ikki magʻrib deganda, yozdagi va qishdagi botish joylarini tushunish kerak.)","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?","Daryo-dengizlarni bir-biri bilan uchrashadigan qilib qoʻydi.","Oʻrtalaridagi toʻsiqdan oshib oʻtolmaslar. (Shoʻr dengiz bilan chuchuk suvli daryo oʻrtasida bir toʻsiq boʻlib, ular bir-birlariga aralashib ketmaydi degan maʼnoni anglatadi.)","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?","U ikkisidan luʼluʼ va marjon chiqar.","Bas, Robbingizning qaysi neʼmatlrini yolgʻon deya olursiz?!","Dengizlarda togʻdek boʻlib suzib yuruvchilar ham Unikidir.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","(Yer) yuzidagi barcha jonzot foniydir.","Ulugʻlik va ikrom egasi Robbingning Oʻzigina boqiydir.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?","Undan yeru osmondagi jonzotlar soʻrarlar. U har kuni ishdadir. (Butun mavjudot, yerda boʻlsin, osmonda boʻlsin, Allohdan soʻrovlarini soʻraydi. Nimani soʻrashlari oyatda tayin qilinmagan. Har kim nimaga muhtoj boʻlsa, oʻshani soʻraydi.)","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Albatta, sizlar uchun vaqt toparmiz, ey insu jinlar!","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ey jin va ins jamoalari, agar siz osmonlaru yer chegaralaridan chiqib ketishga qodir boʻlsalaringiz, chiqaveringlar. Faqat Sulton ila chiqa olursiz, xolos.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ustingizdan oʻt-choʻgʻ va tutun yuborilur. Bas, qutula olmassiz.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Osmon yorilib, qirmizi moyga aylangan vaqtda...","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Bas, u kunda ins ham, jin ham gunohidan soʻralmas. (Qiyomat boshlangandan insdan ham, jindan ham gunoh qilgan-qilmagani haqida soʻrab oʻtirilmaydi. Chunki hammaning basharasidan, holatidan uning kim ekanligi bilinib turadi.)","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Jinoyatchmlar siymolaridan bilinib turur. Va ularning peshona sochlari va oyoqlaridan tutilur.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Jinoyatchilar yolgʻonga chiqarayotgan jahannam shu boʻlur.","Ular jahannam bilan oʻta qaynoq suv oʻrtasida aylanur.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Robbisi huzurida turishdan qoʻrqqanlar uchun ikki jannat bor. (Qiyomat kuni olam Parvardigorining huzurida savollarga javob berishdan, hisob-kitob maqomidan qoʻrqib, tirikligidayoq tayyorgarlik koʻrib, yaxshilik bilan kun kechirganlarga ikki jannat bor ekan. «Ikkin jannat»ning bir necha sharhlari bor, jumladan, insga alohida jannat, jinga alohida jannat yoki ikkovlaridan har birlariga ikkitadan jannat, gunohkorlar jahannam bilan oʻta qaynoq suv oʻrtasida aylansalar, taqvodorlar birinchi jannatlari, yaʼni, bogʻlari bilan ikkinchi jannatlari - bogʻlari orasida sayr qiladilar.)","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ular shox-novdalidirlar.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ikkovlarida oquvchi ikki buloq bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ikkovlarida ham mevadan juft navlar bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ipak astarli toʻshaklarga yonboshlagan va ikki jannat mevalari yaqin boʻlgan hollari bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ularda koʻzlari tiyilgan, avval ins ham, jin ham tegmagan(hur)lar bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","U(hur)lar xuddi yoqut va marjonga oʻxsharlar.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ehsonning mukofoti, faqat ehsondir.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","U ikkovidan pastroqda yana ikki jannat bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ikkovlari yam-yashildir.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ikkovlarida otilib turuvchi ikki buloq bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ikkovlarida mevalar, xurmo va anorlar bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ularda yaxshi, goʻzallar bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Chodirlarni lozim tutgan hurlar bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Avval ularga ins ham, jin ham tegmagan.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Yashil bolishlarga va goʻzal gilamlarda yonboshlagan hollari bor.","Bas, Robbingizning qaysi neʼmatlarini yolgʻon deya olursiz?!","Ulugʻlik va ikrom egasi boʻlmish Robbing ismi muborak boʻldi."],"56":["Voqea voqeʼ boʻlganda.","Uning voqeʼ boʻlishini yolgʻon qiluvchi (jon) yoʻqdir.","U ham pastlatuvchi, ham koʻtaruvchidir.","Qachonki yer qattiq larzaga kelganda.","Togʻlar maydalanib, titilganda.","Bas, ular tarqalgan chang-toʻzonga aylanganda.","Va sizlar uch toifa boʻlgangda.","Oʻng taraf egalari. Oʻng taraf egalari ne(saodatlilar)dir?!","Va chap taraf egalari. Chap taraf egalari ne(badbaxtlar)dir?!","Va peshqadamlar, peshqadamlar.","Ana oʻshalar, (Allohga) yaqin boʻlganlar.","Serneʼmat jannatlardalar.","Avvalgilardan koʻpgina jamoatlar.","Va oxirgilardan ozdirlar.","Toʻqima soʻrilaridalar.","Bir-birlariga roʻbaroʻ boʻlib, yonboshlagan hollaridalar. (Yaʼni, peshqadamlar jannat duru-yoqutlarni aralash qilib toʻqilgan soʻrilarda bir-birlariga qarab, yonboshlab-yastanib rohatlanishar ekan.)","Atroflarida mangu yosh yigitlar aylanib yururlar.","Oqar chashma (mayi toʻlatilgan) qadahlar, koʻzalar va kosalar bilan.","Undan bosh ogʻrigʻi ham, mast ham boʻlmaslar.","Va ular xohlagan mevalar bilan.","Ishtahalari tusagan qush goʻshti bilan.","Yana koʻzi goʻzal hurlar bor.","Misoli yashirilgan dur.","Bular, qilgan amallarning mukofotidur.","Ular u yerda behuda, gunoh soʻzlarni eshitmaslar.","Faqat «Salom, Salom» deyilganini (eshitarlar). (Bir-birlariga salom beradilar, ularga farishtalar ham salom beradilar. Allohning salomi ham yetkazib turiladi.)","Oʻng taraf egalari. Oʻng taraf egalari ne(saodatlilar)dir!","Ular tikonsiz sidrzorlardadir. (Sidr-hushboʻy hidli buta boʻlib, arablar uni hidi uchun yaxshi koʻrar ekanlar. Ammo tikani juda koʻp boʻlarkan.)","Sermeva bananzorlardadir.","Va yoyilgan soyalardadir.","Oqar suvlardadir.","Serob mevalardadir.","Tugamaydigan va man qilinmaydiganlardadir.","Baland-baland koʻrpachalardadir.","Albatta, Biz u(hurlar)ni dafʼatan, xos qilib, yaratdik.","Bas, ularni bokiralar qildik.","Tengdosh mahbubalar qildik.","Oʻng taraf egalari uchun.","Ular avvalgilardan koʻpgina jamoatlardir.","Keyingilardan ham koʻpgina jamoatlardir.","Va chap taraf egalari. Chap taraf egalari ne(badbaxtlar)dir?!","Ular oʻt shamol va qaynoq suvdadirlar.","Qop-qora tutundan boʻlgan soyadadirlar.","Salqin hamemas, foydaii ham.","Albatta ular bundan oldin hoy-havasga berilganlardan edilar.","Va mudom katta gunoh ishlar qilar edilar.","Va «Biz oʻlib, tuproqqa va suyakka aylanganimizdan keyin qayta tiriltrilamizmi?","Avvalgi otalarimiz ham-a?!» der edilar.","Aytgil: «Albatta, avvalgilar va oxirgilar.","Maʼlum kunga belgilangan vaqtda albatta toʻplanuvchilar».","Soʻngra, siz ey adashganlar, yolgʻonga chiqaruvchilar!","Albatta, zaqqum daraxtidan yeyuvchisizlar.","Bas, undan qorinlarni toʻldiruvchisizlar.","Bas, ustidan oʻta qaynoq suvdan ichuvchisizlar.","Bas, chanqoq tuyadek ichuvchisizlar.","Ularning qiyomat kunidagi ziyofatlari mana shu!","Biz sizlarni yaratganimiz, ishonsalaring-chi!","Oʻzingiz chiqaradigan maniyni oʻylab koʻring-a!","Uni sizlar yaratasizmi yoki Biz yaratuvchimizmi?!","Orangizdagi oʻlimni Biz belgilaganmiz va Biz ojiz emasmiz.","Sizning oʻrningizga sizga oʻxshashlarni almashtirishdan va sizlarni oʻzingiz bilmaydigan holda yaratishdan.","Va darhaqiqat, avvalgi yaratilishini bildingiz-ku, eslasalaringiz-chi!","Oʻzingiz ekayotgan narsani oʻylab koʻring-a!","Uni siz undirasizmi yoki Biz undiruvchimizmi?","Agar xohlasak, Biz uni quruq choʻpga aylantirib qoʻyamiz. Sizlar esa nadomatda ajablanib:","«Albatta, biz ziyon koʻrganlarmiz.","Balki mahrum boʻlganlarmiz», (deysiz).","Oʻzingiz ichadigan suvni oʻylab koʻring-a!","Uni bulutlardan siz tushirasizmi yoki Biz tushuruvchimizmi?","Agar xohlasak, Biz uni shoʻr qilib qoʻyamiz. Shukr qilsangiz-chi!","Oʻzingiz yoqadigan olovni oʻylab koʻring-a!","Uning daraxtini siz yaratgansizmi yoki Biz yaratuvchimizmi?","Biz u(olov)ni eslatma va yoʻlovchilar uchun manfaʼat qilib qoʻydik.","Bas, ulugʻ Robbing ismini poklab yod et! (Mazkur neʼmatlarning egasini tanigan inson Ulugʻ Alloh taologa tasbih aytib, ibodat qilishga oʻtadi.)","Yulduzlarning manzillari bilan qasam ichaman. («Joylari» deganimiz - uning oʻrnashgan, chiqish va botish joylari - burjlaridir.)","Albatta, agar bilsangiz bu ulugʻ qasamdir. (Bu oyati karima oʻn toʻrt asrdan koʻproq muqaddam nozil boʻlganligi hammaga maʼlum. Oʻsha paytda odamlar yulduzlar haqida sodda tushunchaga ega edilar, ularning hajmi, soni, harakati haqida deyarli hech narsa bilmas edilar. Falakiyot ilmi rivojlanib, ular vositasida ochilgan juda koʻplab kulliyotlar Qurʼon oyatlarining ulugʻligini tasdiqladi.)","Albatta, u Qurʼoni karimdir.","U saqlangan kitobdadir.","Uni faqat poklanganlargina ushlaydir.","U olamlarning Robbisidan tushirilgandir.","Bas, sizlar mana shu soʻz(Qurʼon)ga beparvolik qilasizlarmi?!","Va yolgʻonga chiqarishni rizq qilib olasizlarmi?! (Yaʼni, iymon keltirish lozim boʻlgan narsalarga ishonmaslikni oʻz nasibangiz qilib olasizlarmi?)","Joningiz halqumga kelib qolsa-chi?!","Holbuki, oʻsha vaqtda oʻzlaringiz qarab turgan boʻlasizlar.","Biz esa, sizdan koʻra unga yaqinmiz, ammo sizlar koʻrmaysizlar. (Yaʼni, Allohning Oʻz bandasiga qanchalar yaqinligini anglamaysizlar. Oʻlayotgan odamga Alloh taolo uning ustida turgan qarindoshidan koʻra yaqinroq boʻladi.)","Agar siz hisob bermas boʻlsangiz.","U(jon)ni oʻrniga qaytaring-chi! Agar rostgoʻy boʻlsangiz!","Agar, u muqarrablardan boʻlsa.","Rohatda, farogʻatda va serneʼmat jannatdadir.","Agar oʻng taraf egalaridan boʻlsa.","Bas, «Senga oʻng taraf egalaridan Salom»dir.","Va agar yolgʻonga chiqaruvchilardan, gumrohlardan boʻlsa.","Bas, oʻta qaynoq suvdan ziyofatdir.","Va doʻzaxga kirishdir.","Albatta, ushbuochiq-oydin haqiqatdir.","Bas, ulugʻ Robbing ismini poklab yod et!"],"57":["Osmonlardagi va yerdagi narsalar Allohga tasbih aytdi. Va U aziz va hakimdir.","Osmonlaru yerning mulki Unikidir. U tiriltirur va oʻldirur va U har bir narsaga qodirdir.","U avval va oxir, oshkor va pinhondir. Va U har bir narsani biluvchidir. («Avval»-U barcha mavjudotlar yoʻqligida bor edi. «Oxir»-U hamma narsa yoʻq boʻlib ketganda ham Oʻzi qoladi. «Oshkor»-Uning mavjudligi oshkor, ochiq-oydindir. «Zohir»-U hamma narsadan-ustundir. «Pinhon»-U koʻzga koʻrinmaydi. Hammadan pinhon - maxfiy narsalarni bilib turuvchidir.","U osmonlaru yerni olti kunda yaratib, soʻngra arshni egallagan zotdir. Yerga nima kirganini ham, undan nima chiqqanini ham, osmondan nima tushganini ham unga nima chiqqanini ham biladir. U qayerda boʻlsangiz ham siz bilan birgadir. Alloh qilayotgan amallaringizni koʻrib turuvchidir. («Istivo» lugʻatda koʻtarilish, oʻrnashish va egallash maʼnolarini bildiradi. Lekin Allohga nisbatan bu maʼnolarni biz tushunganday holatda ishlatib boʻlmaydi. Shuning uchun, hamma narsani yaratgandan soʻng Alloh ularni Oʻzining tasarrufiga oldi, deb sharhlanadi.)","Osmonlaru yerning mulki Unikidir va barcha ishlar Allohning Oʻzigagina qaytadir.","U kechasini kunduzga kiritadir, kunduzni kechasiga kiritadir va U koʻksingizdagi narsani ham yaxshi biluvchidir.","Allohga va Uning Rasuliga iymon keltiringlar hamda sizlarni xalifa qilib qoʻygan narsalardan ehson qilinglar. Bas, sizlardan iymon keltirgan va ehson qilganlarga ulkan ajr bordir.","Sizlarga nima boʻldiki, Allohga iymon keltirmaysizlar?! Holbuki, Paygʻambar sizlarni Robbiingizga iymon keltirishga chaqirib turibdir. U sizlardan ahd olgan edi. Agar iymon keltiruvchi boʻlsalaringiz. (Yaʼni, Agar sizlar oʻzi biror narsaga ishonuvchi boʻlsalaringiz, nima uchun Allohga ishonmayapsizlar. Holbuki, orangizda Paygʻambar yurib, sizni parvardigoringizga iymon keltirishga chaqirib turibdi.)","U zot Oʻz bandasiga sizlarni zulmatlardan nurga chiqarish uchun ravshan oyatlarni tushiradir. Va, albatta, Alloh sizlarga shafqatli va rahmlidir.","Sizlarga nima boʻldiki, Allohning yoʻlida ehson qilmaysizlar?! Holbuki, osmonlaru yerning merosi Allohnikidir. Sizlardan hech kim fathdan ilgari ehson qilganlarga va urushda qatnashganlarga barobar boʻla olmaydir. Ularning darajalari fathdan soʻng ehson qilganlardan va urushda qatnashganlardan koʻra ulugʻdir. Alloh barchaga yaxshilikni vaʼda qilgandir. Va Alloh nima qilayotganlaringizdan xabardordir. (Oyatdagi «Fath» soʻzi Makkai mukarramani Paygʻmbar alayhissalom boshliq musulmonlar Madinai munavvaradan kelib mushriklardan ozod qilish maʼnosida aytilgan.)","Allohga yaxshi qarz beradigan kishi bormi?! Bas, U zot unga bir necha marta koʻpaytirib qaytaradir va unga karamli ajr bordir. (Alloh taolo Oʻz dini yoʻlida sarflanadigan molu mulkni unga berilgan «yaxshi qarz»ga, yaʼni, oraga sudxoʻrlik va boshqa gʻarazlar qoʻshilmagan qarzga oʻxshatmoqda. Bunda ehson, infoq qilishga katta targʻib bordir. Chunki qarzni muhtojlar oladi, Alloh esa hech narsaga muhtojligi yoʻq, balki barchaning Unga muhtojligi bor zotdir. )","Moʻmin va moʻminalarni ularning oldilarida va oʻng taraflarida nurlari harakat qilayotgan holda koʻrgan kuningda, Sizlarga bugungi kunning xushxabari daraxtlari ostidan suvlari oqib turgan jannatlardir. U joyda abadiy qolajaksiz. Bu esa, aynan ulkan yutuqdir, (deyiladir).","Munofiq va munofiqalar iymonlilarga: «Toʻxtab turinglar, biz ham nuringizdan bir oz olaylik», degan va ularga: «Ortingizga qayting hamda nur qidiring», deyilgan kunda. Bas, ularning orasiga eshigi bor qoʻrgʻon uriladir. Uning ichida rahmat, tashqarisida - oldida azobdir. (Qiyomat kuni zulmat boʻlib, albatta, bu oʻsha kunda roʻy beradigan hodisalarning bir bosqichi, xolos. Hech kim hech narsani koʻrmay qolganda, moʻminlarga nur ato qilinib, ular shodon va shahdam yurib borishadi. Shunda munofiqlar: «Bizni tashlab ketmanglar, kutib turinglar, bizga ham nuringizdan ozgina beringlar», deb yalinishar ekan. Ularga: «Ortingizga qaytib, oʻzingiz nur axtaring», deyilarkan. Ular qanday qilib nur topishardi. Bu dunyoda johiliyat zulmatlaridan Islom nuriga chiqishni xohlamagan edilar. Endi oxirat zulmatlarida xoru zor boʻlishlari turgan gap.)","Ularga (munofiqlar): «Biz siz bilan birga emasmidik?!» deb nido qilurlar. Ular: «Xuddi shunday. Lekin sizlar Allohning amri kelguncha oʻzingizni oʻzingiz fitnaga duchor qildingiz, koʻz tikib kutdingiz, shubha qildingiz va sizlarni xom-xayollar gʻururga ketkazdi. Sizlarni Alloh haqida aldamchi aldab qoʻydi.","Bugun sizlardan ham, kufr keltirganlardan ham toʻlov olinmas. Joylaringiz jahannamda, u sizning egangizdir. Qanday ham yomon borar joy!» - derlar. (Munofiqlar: «Ajab emas, Islom magʻlubiyatga uchrab, musulmonlar yengilsa», degan xom xayollarga berilib, gʻururga ketadilar. Munofiqlarni shayton «Sizlar toʻgʻri ish qilyapsizlar, maboda notoʻgʻri boʻlsa ham, Allohning oʻzi kechiradi», deb ularni aldab qoʻyadi. Qiyomat kunida ularga hech qanday najot yoʻq.)","Iymon keltirganlar uchun Allohning zikriga va nozil boʻlgan haqqa qalblari yumshash, ayni choqda, oldin kitob berilgan, soʻng muddat oʻtishi bilan qalblari qotib qolgan, koʻplari fosiq boʻlganlarga oʻxshamaslik vaqti kelmadimi?! (Agar Alloh tez-tez eslab turilmasa, Qurʼon va shariatdan, din taʼlimotlaridan uzoqlashilsa, inson qalbini mogʻor bosadi, bagʻri toshga aylanadi. Unga Allohning zikri ham, diniy taʼlimotlar ham taʼsir qilmaydigan boʻlib qoladi. Avval Tavrot va Injil kabi ilohiy kitoblar berilgan yahudiy va nasroniylarning vaqt oʻtishi bilan oyatda tasvirlanganidek qalblarini mogʻor bosib, qattiq boʻlib qolgan.)","Bilinglarki, albatta Alloh oʻlik yerni tiriltirur. Darhaqiqat, sizlarga oyatlarni bayon qildik, shoyadki aql yuritsangizlar.","Albatta, sadaqa qiluvchi erkagu ayol hamda Allohga qarzi hasana beruvchilarga (savob) koʻpaytirib berilur. Ularga karamli ajr ham bor.","Allohga va Uning Paygʻambarlariga iymon keltirganlar, ana oʻshalar, siddiqlardir. Va Robbilari huzuridagi shohidlardir. Ularning ajrlari va nurlari bor. Kufr keltirganlar va oyatlarimizni yolgʻonga chiqarganlar, ana oʻshalar, doʻzax egalaridir. (Ushbu oyatda Allohga va Uning Paygʻambarlariga iymon keltirganlar, siddiqlar, deb atalmoqda. «Siddiq» aslida soʻziga, eʼtiqodiga va amaliga sodiq kishilarning sifatidir. Ular fazl va martabada Paygʻambarlardan keyin turadilar. Ularnin hammalariga ulugʻ ajr va qiyomat zulmatida yoʻllarini yoritib boradigan nur bordir. Kofirlarga esa doʻzax roʻpara qilinadi.)","Bilingki, albatta, bu dunyo hayoti oʻyin, koʻngil ermagi va zeb-ziynatdan, oʻzaro faxrlanishdan, mol-mulkni va bola-chaqani koʻpaytirishdan iboratdir. Xuddi oʻsimligi dehqonlarni ajablantirgan yomgʻirga oʻxshaydir. Keyinroq bu oʻsimliklar quriydir va sargʻayganini koʻrasan. U soʻngra xas-choʻpga aylanib ketadir. Oxiratda esa qattiq azob bor, Allohdan magʻfirat va rozilik bor. Bu dunyo hayoti gʻururga ketgazuvchi matodan oʻzga hech narsa emas. (Yaʼni, bu dunyo hayoti shunday bir yomgʻirga oʻxshaydiki, u yoqqandan soʻng chiqqan nabotot dehqonlarni hayratga soladi, zavqlantiradi. Aslida esa bu hol oʻtkinchidir. Yaʼni, oʻsimliklar tezda quriydi. rangi sargʻayadi va qurib, qovjirab, uqalanib ketadi. Ha, bu dunyo hayoti ham shu kabi aldamchidir. Shu bilangina ovunib qolmasligi kerak. Chunki oxiratda kofirlarga qattiq azob, moʻminlarga esa Allohning magʻfirati va roziligi bor. Albatta, bu gaplar tarki dunyo qilishga, hamma narsadan yuz oʻgirishga chaqiriq emas. Balki mezon va oʻlchovlarni toʻgʻri yoʻlga solishga, oʻtkinchi hoy-havasdan ustun boʻlishga daʼvat, xolos.)","Robbingizning magʻfiratiga va Allohga hamda Uning Paygʻambarlariga iymon keltirganlar uchun tayyorlangan, kengligi osmonu yerning kengligicha boʻlgan jannatga musobaqalashing. Ana oʻsha Allohning fazli. Kimga xohlasa beradi, Alloh ulugʻ fazl egasidir. (Qurʼoni karim nazarida, musobaqa bu dunyo hayotining oʻtkinchi hoy-havaslariga, boylikka, oʻyin-kulguga emas, balki Allohning magʻfiratiga va jannatga eltuvchi yaxshi amallarga qaratilishi kerak.)","Biror musibatni paydo qilmasamizdan oldin u Kitobda bitilgan boʻlur, aks holda yer yuzida va oʻz shaxslaringizda sizga biror musibat yetmas. Albatta, bu ish Alloh uchun osondir.","Toki, ketgan narsaga qaygʻurib, kelgan narsadan xursand boʻlmasligingiz uchun, Alloh barcha dimogʻdor va maqtanchoqlarni suymaydir.","Ular baxildirlar va kishilarni ham baxillikka buyuradilar. Kim yuz oʻgirsa, bas, Alloh behojat va maqtalgan zotdir. (Ular baxillik qilib, kishilarni ham baxillikka buyursalar-da, Allohga hech zarari yoʻq, chunki Alloh behojat, boy va maqtalgan zotdir.)","Darhaqiqat, Biz Paygʻambarlarimizni ravshan(narsa)lar ila yubordik va ular ila kitob, hamda odamlar adolatda turishlari uchun mezon tushirdik. Va temirni tushirdik - unda katta kuch-quvvat va odamlar uchun manfaatlar bor. Alloh kim Oʻziga va Paygʻambarlariga gʻoyibona yordam berayotganini bilishi uchun. Albatta, Alloh kuchli va azizdir. (Oyati karimada Alloh subhanahu va taolo Oʻz Paygʻambarlariga yubordim deyayotgan ravshan, ochiq-oydin narsalar - moʻjizalar, shariat ahkomlari, oyatlar boʻlishi mumkin. Ushbu oyat tushgan vaqtidayoq musulmonlarni temirga eʼtibor berishga, undan samarali foydalanishga daʼvat qilgan edi. Temirning odamlar uchun manfaatini sanab tugatib boʻlmaydi. Oyatning oxiridagi jumlada bir-ikki nozik maʼno bor. Jumladan, temirdan yasalgan asboblarni ishlatib, Allohga va Uning Paygʻambarlariga yordam beruvchilarni bilishi uchun, degan ishora. Maʼlumki, Alloh ilmining chegarasi yoʻq - hamma narsani roʻy berishidan avval bilib turadi. Lekin bu oyatdagi «bilishi»ni yuzaga chiqarishi, xaloyiqqa bildirishi deb tushunmoq kerak. Shuningdek, «gʻoyibona» soʻzi ham Allohni va Uning Paygʻambarlarini koʻrmasdan turib ularni diniga yordam beringlar, deb sharhlanadi.)","Darhaqiqat, Nuh va Ibrohimni Paygʻambar qilib yubordik hamda Paygʻambarlikni va kitobni ikkovlarining zurriyotiga xos qildik. Ular orasida hidoyat topganlar bor, lekin ularning koʻplari fosiqlardir.","Soʻngra ularning ortidan Paygʻambarlarimizni ketma-ket yubordik va Isyo ibn Maryamni ham ortlaridan yubordik hamda unga Injilni berdik. Unga ergashganlarning qalblariga mehribonlik va rahmdillikni soldik. Rohiblikni oʻzlari chiqarib oldilar, Biz buni ularga farz qilmagan edik, faqat oʻzlari Allohning roziligini tilab qildilar, lekin haqiqiy rioyasini qila olmadilar. Bas, ulardan iymon keltirganlariga ajrlarini berdik, lekin ularning koʻpi fosiqlardir. (Rohiblik, tarkidunyochilikdan iborat boʻlib, oʻrislarda, monaxlik, deyiladi. Monaxlikni ixtiyor qilgan erkak erkaklar monastirida, ayol esa ayollar monastirida, oila qurmay, dunyoni tark etib hayot kechiradilar. Qurʼoni karim bunday rohiblikni Alloh Iyso alayhissalomga ergashuvchilarga buyurmaganini, balki ular oʻzlari bidʼat sifatida keyinchalik oʻylab topib odat qilishganini eslatmoqda.)","Ey iymon keltirganlar! Allohga taqvo qilinglar va Uning Paygʻambariga iymon keltiringlar. U zot Oʻz rahmatidan sizlarga ikki hissa beradir va sizlarning yurishingizga nur beradir hamda sizlarni magʻfirat qiladir. Alloh kechiruvchi, rahmli zotdir.","Toki kitob ahllari Allohning fazlidan hech narsaga qodir emasliklarini, fazl Allohning qoʻlida boʻlib, xohlagan kishisiga berishini bilsinlar. Alloh ulugʻ fazl egasidir. (Yahudiy va nasroniylar vahiy, Paygʻambarlik va ilohiy kitoblar faqat bizga xos, oʻzgalarga berilmaydi, deb faxrlanishar edi. Alloh taolo ularning bu daʼvolarini rad qilib, fazl oʻzining qoʻlida ekanini, kimga xohlasa, shunga ravo koʻrishini, shu jumladan, arablardan boʻlgan Muhammad alayhissalomga berishini taʼkidlamoqda.)"],"58":["Albatta, Alloh Sen bilan oʻz eri haqida tortishayotgan va Allohga shikoyat qilayotgan (ayol)ning soʻzini eshitdi. Ha, Alloh ikkovingizning gaplashuvingizni eshitmoqda. Albatta, Alloh eshituvchi va koʻruvchidir. (Yaʼni, Alloh taolo uy ichida, Paygʻambar alayhissalom bilan pichirlashib gaplashgan Havla Binti Saʼlabaning soʻzlarini eshitgandek, dunyoda boʻlayotgan barcha ishlarni koʻrib turadi. Uning uchun hech bir narsa maxfiy emasdur.)","Sizlardan oʻz xotinlaridan zihor qiladiganlar (bilib qoʻysinlarki), u(xotin)lar onalari emas. Tuqqan onalaridan oʻzga hech kim ularga ona emaslar. Va, albatta, ular inkor qilingan va gʻirt yolgʻon soʻzlarni aytarlar. Va, albatta, Alloh kechiruvchi va magʻfirat qiluvchidir.","Xotinlaridan zihor qilganlar oʻz aytganlaridan qaytsalar, (qayta) qoʻshilmaslaridan avval bir qul ozod qilsinlar. Bu (hukm) vaʼzlanishingiz uchundir. Alloh qilayotgan ishlaringizdan xabardordir.","Kim (qul) topmasa, bas (qayta) qoʻshilmasdan avval ikki oy ketma-ket roʻza tutsin. Kim (roʻzaga) qodir boʻlmasa, oltmish miskinni toʻygʻazsin. Bu (hukm) Allohga va Uning Rasuliga iymon keltirishingiz uchun. Va bu(hukm)lar Allohning chegaralaridir. Va (undan chiqqan) kofirlarga alamli azob bor.","Albatta, Allohga va Uning Paygʻambariga dushmanlik qiladiganlar, ulardan avvalgilar xor boʻlganidek, xor boʻlurlar. Holbuki batahqiq Biz ochiq-oydin oyatlarni tushirib qoʻyganmiz. Va kofirlarga xorlovchi azob bor.","Alloh barchalarini qayta tiriltiradigan kunda, ularga qilgan ishlarining xabarini berur. Alloh hisoblab turgan, ular esa unutganlar. Holbuki Alloh har bir narsaga shohiddir.","Albatta, Alloh osmonlaru yerdagi barcha narsalarni bilishini anglamadingmi? Agar uchtaning sirli soʻzlashuvi boʻlsa, albatta, U zot toʻrtinchidir. Beshta boʻlsalar, U zot oltinchidir, bundan oz boʻlsa ham, koʻp boʻlsa ham va qayerda boʻlsalar ham, albatta, Alloh ular bilandir. Soʻng qiyomat kunida ularga qilgan ishlaridan xabar beradir. Albatta, Alloh har bir narsani biluvchidir.","Sirli soʻzlashuvdan qaytarilganlarni koʻrmadingmi?! Man etilgan ishga yana qayturlar, gunoh va dushmanlik-la va Paygʻambarga osiy boʻlib, sirli soʻzlashurlar. Va huzuringga kelsalar, sen bilan Alloh oʻrgatmagan tarzda soʻrashurlar. Va ichlarida, shu gapimiz uchun Alloh bizni azoblamasa edi, derlar. Ularga jahannam kifoyadir, unga kirurlar. U qandoq ham yomon joy! (Yahudiylar har bir narsada hiyla ishlatib, Rasulullohga va musulmonlarga yomonlik qilishning payida boʻlardilar. Hattoki ular salomlashish paytida ham «As-Salomu alaykum (sizga tinchlik boʻlsin)» deyish oʻrniga, «As-Somu alaykum (sizga oʻlim boʻlsin)» deb sezilmaydigan qilib aytishardi.)","Ey iymon keltirganlar! Qachon sirli suhbat qilsangiz, gunoh, dushmanlik va Paygʻambarga maʼsiyatga sirli suhbat qilmangiz. Yaxshilik va taqvoga sirli suhbat qilingiz. Huzuriga toʻplanib boradiganingiz Allohga taqvo qilingiz. (Musulmonlar oʻzaro suhbatlarida doimo bir-birlarini yaxshilikka va taqvoga chorlashlari lozim. Afsuski, hozir bu qurʼoniy taʼlimotlar bizning oramizdan yoʻqolgan. Oʻzaro suhbatlar yolgʻon, boʻhton, tuhmat va gʻiybatdan iborat boʻlib qolmoqda. Bu esa musulmonlarning na odobiga, na shaʼniga toʻgʻri keladi.)","Albatta, iymonlilarni ranjitish uchun qilingan sirli suhbat shaytondandur, Allohning izni bilan qilingan sirli suhbatgina ularga hech zarar yetkazmas. Moʻminlar Allohning Oʻziga tavakkal qilsinlar. (Odatda ikkita-ikkita yoki koʻproq boʻlib olib, jamoatdan ajrab pichir-pichir qilib gaplashish koʻrib turganlar qalbiga shubha soladi. «Bizdan berkitib bular nimaningdir maslahatini qilishayotgan ekan», degan xayolga olib boradi. Buning ustiga, shayton: «Sening zararingga maslahat qilishyapti, boʻlmasa oshkora gapirishardi», deb vasvasa qiladi. Shunday qilib, qarabsizki, jamiyat aʼzolari ichida bir-biriga ishonchsizlik yuzaga keladi.)","Ey iymon keltirganlar! Agar sizlarga majlislarda siljibroq oʻtiring, deyilsa, bas, siljing, agar turing deyilsa, turing. Alloh sizlardan iymon keltirganlarni va ilmga berilganlarning darajalarini koʻtarur. Alloh nima qilayotganingizdan xabardordir. (Musulmonlar Paygʻambar alayhissalom majlislarida iymon va ilm olardilar. Shuning uchun ham hamma katta qiziqish bilan, iloji boricha, u zotga yaqinroq oʻtirishni xohlardi. Ushbu oyat nozil boʻlgach, ilm olish majlisini hammaga keng targʻib qilish zarurligi eslatilib, majlis ahlining barchasiga joy berishni yoʻlga qoʻyishga daʼvat etildi.)","Ey iymon keltirganlar! Agar Paygʻambar bilan sirli suhbat qilmoqchi boʻlsangiz, sirli suhbatingizdan avval sadaqa bering. Shundoq qilmogʻingiz oʻzingiz uchun yaxshiroqdir va (qalbingiz uchun) pokroqdir. Agar (sadaqa) topmasangiz, albatta Alloh kechiruvchi va rahmdildir. (Paygʻambar alayhissalom bilan munojot (suhbat) qilishdan avval sadaqa berishga daʼvat etilgan buyruqning bir necha hikmatlari bor. Paygʻambar alayhissalomning vaqtlarini bekor ketkazmaslik; kambagʻallarga foyda boʻlishi; muxlis va munofiqlarni ajratish va hokazo.)","Sizlarga sirli suhbatingizdan avval sadaqa berish ogʻir keldimi. Agar bajarmasangiz, (mayli) Alloh avf qildi. Bas, namoz oʻqinglar va zakot beringlar. Va Allohga va Uning Paygʻambariga itoat qilinglar. Alloh qilayotgan ishlaringizdan xabardordir. (Alloh taolo avvalgi hukmini bekor qilmasa yoki undan ham ogʻirroq hukmni joriy qilsa boʻlaverar edi. Lekin Alloh taolo oʻzini unutib qoʻygan baʼzi kishilarni ogohlantirib boʻlgach, yana koʻpchilikka rahm qilib, avvalgi Oʻz hukmini bekor qildi.)","Allohning gʻazabiga duchor boʻlgan qavmni doʻst tutganlarni koʻrmaysanmi? Ular sizlardan ham emas, ulardan ham emas. Bilib turib, yolgʻonga qasam ichurlar.","Alloh ular uchun shiddatli azobni tayyorlagan. Ularning qilayotgan ishlari naqadar yomon!","Qasamlarini oʻzlari uchun toʻsiq qilib oldilar. Bas, Allohning yoʻlidan toʻsdilar. Ular xorlovchi azob bor!","Mollari ham, bolalari ham ulardan Alloh(azobi)dan hech narsani qaytara olmas. Unday kishilar doʻzax ahlidurlar. Ular unda abadiy qolurlar.","Alloh ularning barchasini qayta tiriltiradigan kunda xuddi sizlarga qasam ichganlaridek, Unga ham qasam icharlar, va biror narsaga erishamiz, deb oʻylarlar. Ayo, ogoh boʻling, ular, ha, ular yolgʻonchidirlar.","Shayton ularni egallab olgan va Allohning zikrini unutdirgan. Ana oʻshalar, shayton firqasidirlar. Ayo, ogoh boʻlinglar, shayton firqasi, ha, oʻshalar, yutqazuvchidirlar. («Bandani shayton egallab olishining alomati shulki, uni sirtini yaltiroq qilish bilan mashgʻul qilib qoʻyadi. Yaxshi yeyish, yaxshi ichimlik ichish, yaxshi liboslar kiyishga urintirib, Allohning neʼmatlariga shukr keltirishdan chalgʻitadi. Tilida yolgʻon, boʻhton va gʻiybatni gapiradi-yu, Allohning zikrini unutadi».)","Albatta, Allohga va Uning Rasuliga dushmanlik qiluvchilar, ana oʻshalar, eng xorlar ichidadir.","Alloh, Men va Mening Rasullarim gʻalaba qilamiz, deb hukm qilgan. Albatta, Alloh quvvatli va gʻolibdir.","Allohga va oxirat kuniga iymon keltirgan qavmning Allohga va Uning Rasuliga dushmanlik qiluvchilarga doʻstlik qilganlarini topmaysan. Hatto u(dushman)lar oʻz otalari, bolalari, aka-ukalari yoki qarindoshlari boʻlsa ham. Alloh undoq kishilarning qalblarida iymonni sobit qilgan, ularni Oʻz huzuridan bir ruh bilan qoʻllagandir. Va ularni ostidan suvlar oqib turgan jannatlarga kiritadir. Unda abadiy qolurlar. Alloh ulardan rozi boʻladir. Ular Allohdan rozi boʻladir. Ana oʻshalar, Allohning firqasidirlar. Ayo, ogoh boʻlinglar, albatta, Allohning firqasi, ha, oʻshalar yutuvchilardir. (Allohnning rizoligini topish... Kimki yaratgan Robbisi rizoligini topmas ekan, mabodo uning iymoni saqlab qolmasa, bu yolgʻonchi dunyoda umri aldanish bilan, oxiratda esa faqat azobga duchor boʻlish bilan intiho topadi.)"],"59":["Osmonlardagiyu yerdagi barcha narsalar Allohni poklab yod etdi. U zot aziz va hikmatli Zotdir.","U zot ahli kitobdan boʻlgan kofirlarni oʻz diyorlaridan birinchi hashr uchun chiqardi. Ularni chiqadi deb oʻylamagan edingiz. Oʻzlari ham qoʻrgʻonimiz bizni Alloh(azobi)dan saqlab qoladir, deb oʻylashardi. Alloh ular oʻylamagan tarafdan oldi va ularni qalbiga qoʻrqinch soldi. Uylarini oʻz qoʻllari bilan va moʻminlarning qoʻllari bilan buza boshladilar. Ibrat oling, ey aql egalari! (Yahudiylar qoʻrgʻonlariga ishonib, bizga hech qanday yomonlik yetishi mumkin emas, deb xotirlari jam edi. Lekin Alloh taolo ular oʻylamagan, xayollariga kelmagan ishni amr qildi. Qoʻrgʻonlar joyida qolib, yahudiylarning qalblaridan putur ketdi. Alloh ularning qalblariga qoʻrqinch va vahima soldi. Ana shunda, biz koʻchib ketsak, bu qoʻrgʻonlar musulmonlarga qolmasin, deya uylarini oʻzlari buza boshladilar. Musulmonlar qamal davomida binolarga tashqaridan putur yetkazdi. Oqibatda mustahkam qoʻrgʻonlar vayron boʻldi. Bu voqea aqli bor har bir kishiga oʻrnak boʻlarlik bir ogohlantirishdir. Demak, bandasi qanchalik xom xayol qilmasin, Xudoning buyurgani boʻladi.)","Mabodo Alloh ularga koʻchishni yozmaganda ham bu dunyoda ularni azoblar edi. Ularga oxiratda doʻzax azobi bordur. (Inson oxiratda bu dunyoda qilgan gunoh amallariga yarasha jazo olishi muqarrar. Yahudiylarning koʻchirilishi, ular uchun nisbatan yengil azobdir.)","Unday boʻlishi, ular Allohga va Uning Rasuliga xilof qilganlari uchundir. Kimki Allohga xilof qilsa (unutmasinki), albatta, Alloh - azobi zoʻr zotdir.","Sizning xurmoni kesishingiz yoki aslida tik qoldirganingiz faqat, Allohning izni bilan va buzgʻunchilarni xorlashi uchun boʻldi. (Xurmo daraxtining eng yaxshi navi «liynatin» deb ataladi. Oyat tafsiridla taʼkidlanganidek, baʼzi xurmo daraxtlarini kesib, baʼzilarining qoldirilishi buzgʻunchilik uchun emas, balki Allohning izni bilan boʻldi. Islom shariatida urush paytida ham oʻsimlik va hayvonot dunyosiga zarar keltirish qatʼiyan man qilinadi. Bu boqiy hukmdir. Lekin Bani Naziyr hodisasida Alloh taolo Oʻzi ularni baʼzi xurmo daraxtlarini kesib oʻt qoʻyishga izn bergan.)","Alloh Oʻz Rasuliga ulardan qaytarib bergan narsaga sizlar ot yoki tuya choptirib bormadingiz. Lekin Alloh Oʻz Paygʻambarini xohlagan kimsaning ustidan, gʻolib qiladir. Alloh har bir narsaga qodirdir. (Bu oyatda Alloh taolo qoʻlga tushgan mol-mulk uchun musulmonlar tuya minib, ot choptirib qiynalmaganlarini, bu narsalarni Paygʻambariga Allohning Oʻzi, Oʻz qudrati bilan berganini eslatmoqda.)","Alloh Oʻz Rasuliga shahar ahlidan qaytarib bergan narsa. Allohgadir va Uning Rasuliga va yaqin qarindoshlariga, yetimlarga va miskinlarga va koʻcha oʻgʻillarigadir. Sizlardan boylaringiz orasida aylanadigan narsa boʻlib qolmasligi uchun. Paygʻambar sizga nimani bersa, oʻshani olinglar va nimadan qaytarsa, oʻshandan qaytinglar. Allohdan qoʻrqinglar. Albatta, Alloh azobi shiddatli zotdir. ( Alloh taolo yahudiylar qoldirgan mollarni «qaytarilgan mol» deb nomlayapti. Aslida, mol Allohniki, Bani Naziyrga bergan molini endi Paygʻambariga qaytardi. Aslida oʻljalarni jihodda qatnashgan mujohidlarga taqsimlanadi. Ammo bu safar oʻlja urushsiz qoʻlga tushgani uchun ushbu va keyingi oyatda zikri kelgan: Alloh, Allohning Rasuli, Paygʻambar alayhissalomning yaqin qarindoshlari, safarda ogʻir ahvolga tushganlar, yetim, miskin va faqir muhojirlarga taqsimlanmoqda.)","Faqir muhojirlargaki, ular oʻz diyorlaridan va mol-mulklaridan judo qilingan edilar, (ular) Allohdan fazl va Uning roziligini umid qilular. Allohga va Uning Rasuliga yordam berurlar. Ana oʻshalar sodiqlardir.","U(muhojir)lardan avval bu joyda yashagan va iymonga (ixlos qilganlar). Oʻzlariga hijrat qilib kelganlarni sevadirlar va u(muhojir)larga berilgan narsalarga qalblarida hasad qilmaslar. Va gar oʻzlarining hojatlari boʻlsa ham, (ularni) oʻzlaridan ustun qoʻyarlar. Kim oʻz nafsining baxilligidan saqlansa, undoq kishilar, ha, oʻshalar yutuvchilardir. (Madinalik musulmonlar Paygʻambar alayhissalomga va muhojirlarga yordam berganlari uchun «Ansorlar» deb nomlanganlar. Ushbu oyat ansorlarning insoniyat tarixida misli koʻrilmagan saxovatlariyu odamgarchiliklarini vasf qilmoqda.)","Ulardan keyin kelganlar: «Ey Robbimiz, bizni va bizdan avval iymon bilan oʻtgan birodarlarimizni magʻfirat qilgin, qalbimizda iymon keltirganlarga nafrat solmagin, ey Robbimiz, albatta, sen shafqatli va mehribonsan», derlar. (Oyati karimada Islom ummatining avvali bilan oxirini bogʻlab turuvchi ip namoyon boʻlmoqda. Keyin kelgan musulmon avlodi, kim boʻlishidan qatʼiy nazar, oʻzidan avval oʻlib ketganlarni yaxshilik bilan eslab, ularning haqiga xayrli duolar qiladilar. Oʻlganlarni soʻkish, ularni xorlash musulmonlarga munosib ish emas. Islom ummatining oʻligiyu, tirigi, avvaliyu oxiri bir xilda eʼzozga loyiqdir.)","Nifoq qilganlarning ahli kitobdan boʻlmish kufr keltirgan oʻz birodarlariga: «Agar sizlar chiqarilsangiz, biz ham sizlar bilan chiqamiz, sizni quyib hech qachon hech kimga itoat qilmasmiz va mabodo sizlarga urush qilinsa, albatta yordam berurmiz», deyishlarini koʻrmaysanmi? (Munofiq lar ahli kitob boʻlmish yahudiy qabilasi Bani Naziyrga kelib: «Muhammaddan qoʻrqmanglar, biz sizlar bilan birgamiz. Mabodo oʻz yurtlaringdan chiqib ketishga majbur boʻlsalaringiz, biz ham sizga qoʻshilib chiqib ketamiz. Agar Muhammad sizga qarshi urush qiladigan boʻlsa, biz sizlarga yordam beramiz», deyishgan.)","Albatta agar u(yahudiy)lar chiqarilsalar, ular birga chiqmaslar. Va, albatta, agar u(yahudiy)larga urush qilinsa, (munofiqlar) ularga yordam bermaslar. Bordiyu yordam berganlarida ham, ortlariga qarab qocharlar va alar yordamsiz qolarlar.","Albatta, ularning qalblariga Allohdan koʻra sizlar koʻproq qoʻrqinchli tuyulasizlar. Chunki ular yaxshi anglamaydigan qavmdirlar. (Munofiqu kofirlar Allohdan koʻra moʻmin-musulmonlardan koʻproq qoʻrqadilar. Agar Allohning Oʻzidangina qoʻrqanlarida edi, munofiq ham, kofir ham boʻlmas edilar.)","Sizlarga qarshi uyushib ochiq urush qila olmaslar, balki qoʻrgʻon bilan oʻralgan qishloqlarda yoki devorlar ortiga bekinib olib urush qilurlar. Oʻz oralarida adovatlari shiddatli. Ularni bir deb oʻylaysan. Holbuki, qalblari tarqoqdir. Bu, ularning aql yuritmaydigan qavm ekanliklaridandir. (Tabiiyki, ixtiloflar tufayli istaklar, maqsadlar, firqalar va shiorlar koʻpayadi. Bu esa har bir millatni halokatga olib boradi.)","Bu xuddi yaqinda oʻz qilmishlarining oqibatini tatib koʻrganlarga oʻxshashdir. Va ularga (oxiratda) alamli azoblar bor. (Bu oyatda, Bani Naziyr ahli ham xiyonat, isyon tufayli xuddi ulardan avvalgi Bani Qayniqoʼ ahli tushgan holga tushganlari eslatilmoqda.)","Bu xuddi Shayton insonga, kofir boʻl, degan paytga oʻxshaydir. U (inson) kufr keltirganda esa, sen bilan mening ishim yoʻq, men olamlar Obbisi-Allohdan qoʻrqaman, dedi.","Bas, ularning oqibatlari bir. Albatta, ikkovlari ham doʻzaxda boʻlurlar, u yerda abadiy qolurlar. Va bu zolimlarning jazosidir. (Bani Naziyr qabilasi ushbu jonli misol bilan xotima topadi.)","Ey iymon keltirganlar! Allohga taqvo qilinglar! Har kim ertalik uchun nima taqdim qilganiga nazar solsin. Allohga taqvo qilinglar! Albatta, Alloh nima qilayotganingizdan xabardordir. (Qiyomat nisbatan juda yaqin vaqt, shuning uchun ham u «erta» deyiladi. Demak, har bir inson qiyomat kuni uchun nima ish qilganini oʻylab qoʻyishi kerak.)","Allohni unutganlarga oʻxshagan boʻlmanglar. U zot ularga oʻz shaxslarini unutdirdi. Ana oʻshalar, fosiqdirlar. (Allohni unutgan odam bu dunyoda uni oliy maqom bilan bogʻlab turuvchi aloqani yoʻqotadi. Uni boshqa jonzotlardan ajratib turadigan oliy maqsaddan mahrum boʻladi. Va nihoyat, oʻzining insonligini unutadi.)","Doʻzax egalari va jannat egalari teng boʻlmaslar. Jannat egalari, oʻshalar yutuqqa erishuvchilardir.","Agar ushbu Quʼonni togʻga tushirganimizda edi, uning Allohdan qoʻrqqanidan titrab-qaqshab va parchalanib ketganini koʻrar eding. Ushbu misollarni odamlarga keltirurmiz, shoyadki ular fikr yuritsalar.","U Alloh Undan oʻzga iloh yoʻq zotdir. U gʻoyibni ham, oshkorni ham biluvchidir. U mehribon va rahmlidir.","U Alloh, Undan oʻzga iloh yoʻq. U - Malik, U-Quddus, U-Salom, U- Moʻmin, U- Muhaymin, U-Aziz, U-Jabbor, U-mutakabbirdir. Alloh Unga shirk keltirayotgan narsalardan pokdir. (Malik-haqiqiy egadir, Undan oʻzga ega yoʻq. Shuning uchun bandalar faqat unga qul boʻladilar. Quddus-barcha ayblardan xoli, noloyiq sifatlardan pok. Mutlaq muqaddaslik va mutlaq poklik Allohning Oʻzigagina xosdir. Salom-nuqsonlardan salomat, shuningdek, tinchlik-xotirjamlik va rohat beruvchi zot. Alloh «Salom» sifati ila bandalarga tinchlik, omonlik, xotirjamlik ato qiladi. Moʻmin-iymon va omonlikni beruvchi. Muhaymin-hamma narsani qamrab oluvchi, yaʼni, Alloh bandalarning barcha holatlarining guvohi boʻlib turadi, undan hech narsa maxfiy qolmaydi. Aziz-barchaning ustidan gʻolib. Jabbor - oliy qadar, ulugʻ, Uning oldida oʻzgalar oʻzini xor tutadi. Mutakabbir-kibiryosi va ulugʻligi mubolagʻali zot.)","U Alloh Xoliq, Bariʼu, Musavvirdur. Barcha goʻzal ismlar Unikidir. Osmonlaru yerdagi barcha narsalar Uni poklab yod etarlar. Yana U Aziz va Hakimdir. (Xoliq-yaratuvchi. Bariʼu-yoʻqdan bor qiluvchi. Musavvir-maxluqotlarning suvratini shakllantiruvchi zot. Dunyodagi barcha chiroyli ismlar Allohnikidir. Hadisi sharifda Allohning toʻqson toʻqqizta chiroyli ismi zikr qilingan. Osmonda boʻlsin, yerda boʻlsin, dunyodagi barcha narsalar Alloh taoloni poklab yod etadi, lekin biz ularning tasbihini tushunmaymiz. U Alloh gʻolibdir va hakim-barcha ishlarni hikmat bilan qiluvchi zotdir.)"],"60":["Ey iymon keltirganlar! Agar Mening yoʻlimda jihod qilib va roziligimni soʻrab chiqqan boʻlsangiz, Mening dushmanlarimni va oʻzingizning dushmanlaringizni doʻst tutmanglar. Sizlar ularga doʻstlik qilasizlar, ular boʻlsa sizlarga kelgan haqqa kufr keltirarlar. Robbingiz boʻlmish Allohga iymon keltirganingiz uchun Paygʻambarni va sizni haydab chiqararlar. Siz ularga doʻstlik qilib sir aytasiz. Holbuki, Men nimani maxfiy tutganingizniyu nimani oshkor qilganingizni juda yaxshi bilurman. Oralaringizda kim oʻsha ishni qilsa, toʻgʻri yoʻldan adashgan boʻladir. (Allohning va musulmonlarning dushmanlariga doʻstlik qiluvchi kishilar bilib qoʻysinlarki, ular musulmonlarga kelgan haqqa - Qurʼon va Islomga kofir boʻlganlar. Bu ham yetmaganidek, Paygʻambarning va moʻminlarning iymonlarini ayb hisoblab, oʻz diyorlaridan haydab chiqarganlar. Shuning uchun u mushriklarni doʻst tutmaslik kerak. Birov bilmaydi deb ularga sir aytmang, Alloh taolo siru oshkor barcha amallaringizni bilib turuvchi zotdir.)","Agar ular sizdan ustun kelsalar, sizga dushman boʻlarlar va sizlarga qoʻllariyu tillarini yomonlikla choʻzar lar. Va sizlarning kofir boʻlishlaringizni xohlarlar.","Qarindoshlaringiz va farzandlaringiz sizga hech manfaat bera olmaslar. Qiyomat kuni U zot oralaringizni boʻlur. Alloh nima qilayotganingizni koʻrib turguvchidir.","Haqiqatda, sizlarga Ibrohim va u bilan birga boʻlganlarda yaxshi oʻrnak bor. Ular, biz sizdan va siz ibodat qilayotgan narsadan bezormiz, sizga kufr keltirdik, endi toki yagona Allohga iymon keltirmagunlaringizcha oramizda doimiy adovat va kuchli nafrat paydo boʻldi, dedilar. Magar Ibrohimning otasiga qarata, albatta sen uchun istigʻfor aytaman, sendan Alloh(azobi)dan biror narsa qaytarishga molik emasman, degan soʻzi mustasno. Ey Robbimiz, faqat Senga tavakkal qildik, faqat Sengagina qaytdik va qaytib boradigan joy ham faqat Senginadir. (Ibrohim Paygʻambar otalariga rahmlari kelib: «Albatta, sen uchun istigʻfor aytaman», deya vaʼda berganlar. Lekin otaning iymonga kelmasligiga koʻzlari yetgach, «Sendan Allohning azobini qaytarishga molik emasman», deb qoʻshib qoʻyganlar.)","Ey Robbimiz, bizni kofirlarga fitna qilib qoʻymagin va bizni kechirgin. Ey Robbimiz, albatta, Sen, Oʻzing azizu hakimsan.","Albatta, kimning Allohdan va qiyomat kunidan umidi boʻlsa, shular uchun ularda yaxshi oʻrnak bor edi. Lekin kim yuz oʻgirsa, Alloh behojat, maqtalgan zotdir.","Shoyadki, Alloh sizlar bilan ular ichidagi dushmanlaringiz oʻrtasida doʻstlik paydo qilsa, Alloh qodirdir. Alloh kechiruvchi va rahmdildir. (Alloh taolodan «shoyadki» kalimasi sodir boʻlsa, albatta, voqelikda sodir boʻlishi shart. Bu vaʼda Makkai mukarrama fath boʻlishi bilan amalga oshdi. Mushriklar toʻp-toʻp boʻlib Allohning diniga kirdilar va musulmonlar bilan doʻst-birodar boʻldilar. Qalblaridagi dushmanlik tuygʻulari ham koʻtarildi.)","Alloh sizlarni diniy urush qilmagan va diyorlaringizdan chiqarmaganlarga yaxshilik va adolatli muomala qilishdan sizlarni qaytarmas. Albatta, Alloh adolat qiluvchilarni yaxshi koʻradir.","Albatta Alloh sizlarni diniy urush qilganlar, diyoringizdan chiqarganlar va chiqarilishingizga yordam berganlarga doʻstlik qilishdan qaytarur. Ularni doʻst tutganlar, ana oʻshalar, zolimlardir. (Alloh taolo bu oyati karimada moʻmin-musulmonlarni boshqa millat va diyonat vakillari bilan agar ular musulmonlarga diniy adovat ila urush qilmasa va ularni siquvga olib oʻz diyorlaridan chiqarib yuborishga urinmasa, yaxshi aloqada boʻlishga buyurmoqda va ularga nisbatan adolatli boʻlishni taʼkidlamoqda. Ammo kimki musulmonlarga diniy adovat tufayli urush ochsa, ularni diyorlaridan chiqarsa yoki dushmanlariga ularni diyorlaridan chiqarishda yordam bersa, albatta, unday kishilarni doʻst tutib boʻlmaydi. Bu ham ayni adolatdir.)","Ey, iymon keltirganlar! Agar sizlarga moʻminalar hijrat qilib kelsalar, ularni imtihon qilib koʻringlar. Alloh ularning iymonini bilguvchidir. Bas, moʻminaliklarini bilsangiz, ularni kofirlarga qaytarib yubormang. Bu (ayol)lar ularga halol emas va ular ham bularga halol boʻlmaslar. Va u(kofir)larga nafaqa qilgan narsalarini (qaytarib) beringlar. Va u(ayol)larni nikohlab olsangiz, agar mahrlarini bersangiz, sizlarga gunoh boʻlmas. Kofir xotinlaringizni nikohlaringizda ushlab turmanglar. Nafaqa qilgan narsalaringizni soʻranglar, ular ham nafaqa qilgan narsalarini soʻrasinlar. Bu sizlarga Allohning hukmidir. Orangizda hukm qiladir. Alloh bilguvchi va hikmatlidir. (Dushman tarafdan kelgan har bir kishini ham quchoq ochib kutib olinavermaydi. Chunki, dushman josus yuborishi ham mumkin. Shuning uchun Alloh taolo imtihon qilib koʻrishni amr qilmoqda. Ushbu oyati karima tushguncha musulmonlardan baʼzilari mushrika xotinlari bilan birga yashayotgan edilar. Oyat tushgandan soʻng ularni taloq qildilar.)","Agar ayollaringizdan birortasi kofirlarga oʻtib ketsa, urushda tushirilgan oʻljadan xotini ketib qolganga, u nafaqa qilgan miqdorni beringiz. Oʻzingiz iymon keltirgan Allohdan qoʻrqing.","Ey Nabiy! Agar moʻminalar senga Allohga hech narsani shirk keltirmaslik, oʻgʻrilik qilmaslik, zino qilmaslik, bolalarini oʻldirmaslik, qoʻllari va oyoqlari orasidan boʻhton toʻqib keltirmaslik va senga yaxshilik ishda isyon qilmaslikka bayʼat qilib kelsalar, ularning bayʼatini qabul qil. Va Allohdan ularning gunohini kechishni soʻra. Albatta, Alloh gunohlarni kechiruvchi va mehribondir. (Ahdnoma (bayʼat) berish - Islom rahbariga oʻzining sodiqligini bayon qilib vaʼda berishdir. Paygʻambar alayhissalom er musulmonlardan avvallari ahdnoma olgan edilar. Ayollardan esa ushbu oyat tushgandan soʻng ola boshlaganlar.)","Ey iymon keltirganlar! Allohning gʻazabiga uchragan qavmni doʻst tutmanglar. Kofirlar qabr egalaridan umid uzganlaridek, ular ham oxiratdan umid uzganlar."],"61":["Osmonlaru yerdagi barcha narsalar Allohga tasbih aytadir. U zot gʻolib va hikmat egasidir.","Ey iymon keltirganlar! Nima uchun qilmagan narsangizni gapirasiz.","Qilmagan narsangizni gapirishingiz Allohning nazdida qattiq yomon koʻrilgandir. (Jihod farz qilinishidan avval bir guruh moʻminlar, agar Alloh taolo bizni Oʻzi eng suyadigan amalga buyurganda edi, uni bajarib ulkan savoblarga erishardik, deb orzu qilib yurishardi. Shunda Alloh Paygʻambar alayhissalomga vahiy yuborib, jihodni farz qildi, ammo avval gapirib yurganlarga bu amr mashaqqatli tuyuldi, ogʻir botdi. Shundan soʻng Alloh taolo yuqoridagi oyatlarni tushirib, ularni ogohlantirdi. Bundan kamida ikkita ibrat chiqadi: birinchisi - jihod Alloh naqadar suygan amallardan ekanini hamda ikkinchisi - aytganiga amal qilish eng oliy darajadagi martaba ekanini bilamiz. Bu gaplar har bir islom ummatiga tegishlidir. Qaysi ummat - millat shunga amal qilsa, Alloh oldida ulkan savobga, hayotda esa ulkan taraqqiyotga erishadi.)","Albatta, Alloh Oʻz yoʻlida xuddi jips binodek boʻlib, safda turib urush qiladiganlarni yaxshi koʻradir. (Alloh taolo moʻminlar jamiyatini doimo birdam, hamfikr va jipslashgan boʻlishini xohlaydi. Bu oyatda esa urushda ham birdam boʻlishga, jipslashib, dushmanni bir jabha boʻlib qarshi olishga buyurmoqda.)","Muso oʻz qavmiga: «Ey qavmim, Allohning Rasuli ekanimni bilib turib, yana nima uchun menga ozor berasiz», deganini esla. Ular (haqdan) burilgan edilar Alloh ularning qalbini burib qoʻydi. Alloh fosiq qavmlarni hidoyat qilmas.","Iyso ibn Mariyam: «Ey Bani Isroil, albatta, men oʻzimdan oldin kelgan Tavrotni tasdiqlovchi va mendan keyin keluvchi Ahmad ismli Rasulning bashoratini beruvchi, Alloh sizlarga yuborgan Paygʻambarman», deganini esla. (Ahmad) ularga haq bilan kelgan vaqtda esa, bu ochiq-oydin sehrdir, dedilar.","Islomga daʼvat qilinib turganda Allohga nisbatan yolgʻon toʻqigan kimsadan ham zolimroq kishi bormi? Holbuki. Alloh zolimlarni hidoyatga solmas. (Yaʼni, inson Islomga daʼvat qilinsa, ikki dunyoning saodatiga erishtiruvchi dinga chaqirilsa, uni xursandlik bilan qabul qilishning oʻrniga, Allohga nisbatan yolgʻon toʻqisa, haqiqatdan u dunyodagi eng ashaddiy zolim hisoblanadi. Undaylarning Alloh taologa nisbatan toʻqigan yolgʻonlari turlicha boʻladi.)","Ogʻizlari bilan Allohning nurini oʻchirmoqchi boʻlurlar. Holbuki, Alloh, kofirlar yoqtirmasa ham, Oʻz nurini tugal etguvchidir. ( Islom dinini yoʻq qilish uchun urinuvchilarning harakati quyoshning shuʼlasini ogʻiz bilan puflab oʻchirishga harakat qilishga oʻxshaydi.)","U zot, Oʻz Rasulini hidoyat va haq din bilan barcha dinlardan ustun qilish uchun yuborgan zotdir. Garchi mushriklar yoqtirmasalar ham.","Ey iymon keltirganlar! Sizlarni alamli azobdan najot toptiruvchi tijoratga dalolat qilaymi?","Allohga va Uning Rasuliga iymon keltirasizlar hamda Uning yoʻlida molingiz va joningiz bilan jihod qilasizlar. Shundoq qilmoqlaringiz, agar bilsangizlar, oʻzlaringiz uchun yaxshidir.","Ana shunda, U zot gunohlaringizni kechirur va sizlarni adn jannatidagi ostidan anhorlar oqib turgan bogʻlarga va yaxshi maskanlarga kiritur. Bu ulugʻ yutuqdir.","Va sizlar yaxshi koʻradigan boshqasi ham bor. Allohdan yordam va yaqin zafar. Va moʻminlarga bashorat ber. (Ushbu oyat Qurʼoni karimning gʻoyibdan bergan xabarlaridan boʻlib, ulkan moʻjiza hamdir. Chunki u Makkai Mukarrama fath etilishidan avval tushgan. Bundan bir oz vaqtdan keyin Alloh taolo ushbu oyatda bergan vaʼdasi ustidan chiqdi. Allohning yordami boʻlib, Makka musulmonlar qoʻliga oʻtdi. Soʻng tezda butun Arabiston yarim roliga Islom dini tarqaldi.)","Ey iymon keltirganlar! Allohning yordamchilari boʻling! Xuddi Iyso ibn Maryam havoriylarga: «Kim Alloh uchun mening yordamchim» deganida, havoriylar: «Biz Allohning yordamchilarimiz», deganlaridek. Bas, Bani Isroildan bir toifa iymon keltirdi va bir toifa kofir boʻldi. Bas, Biz iymon keltirganlarni dushmanlari ustidan qoʻllab-quvvatladik. Va ular gʻolib boʻldilar. (Havoriylar Iyso alayhissalomning shogirdlari, u kishiga yaqin odamlardir. Alloh taolo bu oyati karimada musulmonlarni Islom diniga xizmat qilishga chaqirmoqda va bu xizmatni Allohga yordamchi boʻlish, deb atamoqda.)"],"62":["Osmonlaru yerdagi barcha narsalar Xoja, Benuqson, Aziz, Hakim Allohga tasbih aytadir.","U zot savodsizlar ichidan, garchi ular bundan avval ochiq zalolatda boʻlsalar ham, ularga oyatlarini oʻqib beradigan va ularni poklaydigan hamda kitobni va hikmatni oʻrgatadigan Paygʻambarni yubordi. (Oʻsha davr arablari ummiy qavm deyilgan, chunki ularning ichlarida oʻqish-yozishni biladiganlari juda oz boʻlgan. Paygʻambarimiz Muhammad alayhissalom oʻqish-yozishni mutlaqo oʻrganmaganlar.)","Va hozircha ularga qoʻshilmagan boshqalarga ham. Va U zot gʻolib va hikmat egasidir. (Bu oyati karima ham Qurʼonning ulkan moʻjilaridan biridir. Bu gʻoyibning xabaridir. Arablardan boshqa xalqlarning islomga kirishini oʻsha paytda Allohdan oʻzga hech kim bilmasdi.)","Bu Allohning fazlidir (va uni) xohlagan kishisiga beradir. Alloh ulugʻ fazl egasidir.","Ustlariga Tavrot yuklatilgan, soʻngra uni koʻtarmaganlar misoli ustiga kitob yuklangan eshakka oʻxsharlar. Allohning oyatlarini yolgʻonga chiqargan qavmning misoli qandoq ham yomon. Alloh zolim qavmlarni hidoyat qilmas. («Ustlariga Tavrot yuklatilgan»lar - yahudiylar. Alloh taolo ularni ustiga kitob ortilgan eshakka oʻxshatmoqda. Xuddi eshak ustidagi kitobni koʻtarib charchasa charchaydi, ammo aslo bu kitobdagi ilm va taʼlimotlardan foydalanmaydi.)","Sen: «Ey yahudiylar, albatta siz, boshqalardan farqli oʻlaroq, Allohning avliyolarimiz, deb daʼvo qiladigan boʻlsangiz, bas, oʻlimni orzu qiling, agar rostgoʻy boʻlsangiz», deb ayt.","Ular qoʻllari qilgan(gunoh)lari tufayli hech qachon, u(oʻlim)ni orzu qilmaslar. Alloh zolimlarni biluvchidir. (Yahudiylarning oʻlimni sira orzu qilmasliklariga sabab - gunohlarining koʻpligi. Ular biladilarki, oʻlimdan keyin savol-javob boʻladi, gunohlarga yarasha azob belgilanadi. Bu esa ular uchun nihoyatda dahshatli.)","Sen: «Albatta, siz undan qochayotgan oʻlim, taʼkid shulki, sizga baribir yoʻliquvchidir. Soʻngra maxfiy va oshkor narsalarni Biluvchining huzuriga qaytarilursizlar. Bas, U sizga nima qilib yurganingizning xabarini beradir.","Ey iymon keltirganlar! Juma kuni namozga nido qilinganda, Allohning zikriga shoshiling va savdoni qoʻying. Agar bilsangiz, bu oʻzingiz uchun yaxshidir.","Bas, namoz tugagandan soʻng yer yuzi boʻylab tarqaling va Allohning fazlidan talab qiling va Allohni koʻp eslang, shoyadki yutuqqa erishsangiz.","Va ular tijorat yoki oʻyin-kulgu koʻrganlarida, unga tomon yopirildilar va seni tik holda tark etdilar. Sen: «Allohning huzuridagi narsa oʻyin-kulgudan va tijoratdan yaxshidir. Va Alloh eng yaxshi rizq beruvchidir», deb ayt. (Dunyo tashvishi deb ibodatni tark etish yaxshi emas. Chunki rizq beruvchi Allohning Oʻzi. Avval Uning ibodati ado boʻlsa, rizq topishda keyinOʻoʻzi yordam beradi.)"],"63":["Munofiqlar huzuringga kelganlarida, guvohlik beramizki, sen, albatta, Allohning Rasulisan, derlar. Holbuki, Alloh albatta sen Uning Rasuli ekaningni biladir. Va Alloh guvohli berurki, albatta, munofiqlar yolgʻonchidirlar.","Ular qasamlarini qalqon qilib oldilar va (odamlarni) Allohning yoʻlidan burdilar. Bas, albatta, ularning qilgan ishlari yomon boʻldi!","Bunga sabab shuki, ular iymon keltirdilar, soʻng kofir boʻldilar, bas, qalblariga muhr bosildi. Endi ular fahmlamaslar.","Va agar ularni koʻrsang, jismlari seni ajablantirur va agar gapirsalar, gaplariga quloq osursan. Ular xuddi suyab quyilgan xodaga oʻxsharlar. Har qichqiriqni ziddilariga hisoblaydilar. Ular dushmandirlar. Ulardan hazir boʻl. Alloh ularga urush ochsin, haqdan qandoq oʻgirilurlar. (Bu oyatda Alloh taolo munofiqlarning baʼzi sifatlari va tasarruflarini moʻminlar ulardan ehtiyot boʻlishlari uchun bayon qilmoqda. Chunki munofiqlarning ichida chiroyli yuzli, kelishgan gavdali, soʻzga usta kishilar bor. Bunday qaraganda, kelishgan, tuppa-tuzuk odamlar, gaplari ham kishilarni rom qiladigan. Masalan, munofiqlarning oʻsha paytdagi rahbari Abdulloh ibn Ubay qomatli, chiroyli va soʻzlamol odam edi. Boshqa munofiqlardan ham unga oʻxshashlari bor edi. Paygʻambar alayhissalomning majlislariga kelib, devorga suyanib oʻtirar edilar. Sahobalar ularning qomatlariga havas bilan boqishar, gaplariga quloq solar edilar. Lekin baribir qalblari iymondan, yaxshilikdan xoli boʻlgani uchun Alloh taolo ularni devorga suyab qoʻygan xodaga oʻxshatmoqda.)","Va agar ularga: «Kelinglar, Allohning Rasuli sizlarga istigʻfor aytadir», deyilsa, ular boshlarini chayqarlar. Va ularni mutakabbirlik holida yuz oʻgirayotganlarini koʻrarsan.","Ularga istigʻfor aytasanmi yoki aytmaysanmi-ular uchun bari bir. Alloh ularni hech magʻfirat qilmas. Zero, Alloh fosiq qavmlarni hidoyatga boshlamas. (Istigʻfor aytish - gunohning kechishini Allohdan soʻrash. Suraning nozil boʻlishi haqidagi rivoyatlarda kelishicha, munofiqlarning rahbari Abdulloh ibn Ubayning yolgʻonchiligi fosh boʻlgandan soʻng kishilar unga: «Endi Rasulullohning huzurlariga borib uzr soʻra, u kishi sening gunohlaringni kechishini soʻrab Allohga duo qilsalar, gunohlaring magʻfirat qilinsa ajab emas», deyishganda, mutakabbirlik bilan bosh chayqab, bormagan ekan. Lekin oyatning hukmi hamma munofiqlar uchun bir.)","Ular, Rasulullohning huzuridagilarga nafaqa bermanglar, toki tarqab ketsinlar, derlar. Holbuki, osmonlaru yerning xazinalari Allohnikidir. Va lekin munofiqlar tushunmaslar.","Ular, agar Madinaga qaytib borsak, albatta aziz xorni undan chiqarur, derlar. Holbuki, azizlik Allohga, Uning Rasuliga va moʻminlariga xosdir. Lekin munofiqlar bilmaslar. (Ushbu oyati karima munofiqlar boshligʻining Paygʻambar alayhissalomni Madinadan xorlarcha quvib chiqaraman, deb qilgan doʻq-poʻpisasiga raddiya beradi. «Madinaga qaytib borsak», deyilgandan murod Mustalaq qavmiga qarshi gʻazotdan qaytib Madina shahriga borsak, deganidir. Bundan koʻrinib turibdiki, munofiqlar qarshi turli jabha va uslublarni, shu jumladan, mahalliychilikni ham ishga soladilar.)","Ey iymon keltirganlar. Mollaringiz va bolalaringiz sizni Allohning zikridan chalgʻitmasin. Kim shunday qilsa, bas, ana oʻshalar yutqazuvchilardir.","Va biringizga oʻlim kelib: «Ey Robbim, agar mening oʻlimimni yaqin muddatga orqaga sursang, bas, sadaqa qilib solihlardan boʻlsam», demasdan avval Biz sizlarga rizq qilib bergan narsalardan nafaqa qiling. (Rizqning asosiy manbai Allohning Oʻzidir va U odamlarga Oʻzi xohlaganicha berib qoʻygan va uning nafaqa, xayr-ehson qilib turishga buyurgan. Albatta, bu ish oʻlim kelishidan avval boʻlishi shart. Sogʻ-salomatlikda, hamma narsaga qodirlik paytda xayr-ehson qilsa, oʻrniga tushadi.)","Alloh ajali kelgan jonni hech-hech orqaga surmas. Zero, Alloh nima qilayotganingizdan xabardordir. (Oqil kishi boshiga oʻlim kelmasidan xayrli ishlarni koʻproq qilib qolishga intiladi va shunday boʻlishi ham lozim. Chunki Alloh taolo har bir gapu ishdan xabardor zotdir.)"],"64":["Osmonlardagi narsalar va yerdagi narsalar Allohga tasbih ayturlar. Mulk Unga xosdir, maqtov ham Unga xosdir va U barcha narsaga qodirdir.","U sizlarni yaratgan zotdir. Bas, baʼzilaringiz kofir va baʼzilaringiz moʻmindir. Alloh nima qilayotganingizni koʻrib turuvchidir.","U osmonlaru yerni haq bilan yaratdi. Va qiyofangizni chiroyli suvratda qildi. Va qaytib borish Uning Oʻzigadir. (Ulamolarimiz «Osmonlaru yerni haq bilan yaratdi» jumlasini «Hikmat» bilan yaratdi, deb tushuntiradilar. Osmondagi hisobsiz yuulduzlar va boshqa jismlar, ularning bir-biridan maʼlum uzoqlikda va qatʼiy tartibda joylashishi, hali inson ilmi yetmagan koʻpgina narsa va hodisalar ularni yagona Alloh yaratganini tasdiqlaydi.)","U osmonlaru yerdagi narsalarni biladir. Sizlar sir tutayotgan narsani ham va eʼlon qilayotgan narsani ham biladir. Alloh koʻkrakdagi narsalarni ham biluvchidir.","Sizlarga oldin kofir boʻlganlarning xabari kelmadimi? Bas, ular oʻz ishlarining azobini tatidilar va ularga alamli azoblar bor.","Buning boisi shundaki, ularga Paygʻambarlari oydin dalillar bilan kelardilar, ular boʻlsa, bizni bashar hidoyatga boshlaydimi, deb kufrga ketardilar va (haqdan) yuz oʻgirardilar. Va Alloh behojat boʻldi. Alloh behojat va maqtalgandir.","Kofirlar hech qayta tirilmasliklarini daʼvo qildilar. Sen: «Undoq emas, Robbim bilan qasamki, albatta qayta tiriltirilursizlar, soʻngra qilgan ishlaringizdan xabardor qilinursizlar. Bu ish Alloh uchun osondir», deb ayt.","Bas, Allohga, Uning Rasuliga va Biz tushirgan nurga iymon keltiringlar. Alloh nima qilayotganingizdan xabardordir.","U sizlarni «Jamlash kuni»ga toʻplaydigan kunni eslang. U kun «tagʻobun» kunidir. Kim Allohga iymon keltirsa va solih amallar qilsa, uning gunohlarini kechirur va ostidan anhorlar oqib turgan jannatlarga kiritur. Unda abadul-abad qolurlar. Bu ulkan yutuqdir. («Jamlash kuni», Alloh u kuni avvalgi va oxirgi barcha bandalarni jamlaydi. «Tagʻobun» kuni. Arabcha «tagʻobun» «gʻibn» soʻzidan olingan boʻlib, bahoning pastlashini bildiradi. Qiyomat kuni kofirlar iymonni tark qilganlari uchun baholari pastlab, doʻzaxga ravona boʻladilar. Yaxshi ishlarni kamroq qilib qolgan moʻminlar ham baholari pastlab, jannatning oliy martabalariga yeta olmay qoladilar.)","Kufr keltirib, Bizning oyatlarimizni yolgʻonga chiqarganlar, ana oʻshalar, otash egalaridir. Unda abadiy qolurlar. Qandoq ham yomon joy u!","Sizga Allohning iznisiz hech bir musibat yetmas. Kim Allohga iymon keltirsa, U zot uning qalbini hidoyatga solur. Alloh har bir narsani biluvchidir. (Bandaga Allohning qozoi qadarisiz, ilmisiz hech bir musibat yetmaydi, degan eʼtiqod doimo inson xotirasida turishi kerak. Paygʻambarimiz hadislaridan birida: «... Va bilginki, senga yetgan musibat adashib boshqaga oʻtishi mumkin emas, agar boshqaga boʻlsa, senga yetmasdi...», deganlar.)","Allohga itoat qiling va hamda Rasulga itoat qiling. Agar yuz oʻgirib ketsangiz, bas, Bizning Rasulimizga ochiq-oydin yetkazish, xolos.","Alloh, Undan oʻzga ibodatga sazovor zot yoʻq. Bas, moʻminlar Allohning Oʻzigagina tavakkal qilsinlar.","Ey iymon keltirganlar! Albatta, juftlaringizdan va bolalaringizdan sizga dushman bor, bas, ulardan hazir boʻling. Va agar afv etsangiz, koʻngilga olmasangiz va ayblarini kechirsangiz, bas, albatta, Alloh kechiruvchi va rahmdil zotdir. (Oyatning nozil boʻlish sababi haqidagi rivoyatda aytilishicha: bir guruh kishilar Makkada iymonga kelib, Madinaga hijrat qilishmoqchi boʻlganlarida, xotin va bola-chaqalari, bizni tashlab qayoqqa borasan, deb toʻsiq boʻlishgan ekan. Vaqti kelib Madinaga borishsa, ulardan avval hijrat qilganlar dinda ilgʻor boʻlib ketishibdi. Shunda ularni hijratdan toʻsgan oila aʼzolariga iqob qilishmoqchi boʻlganlarida Alloh taolo: «Va agar afv etsangiz, koʻngilga olmasangiz va ayblarini kechirsangiz, bas, albatta, Alloh kechiruvchi va rahmdil zotdir», degan oyatini tushirib, ularni bu ishdan qaytargan ekan.)","Albatta, mol-mulklaringiz va farzandlaringiz sinovdan boshqa narsa emas. Va Allohning huzurida ulugʻ ajr bor. (Mol-mulk kishi uchun sinovdir. Qoʻliga mol-dunyo kelganda ham hovliqmasdan, toʻgʻri yoʻlda sarflasa, ibodatini vaqtida qilsa, ulkan savoblarga ega boʻladi. Ammo dunyoga berilib yoʻldan ozsa, harom-xarish ishlarni qilsa, mol topish uchun gunoh yoʻllarga ham kiraversa, unda sinovdan oʻta olmagan boʻladi va gunohiga yarasha jazosini oladi. Shuningdek, farzandlar ham Allohning ulkan neʼmati. Ularni toʻgʻri tarbiyalab, xudojoʻy qilib oʻstirilsa, ikki dunyoning obroʻyini olib beradi. Agar teskarisi boʻlsa, ikki dunyoda sharmanda qiladi. Demak, Allohning muhabbatini, mol-mulk va farzandlar muhabatidan ustun qoʻymoq zarur. Chunki uning huzurida ulugʻ ajr bor.)","Allohga qoʻlingizdan kelganicha taqvo qiling va (amrini) tinglang va itoat qiling va infoq qiling - oʻzingizga yaxshi boʻladi. Va kimki nafsining qizgʻanchiqligidan saqlansa, ana oʻshalar najot topuvchilardir.","Agar Allohga yaxshi qarz bersangiz, U sizga koʻpaytirib berur va sizni kechirur. Alloh shakur va halimdir.","U gʻoyib va oshkorni biluvchi, aziz va hakim zotdir."],"65":["Ey Nabiy! Agar ayollarni taloq qiladigan boʻlsangiz, iddalari uchun qiling va iddani hisoblang va Alohga taqvo qiling. Ularni uylaridan chiqarmanglar va oʻzlari ham chiqmasinlar, illo, ochiq-oydin fohisha ish qilgan boʻlsalar (chiqarilurlar). Va ana shu narsalar Allohning chegaralaridir. Kim Allohning chegarasidan chiqsa, haqiqatda oʻzi oʻziga zulm qilibdi. Sen bilmayssan, shoyadki Alloh undan keyin biror ishni paydo qilsa. (Ayollar uchun idda oʻtirishni boshlashga munosib vaqt hayzdan pok boʻlganlaridan soʻng jinsiy yaqinlik qilmay turib taloq qoʻyishdir. Buning aksi ham boʻlishi mumkin. Shundan kelib chiqib, taloq ikkiga boʻlinadi: sunniy taloq va bidʼiy taloq. Sunniy taloq - er kishi oʻz xotinini hayzdan pok paytida, jinsiy yaqinlik qilmay turib yoki homiladorligi aniq boʻlgan da taloq qilishdir. Ushbu shartlarning qoʻyilishi ham taloqning oldini olish uchun tutilgan yoʻldir. Er kishi xotinini hayzdan pok boʻlishini kutib, hovridan tushib, taloq niyatidan qaytib qolishi mumkin. Yoki homiladorligi aniqlangandan soʻng mehri kuchayib, taloqni unutishi ham mumkin. Bidʼiy taloq - yuqorida sanalgan shartlar vujudga kelmagan paytdagi taloqdir. Yaʼni, hayz paytida, poklik payti-yu, ammo jinsiy yaqinlik sodir boʻlganda qoʻyiladiganidir. Bidʼiy taloq qilgan kishi gunohkor hisoblanadi. Lekin oʻrtaga taloq tushaveradi.)","Bas, ular muddatlariga yetsalar, yaxshilik bilan ushlanglar, yoki yaxshilik bilan ajralinglar va sizdan ikki adolatli kishini guvoh qilinglar. Va guvohlikni Alloh uchun qilinglar. Bu ishingizdan kimning Allohga va qiyomat kuniga iymoni boʻlsa, vaʼzlanadi. Kim Allohga taqvo qilsa, U zot uning yoʻlini ochib qoʻyur.","Va unga oʻzi oʻylamagan tarafdan rizq berur. Kim Allohga tavakkal qilsa, bas, unga U zotning Oʻzi kifoyadir. Albatta, Alloh Oʻz ishini yetkazuvchidir. Haqiqatda, Alloh har bir narsaga oʻlchov qilib qoʻygan. (Uchinchi poklik oxirlab qolganda er xotingarajʼat qilib qaytarib olsa, oilaviy hayotlari davom etaveradi. Idda tugashiga yaqin qolganda ham ajralish fikridan qaytmagan boʻlsa, yaxshilik bilan ajralish kerak.)","Ayollaringizdan hayzdan noumid boʻlganlarining iddasi, agar shubhangiz boʻlsa, uch oydir. Hayz koʻrmaganlariniki ham. Homiladorlarning iddasi homilalarini qoʻymoqlikdir. Kim Allohga taqvo qilsa, U zot uning ishida osonlik qilib beradir.","Bular Allohning sizga tushirgan amridir. Kim Allohga taqvo qilsa, uning gunohlarini kechirur va ajrini koʻpaytirib berur.","U(ayol)larga imkoningiz boricha oʻzingiz yashab turgan joydan joy bering. Ularga siqishtirish maqsadida zarar yetkazmang. Agar homilador boʻlsalar, to homilalarini qoʻygunlaricha ularga nafaqa beringlar. Agar sizga (farzandni) emizib bersalar, haqlarini beringlar, oʻzaro yaxshilik bilan maslahat qilinglar. Agar qiyinchilikka uchrasangiz, u(er)ga (farzandini) boshqa ayol emizib berur.","Rizqi keng kengligidan nafaqa qilsin. Kimning rizqi tor boʻlsa, unga Alloh berganidan nafaqa qilsin. Alloh har bir nafsni Oʻzi berganidan ortiqchaga taklif qilmas. Alloh qiyinchilikdan soʻng tezda osonlikni beradir. (Taloq qilingan ayol homilador boʻlsa, taloq qiluvchi er uni tuqqunicha nafaqa bilan taʼminlab turishi kerak. Ushbu nafaqa taom, kiyim va maskan kabilarni oʻz ichiga oladi. Agar ayol taloq qilgan eridan boʻlgan farzandni emizsa, xohlasa, emizgani uchun haq oladi. Bu haqning qancha boʻlishi «oʻzaro yaxshilik bilan maslahat qiling» degan amrga binoan kelishiladi. Oralariga taloq tushgan eru xotin farzandni emizish haqqini kelishishdan «Agar qiyinchillika uchrasa»lar, unga (erga, farzandni) boshqa ayol emizib beradi». Yaʼni, er boshqa begona ayol bilan shartnoma tuzib, unga haq berib bolasini emizdiradi. Islom dini ayollarni qanchalik eʼzozlaganini ushbu hukmdan ham bilib olsa boʻladi. Taomi, kiyimi va maskani erining zimmasiga. Hatto bolani emizish tashvishi ham xotinning emas, balki erning zimmasida, uning burchi.)","Koʻpgina qishloqlar oʻz Robbisin amriga sarkashlik qildi. Bas, Biz ularni shiddatli hisobga oldik va qattiq azob ila azobladik.","Bas, ular oʻz ishlarining yomonligini totib koʻrdilar va ishlarining oqibati yutqiziq boʻldi.","Alloh ularga qattiq azobni tayyorlab qoʻydi. Bas, Allohga taqvo qiling, ey iymon keltirgan aql egalari. Haqiqatda, Alloh sizlarga zikrni tushirdi.","Paygʻabarniki, u iymon keltirib va yaxshi amallarni qilganlarni zulmatlardan nurga chiqarish uchun, sizlarga Allohning ravshan oyatlarini tilovat qilib berur. Va kim Allohga iymon keltirsa va yaxshi amallarni qilsa, U zot uni daraxtlari ostidan anhorlar oqib turgan jannatlarga kiritur. U yerda abadul-abad qolurlar. Haqiqatda, Alloh uning rizqini yaxshi qilgandir.","Alloh yetti osmonni va ular mislidek yerni yaratgan zotdir. Ularning orasidan U zotning amri tushadir. Alloh har bir narsaga qodir ekanini va, albatta, Alloh har bir narsani Oʻz ilmi ila oʻrab olganini bilishingiz uchun."],"66":["Ey Nabiy! Nima uchun xotinlaring roziligini tilab, Alloh senga halol qilgan narsani harom qilasan! Alloh kechiruvchi va rahmdildir. (Alloh senga halol qilgan choʻrini yoki asalni oʻzingga harom qilishing durust emas.)","Batahhiq, Alloh sizlarga qasamlaringizni boʻshatishni shariatga kiritdi va Alloh sizning xojangizdir va U oʻta biluvchi va oʻta hikmatlidir.","Nabiy xotinlaridan baʼzisiga sir gap aytgan edi. Bas, u(sir)dan xabar berdi va Alloh ishni u(Nabiy)ga bildirdi. U baʼzisini bildirdi va baʼzisini eslamadi. Qachon (Nabiy) ul(ayol)ga (ish) haqida xabar berganida, u, buni senga kim xabar qildi? dedi. U, menga hamma narsani biluvchi va hamma narsadan xabardor Alloh xabar berdi, dedi. (Oyatda Paygʻambar xotinlaridan biri deb Hafsa onamiz nazarda tutilyaptilar. «Sir gap» esa. Paygʻambar alayhissalomning u kishiga «Moriyaga yaqinlik qilmaslik yoki asal ichmaslik» haqida aytgan gaplaridir. Lekin Hafsa onamiz sir gapni Oisha onamizga aytdilar. Alloh Hafsaning sirni fosh etganini Paygʻambar alayhissalomga Jabroil farishta orqali bildirdi. «Paygʻambar alayhissalom Hafsaga sirni Oishaga fosh qilinganini eslatganlarida, u «Bu xabarni sizga kim yetkazdi? deb soʻraydi. Paygʻambar alayhissalom: «Hamma narsani biluvchi va hamma narsadan xabardor Alloh bildirdi», deb javob beradilar.) Ey ikki ayol!","Agar ikkovingiz Allohga tavba qilsangiz, batahqiq, qalblaringiz (haqqa) moil boʻlur. Agar unga qarshi chiqsangiz, bas, albatta, Alloh uning yordamchisidir va Jabroil ham, solih moʻminlar ham. Undan soʻng farishtalar ham unga suyanchiqdir.","U sizlarni taloq qilsa, shoyadki, Robbisi sizdan yaxshiroq, muslima, moʻmina, itoatli, tavbachi, ibodatli, roʻzador juvon va qizlarni oʻrningizga xotin qilib bersa.","Ey iymon keltirganlar! Oʻzingizni va ahli ayolingizni yoqilgʻisi odamlaru toshdan boʻlgan oʻtdan saqlang. Uning tepasida qoʻpol, dargʻazab farishtalar boʻlib, ular Allohning amriga isyon qilmaslar va nimaga buyurilsalar, shuni qilurlar.","Ey kofir boʻlganlar, bugungi kunda uzr aytmanglar, siz oʻzingiz qilgan ishlarning jazosini olmoqdasiz, xolos.","Ey iymon keltirganlar! Allohga xolis tavba qilinglar! Shoyadki Robbingiz gunohlaringizni yuvsa va sizni daraxtlari ostidan anhorlar oqib turgan jannatlarga kiritsa. Bir kundaki, unda Alloh Nabiyni va u bilan birga boʻlgan iymon keltirganlarni sharmanda qilmas. Ularning nurlari oldilarida va oʻng taraflarida yurib boradir. Ular esa, Robbimiz, bizga nurimizni batamom qilib ber, gunohlarimizni kechir, albatta, Sen barcha narsaga qodirsan, derlar. (Qiyomat kunida moʻminlardan boshqalar zulmatda qoladilar. Moʻminlar yoʻlini esa nur yoritib turadi. Ular zulmatda adashmaydilar, qoqilib-surilmaydilar ham. Imom Ahmad ibn Hanbal rivoyat qilgan hadisi sharifda Paygʻambar alayhissalom: «Ey parvardigoro, qiyomat kuni sharmanda qilmagin», deb duo qilganliklari keltirilgan.)","Ey Nabiy! Kofir va munofiqlarga qarshi jihod qil va ularga mahkam tur. Ularning joyi jahannamdir va u joy qandoq ham yomon manzil!","Alloh kufr keltirganlarga Nuhning xotini va Lutning xotinini misol qilib keltirdi. Ular bandalarimizdan ikki solih bandaning tagida edilar. Bas, ularga xiyonat qildilar va (erlari) ulardan Allohning azobini qaytara olmadilar va ularga, doʻzaxga kiruvchilar bilan kiringlar, deyildi. (Nuh alayhissalomning xotinlari iymonda xiyonat qilgan. U kishini masxara qilganlarga qoʻshilib, u ayol ham oʻz eri Nuh alayhissalomni masxara qilar ekan. Lut alayhissalomning xotinlari ham eʼtiqod ishida xiyonat qilgan. U gunohkor qavmga oʻz eri huzuriga kelgan mehmonlar haqida axborot berib turar ekan.)","Alloh iymon keltirganlarga Firʼavnning xotinini misol qilib koʻrsatdi. U: «Robbim, menga Oʻz huzuringda, jannatda bir uy bino qilgin. Menga Firʼavndan va uning ishidan najot bergin va zolim qavmlardan najot bergin, deb aytdi. (Firʼavnning xotini oʻsha paytdagi eng katta podshohning ayoli edi. Yemak-kiymakda toʻkin edi. Nimani xohlasa, shuni qilishi mumkin. Qasrlarda, turli neʼmatlar ichida farogʻatda yashashiga qaramasdan kofir va zolim eriga va qavmiga qarshi chiqdi. Allohga iymon keltirdi. Allohdan jannatda uy qurib berishni soʻradi. Bu esa dunyo hoyi havasidan ustun kelishning oliy misolidir.)","Va Maryam Imron qizini (misol keltirdi), u farjini pok saqlagan edi, Biz unga Oʻz ruhimizdan pufladik va u Robbisining soʻzlarini hamda kitoblarini tasdiq qildi va itoatkorlardan boʻldi. (Bibi Maryam Imronning qizi Allohga sof eʼtiqodda boʻlganlar va oʻzlarini ham sof tutganlar. Alloh taolo Jabroil farishta orqali oʻsha pok jasadga oʻz ruhidan «puf» deyishi bilan Iyso alayhissalomni ato qilgan. Bu qissalar boshqa suralarda batafsil kelgani uchun biz bu yerda yana takrorlab oʻtirmaymiz, faqat shuni taʼkidlaymizki, u kishi Allohning soʻzlariga va kitoblariga iymon keltirganlar hamda itoatkor qavmlardan boʻlganlar. Moʻminlar, Bibi Maryam hayotlaridan oʻrnak olishlari kerak.)"],"67":["Qoʻlida mulk boʻlgan U zot ulugʻ, muqaddas boʻldi. U barcha narsaga qodirdir.","U oʻlim va hayotini sizlarning qaysilaringiz amalda yaxshiroq ekanligingizni sinash uchun yaratgandir. U aziz va oʻta magʻfiratlidir. (Oʻlimni eslagan odam unga tayyorgarlik koʻradi va oʻlgandan soʻng sharmanda boʻlmaslik uchun oʻzini yaxshi ishlarga safarbar qiladi.)","U yetti osmonni tabaqama-tabaqa yaratgandir. Rohmanning yaratganida hech tafovut koʻrmassan. Qayta nazar sol! Biror kamchilik koʻryapsanmi?","Soʻng takror-takror nazar sol, nazar senga istaganini topa olmay, horgʻin- charchagan holda qaytadi.","Va darhaqiqat Biz yaqin osmonni chiroqlar bilan ziynatlab qoʻydik va u (chiroq)larni shaytonlarga otiladigan narsa ham qilib qoʻydik. Va u(shayton)larga olovi qizib turgan jahannamni tayyorlab qoʻydik. (Arab folbinlari bizning shaytonlarimiz osmonga chiqib, gʻoyibdagi narsalarni bilib beradi, deb maqtanar edilar. Qurʼoni Karim buni rad etib, bu dunyoda shaytonlarni yulduzlardan ajrab chiqqan uchqunlar quvib haydashini, u dunyoda esa, ularga Alloh jahannam azobini tayyorlab qoʻyganini taʼkidlamoqda.)","Oʻz Robbilariga kufr keltirganlar uchun jahannam azobi bordur va u qanday ham yomon qaytadigan joy!","Ular jahannamga tashlangan chogʻlarida uning hangragan ovozini eshiturlar, u esa qaynab turgan boʻladir.","U gʻazabdan yorilib ketay deydir. Har qachon unga yangi guruh tashlanganda uning xizmatkorlari: «Sizlarga ogohlantiruvchi kelmaganmidi?», deb soʻraydir.","Ular: «Ha, darhaqiqat bizga ogohlantiruvchi kelgan edi. Lekin biz (uni) yolgʻonchiga chiqardik va: «Alloh hech narsa tushirgani yoʻq, sizlar katta adashuvdan boshqa hech narsa emassizlar», degan edik», derlar.","Va ular: «Agar eʼtibor qulogʻi bilan eshitganimizda yoki aqlni ishlatganimizda edi, doʻzaxiylar orasida boʻlmagan boʻlar edik», derlar.","Bas, ular oʻz gunohlarini eʼtirof etdilar. Yoʻqolsin doʻzaxiylar!","Albatta oʻz Robbilaridan gʻoyibdan qoʻrqadiganlar uchun gunohlarini kechish va ulkan ajr-savoblar bordir.","Va siz soʻzingizni sir tutasizmi yoki oshkora aytasizmi, albatta, U koʻngillardagini ham bilguvchi zotdir.","Yaratgan zot Oʻzi bilmasmidi? Va U daqiqlargacha biluvchi va xabardor zotdir.","U sizlarga yerni boʻysundirib qoʻygan zotdir. Bas, uning turli joylarida yuring va Uning rizqidan yeng va qabrdan chiqib borish ham Uning huzuriga boʻladir. (Ulamolarimiz qadimdan ushbu oyati karimaning tafsirini Islomda mehnatga chorlash, rizqni terib yeyish, yer yuzinining turli joylarida harakat qilish zarurligiga dalil qilib keltiradilar. Darhaqiqaat, Alloh taolo yerni insonga boʻysundirib qoʻygan, lekin bu haqiqat hozirgi asrimizdagidek hech qachon yaqqol koʻzga tashlanmagan.)","Osmondagi zot sizlarni yerga yuttirib yuborishidan omonda boʻldingizmi? U (yer) esa iztirobda harakatlanib turadi. («Osmondagi zot»dan murod Alloh taolo, lekin bu degani Alloh osmonda degani emas. Chunki Alloh taolo makonga muhtoj emasdir. U makon va zamondan ustun zotdir. Ahli sunna va jamoa eʼtiqodiga binoan, Allohning yerda yoki osmonda deyilishidan maqsad, Uning xohishi va hukmi yeru osmonga barobar oʻtishi va Uning sultoni gʻolib ekanligidir.)","Yoki osmondagi zot sizlarga azob shamolni yuborishidan omonda boʻldingizmi? Bas, albatta ogohlantirish qandoq boʻlishini bilursizlar.","Va darhaqiqat ulardan avvalgilari ham yolgʻonga chiqargan edilar. Bas inkorim qanday boʻldi?!","Tepalarida (qanoatlarini) yoyib va yigʻayotgan qushni koʻrmaydilarmi? Ularni Rohmandan boshqa ushlab turuvchi yoʻq. Albatta, U barcha narsani koʻruvchidir.","Rohmandan boshqa sizlarga yordam beradigan askar kim oʻzi? Kofirlar gʻururdan boshqa hech narsada emaslar!","U Rizqni tortib qoʻysa, sizga rizq beradigan kim oʻzi?! Balki ular abadiy tugʻyonda va haqdan nafratda boʻlurlar.","Yuz tuban qoqilib yurayotgan kishi hidoyatdami yoki toʻgʻri yoʻldan qomatini tik tutib borayotgan kishimi? («Yuz tuban, qoqilib yurayotgan kishi» kofir kishidir. Chunki, uning aniq yoʻli, maqsadi va koʻrsatmasi yoʻq. Yoʻli adashtiruvchi, xavf-xatarlarga toʻladir.)","Sen: «U sizlarni yoʻqdan bor qilgan va sizlarga eshitish, koʻrish va aqlni bergan zotdir. Juda ham oz shukr qilasizlar-a?!» deb ayt.","Sen: «U sizlarni yer yuzida yaratgan, koʻpaytirgan zotdir. Va Uning huzuriga toʻplanursizlar», deb ayt.","Va ular: «Agar rostgoʻy boʻlsangiz, bu vaʼda qachon boʻladi?» derlar.","Men: «Albatta, ilm, faqat Allohning huzuridadir. Va albatta, men yaqqol ogohlantiruvchiman, xolos», deb ayt.","Bas azobni yaqindan koʻrganda kufr keltirganlarning yuzlari qorayar. Va ularga: «Soʻragan narsangiz shu boʻladi», deyilur.","Sen: «Aytinglar-chi, agar Alloh meni va men bilan boʻlganlarni halok qilsa yoki rahm qilsa, kofirlarni alamli azobdan kim qutqarib qoladi?!» deb ayt.","Sen: «U Rohmandur, biz Unga iymon keltirdik va Unga tavakkal qildik. Bas, sizlar tezda kim ochiq-oydin xatoda ekanini bilursizlar», deb ayt.","Sen: «Aytinglar-chi, agar suvlaringiz yerga singib ketsa, sizlarga kim osongina topiladigan suvni keltiradi?» deb ayt."],"68":["Nuun. Qalam bilan va satrlarga yozadigan narsalar bilan qasam. (Oyatda qasam qalam bilan cheklanmadi, balki Alloh satrlarga yozilajak narsalar bilan ham qasam ichdi. Bizning zamonamizda qalamdan boshqa yozuv qoʻllanmalari ham chiqdi. Qalam va yozish bilan qasam ichilishi musulmonlar uchun oʻqish-yozish, ilm-maʼrifatga katta eʼtibor berishga chaqiriqdur.)","Sen Robbing neʼmati ila majnun emassan.","Va albatta, senga minnat qilinmaydigan ajr bordur.","Va albatta, sen ulkan xulqdasan.","Bas, tezda koʻrursan va ular ham koʻrurlar.","Sizlardan kimda jununlik borligini.","Albatta, Robbing Oʻzi, kim Uning yoʻlidan adashganini biluvchidur va U hidoyatda yuruvchilarni ham biluvchidur.","Bas, yolgʻonga chiqaruvchilarga itoat qilma.","Agar sen murosa qilsang, ular ham murosa qilishni orzu qilarlar.","Itoat qilma! Har bir qasamxoʻr, pastkashga.","Kishilarni ayblovchi, chaqimchilik qilib yuruvchiga.","yaxshilikni man qiluvchi, tajavuzkor, sergunohga.","Qoʻpol, undan soʻng otasining taʼyini yoʻqqa.","Moli va oʻgʻillari koʻp boʻlganidan.","Bizning oyatlarimiz Ungaoʻqilgan paytda, avvalgilarning afsonalari, deganga.","Tezda uning tumshugʻiga belgi qoʻyamiz.","Albatta, Biz ularini bogʻ egalarini sinaganimizdek sinab koʻrdik. Vaqtiki, erta tongada terib olamiz, deb qasam ichdilar.","Va istisno qilmadilar.","Ular uxlab yotganda, bogʻ ustidan Robbingdan boʻlgan aylanuvchi aylanib chiqdi.","Bas, u xuddi mevasi terib olinganga oʻxshab qoldi.","Ular, tong-saharda bir-birlarini chaqirdilar:","«Agar teradigan boʻlsangiz, ekinzoringizga ertaroq boring», deb.","Bas, past ovozla gaplashib, yurib ketdilar.","«Bugun siz boringizda u bogʻga miskin kira koʻrmasin», deb.","Va ertalabda qasdla, oʻzlarini qodir sezib, bordilar.","Uni koʻrganlarida, biz adashibmiz, dedilar.","Balki biz mahrum boʻlgandirimiz, dedilar.","Ularning eng yaxshi va adolatlisi, «Sizlarga tasbih aytsalaringiz-chi, demabmidim?!», dedi.","Robbimiz ayblardan pok boʻldi, albatta biz zolimlardan edik, dedilar.","Bas, baʼzilari baʼzilarni malomat qila boshladilar.","Voy, shoʻrimiz qursin, tugʻyonga ketgan ekanmiz.","Shoyad Robbimiz uning oʻrniga undan koʻra yaxshirogʻini bersa. Biz oʻz Robbimizga ragʻbatlimiz, dedilar.","Azob shundoq boʻlur va agar bilsalar, albatta oxirat azobi bundan katta boʻladir.","Albatta, taqvodorlar uchun Robbilari huzurida naʼiym jannatlari bordur.","Musulmonlarni jinoyatkorlarga oʻxshatib qoʻyarmidik?!","Sizlarga nima boʻldi, qanday hukm chiqaryapsizlar?!","Yoki sizlarning kitobingiz bor-u, undan oʻqidingizmi?","Unda sizlarga nimani ixtiyor qilsangiz, albatta, (boʻlaveradi) deyilganmi?!","Yoki sizlarga Bizning qiyomat kunigacha yetadigan vaʼdalarimiz boʻlib, unda, albatta, siz nima hukm qilsangiz shu boʻladi, deyilganmi?!","Soʻra ulardan, qay birlari bu narsaga kafil ekan?","Yoki ularning sheriklari bormikin, agar rostgoʻy boʻlsalar, oʻsha sheriklarini ham olib kelsinlar.","Boldirlar shimarilgan kunida va ular sajdaga chaqirilganda, qodir boʻlmaslar. (Bu, qiyomat kunidir. Ogʻir holatda qolib qochishga uringan odam halaqit bermasin, deb ishtonini shimarib, boldirini ochib oladi.","Ularning koʻzlari qoʻrqinchga toʻla, xorlik oʻrab olgan. Va darhaqiqat, ular salomatlik hollarida sajda qilishga chaqirilgan edilar.","Bu gapni yolgʻonga chiqaruvchilarni Mening Oʻzimga qoʻyib qoʻy. Biz ularni oʻzlari bilmagan tarafdan asta-sekin olamiz.","Va ularga muhlat beraman, albatta, Mening hiylam metindir.","Yoki sen ulardan haq soʻrayapsanu, ular qarzga botib qoldilarmi?","Yoki huzurlarida gʻoyib ilmi boru, ular yozib oladilarmi?","Robbing hukmiga sabr qil va bir vaqtlar gʻamga toʻlgan holda nido qilgan baliq sohibiga oʻxshama.","Agar uni Robbisining neʼmati topmaganda, ochiq sahro joyga, mazammatga qolgan holda tashlangan boʻlardi.","Bas, uni Robbisi tanlab oldi va solih bandalaridan qildi.","Va kofirlar zikrni eshitayotganlarida seni koʻzlari bilan toydirmoqchi boʻldilar va, albatta, u jinnidur, derlar.","Holbuki, u butun odamlarga eslatmadan oʻzga narsa emas."],"69":["Al-Haaqqah.","Al-Haaqqah nima oʻzi?!","Al-Haaqqah nimaligini senga nima bildirdi?!","Samud va Od qoriʼani yolgʻonga chiqarishdi. («Qoriʼa» ham qiyomatning nomlaridan biri, shiddat bilan eshik qoqib keluvchi maʼnosini anglatadi.)","Bas, ammo Samud haddan oshuvchi bilan halok qilindi. («Haddan oshuvchi»dan murod qattiq chaqmoqdir.)","Va ammo Od qattiq (sovuq) shamol bilan halok qilindilar.","U zot ularning ustidan bu shamolni yetti kechayu sakkiz kunduz betoʻxtov estirib qoʻydi. Bas, qavmni u yerda halok boʻlib, agʻdarilib yotganini koʻrasan. Ular xuddi xurmoning chirigan tomirlariga oʻxsharlar.","Bas, sen ulardan birortasini boqiy qolganini koʻrasanmi?","Firʼavn, undan avvalgilar va toʻntarilganlar xato qildilar.","Bas, ular Robbilarining Rasuliga osiy boʻldilar. Darhaqiqat, U zot ularni qattiq tutishlik bilan tutdi.","Albatta, Biz suv tugʻyonga kelgan paytda sizlarni kemada koʻtarganmiz.","Uni sizlarga eslatma qilish uchun va anglovchi quloqlar anglab olishi uchun. (Boʻlib oʻtgan qissa va hodisalar hamma uchun oʻrnak, eslatma, vaʼz-nasihat boʻlishi kerak.)","Qachonki dudga birgina puflashla puflansa...","Va yeru togʻlar koʻtarilib, bir martagina silkitilsa...","Bas, oʻsha kunda, voqea voqeʼ boʻlibdir.","Va osmon parchalansa, bas, oʻsha kunda, u (osmon) beholdir.","Va farishtalar uning atrofida va oʻsha kunda Robbingning Arshini sakkiztasi koʻtarib turadir. (Allohning arshini sakkizta yoki sakkiz turli farishtalar koʻtarib turadilar. Arsh oʻzida izzat, sulton va moliklik maʼnolarini anglatadi. Bashariyat Arshning ismini biladi, uning haqiqatini Allohning Oʻzi biladi.)","Bas, oʻsha kunda koʻrikdan oʻtasizlar, birorta narsangiz maxfiy qolmaydir.","Bas, kimning kitobi oʻng tarafdan berilsa, u, mana, mening kitobimni oʻqib koʻringlar...","Albatta, men hisob-kitobimga yoʻliqishimga ishonardim, deydir.","Bas, u rozilik hayotidadir.","Oliy jannatdadir.","Uning mevalari yaqindir.","Oʻtgan kunlarda qilgan narsalaringiz tufayli yenglar va ichinglar, osh boʻlsin.","Va ammo kimning kitobi chap tarafdan berilsa, u, voy shoʻrim, koshki menga kitobim berilmasa edi.","Va hisob-kitob qandoqligini bilmasam edi.","Qani (bu dunyodagi oʻlim) oxirgisi boʻlsa edi.","Molu mulkim meni saqlab qola olmadi.","Mening sultonim ham halok boʻldi, deydir. (Mulku sultonim, mansabu obroʻyim, nasabu xasabim hamma hammasi halok boʻldi.)","Tutinglar uni va kishanlanglar uni!!!","Soʻngra jahannamga solinglar uni!!!","Soʻngra yetmish qulochli zanjirga kiriting uni!!!","Chunki u ulugʻ Allohga iymon keltirmagan edi.","Va miskinlarga taom berishga qiziqtirmagan edi. (Miskinlarga taom berishga qiziqtirmaslik shunchalikka olib kelsa, imkoni boʻlsa turib ularga taom bermaslik qanchalik gunoh ekan–buni kitobxonning oʻzi fahmlayversin.)","Bas, bugungi kunda unga bu yerda biron chin doʻst yoʻq.","Va gʻisliyndan oʻzga taom ham yoʻq.","U(taom)ni xatokorlardan boshqa hech kim yemas.","Sizlar koʻrib turgan narsalar bilan qasam ichurman.","Va sizlar koʻrmaydigan narsalar bilan ham.","Albatta u(Qurʼon) karamli Rasulning soʻzidir. (Qurʼoni Karimni Paygʻambarimiz sallollohu alayhi vasallamga nisbat berilishi U zot (s. a. v) u kalomni tilovat qiluvchi va kishilarga yetkazuvchi ekanligidandir.)","Va u shoirning soʻzi emas. Sizlar juda oz ishonasizlar.","Va folbinning ham soʻzi emas. Sizlar juda oz eslarsizlar.","Olamlar Robbisidan tushirilgandir.","Va agar u Bizning (nomimizdan) baʼzi yolgʻon soʻzlarni toʻqisa.","Albatta, Biz uni qudrat bilan tutarmiz.","Soʻngra, albatta, uning shoh tomirini kesarmiz.","Bas, sizlardan hech kim uni toʻsib qola olmas.","Va, albatta, u(Qurʼon) taqvodorlar uchun eslatmadir.","Va, albata, Biz sizlarning ichingizda yolgʻonga chiqaruvchilar borligini bilib turamiz.","Va albatta u kofirlar uchun hasratdir.","Va albatta u shubhasiz haqiqatdir.","Bas, ulugʻ Robbingning ismini poklab yod et."],"70":["Soʻrovchi voqeʼ boʻluvchi azob haqida soʻradi.","Kofirlar ustiga. U(azob)ni daf qiluvchi yoʻqdir.","U maʼorijlar egasi Allohdandir.","Farishtalar va Ruh Uning huzuriga miqdori ellik ming yil boʻlgan kunda koʻtariladir.","Bas, chiroyli sabr qil.","Albatta, ular u(qiyomat)ni uzoq deb bilurlar.","Va Biz uni juda yaqin deb bilurmiz.","U kunda osmon xuddi qora moy qoldiqlariga oʻxshab qoladir.","Va togʻlar xuddi titilgan junga oʻxshab qoladir.","Va yaqin doʻst oʻz doʻstidan soʻramaydir.","Ularni koʻrib tururlar. Gunohkor oʻsha kun azobidan qutulish uchun oʻz bolalarini ham.","Xotinini va aka-ukasini ham,","Va uni oʻziga olgan qabilasini ham.","Va yer yuzidagi jamiyki kimsalarni ham fido qilishni, soʻngra oʻzi najot topishni istaydir.","Yoʻq! Albatta u(jahannam) kuchli alangadir.","Boshning terisini sidirib oluvchidir. (Bosh terisi shilib olingan doʻzaxiyga Alloh taolo yana yangi teri ato etadi. Jahannam oʻti esa yana uni shilib oladi va shu tariqa toʻxtovsiz davom etaveradi.)","U chaqiradir; orqaga ketgan va yuz oʻgirganni.","Va (molni) yigʻib berkitganni.","Albatta, inson «haluʼ» qilib yaratilgandir. («Haluʼ» soʻzi hirs, zajr, chidamsizlik va sabrsizlik maʼnolarini mujassamlashtiradi.)","Agar unga yomonlik yetsa, chidamsizdir.","Va agar yaxshilik yetsa, koʻp man qiluvchidir.","Magara namoz oʻquvchilargina mustasnodir.","Ular namozlarida doim boʻladiganlardir.","Ularning molu mulklarida mvʼlum haq bordir.","Soʻrovchi va bechoralar uchundir.","Va ular qiyomat kunini tasdiqlaydiganlardir.","Va ular oʻz Robbilari azobidan qoʻrqadiganlardir.","Albatta Robbilarining azobidan omonlik yoʻqdir.","Va ular oʻz farjlarini saqlaydiganlardir.","Magaram oʻz xotinlari yoki oʻz mulki boʻlganlar mustasnodir. Albatta ular bunga malomat qilinmaydir.","Kimki oʻshandan oʻzgani istasa, bas, ular chegaradan chiqqanlardir.","Ular omonatlariga va ahdlariga rioya qiladiganlardir.","Va ular guvohliklarini toʻgʻri beradiganlardir.","Ular namozlarini muhofaza qiladiganlardir.","Oʻshalar jannatlarda hurmatlanadiganlardir.","Kufr keltirganlarga nima boʻldiki, boʻyinlarini choʻzib sen tomon shoshmoqdalar?!","Oʻng tarafdan va chap tarafdan toʻp-toʻp boʻlmoqdalar?! (Paygʻambar sallollohu alayhi vasallam Qurʼon tilovat qilganlarida mushriklar shoshilib kelib, toʻp-toʻp boʻlib oʻtirishar va koʻz uzmay tikilib turishar edilar.)","Ulardan har bir kishi naʼim jannatga kiritilishni tamaʼ qiladimi?","Yoʻq! Albatta, Biz ularni oʻzlari bilgan narsadan yaratganmiz.","Mashriqlar va magʻriblar Robbisi bilan qasam ichamanki, albatta Biz qodirmiz.","Oʻrinlariga ulardan yaxshiroqlarini almashtirishga qodirmiz va Biz bu ishni qilishdan ojiz emasmiz.","Ularni tek qoʻy. To vaʼda qilingan kunga yoʻliqqunlaricha xohlaganlariga shoʻngʻiyversinlar va oʻynayversinlar.","U kunda xuddi sanamlar (ibodatiga) shoshganlaridek, qabrlaridan shoshib chiqurlar.","Koʻzlari qoʻrqinchga toʻlgan, oʻzlarini xorlik qoplagan holda tururlar. Bu oʻsha-ularga vaʼda qilingan kundir. (Qiyomatni inkor etuvchilarga bundan ortiq tahdid boʻlmasa kerak!)"],"71":["Biz Nuhni oʻz qavmiga, qavmingni ularga alamli azob kelishidan avval ogohlantirgin deb, Paygʻambar qilib yubordik.","U: «Ey qavmim, albatta men siz uchun ochiq-oydin ogohlantiruvchiman.","Allohga ibodat qilinglar, Unga taqvo qilinglar va menga itoat qilinglar.","U sizlarning gunohlaringizdan magʻfirat qiladir va sizni belgilangan ajalgacha qoʻyib qoʻyadir. Agar bilsangiz, albatta, Allohning ajali orqaga surilmaydir», dedi. (Bu oyatda zikr qilingan, gunohlarnig kechirilishi va belgilangan muddatgacha yashab qolish, avvalgi oyatda shart qilingan Allohga ibodat qilish, unga taqvo qilish va Paygʻambarga itoat qilish ishalri boʻlsagina vujudga keladi.)","U: «Robbim, men oʻz qavmimni kechayu kunduz daʼvat qildim.","Mening chaqirigʻim ularda qochishdan boshqa narsani ziyoda qilmadi.","Va alabatta qachonki men ularni sening magʻfirat qilishing uchun chaqirsam, ular barmoqlarini quloqlariga tiqdilar va kiyimlariga burkanib oldilar va (kofirlikda) sobit boʻldilar va nihoyatda ulkan takabburlik qildilar.","Soʻngra, albatta men ularni ochiq daʼvat qildim.","Soʻngra, albatta men ularga eʼlon va sirriy (daʼvat) qildim.","Bas, oʻz Robbingizga istigʻfor ayting, albatta u gunohlarni koʻplab magʻfirat qiluvchidir, dedim.","U zot osmondan ustingizga ketma-ket (baraka yomgʻirini) yuboradir.","Va sizga molu mulk va bola-chaqa ila madad beradir va sizlarga bogʻu rogʻlar hamda anqorlarni beradir.","Sizlarga nima boʻldiki, Allohning azamatini oʻylab koʻrmaysizlar?","Holbuki, u sizlarni holatma-holat yaratdi.","Alloh yettti osmonni qandoq qilib tabaqama-tabaqa yaratib qoʻyganini koʻrmadingizmi?","Va ular ichida oyni nur va quyoshni chiroq qilib qoʻyganini koʻrmadingizmi?","Va Alloh sizlarni yerdan oʻstirib chiqaradir.","Soʻngra sizlarni unga qaytarib, yana chiqaradir.","Va Alloh sizlarga yerni gilamdek toʻshab qoʻydi.","Unda siz keng yoʻllardan yurishingiz uchun», deb aytdim.","Nuh: «Ey Robbim, albatta ular menga isyon qildilar va moli, bola-chaqasi xusrondan boshqani ziyoda qilmaganga ergashdilar.","Va nihoyatda ulkan makr qildilar.","Va ular: «Olihalaringizni hech tark qilmanglar va albatta Vaddni ham, Suvaʼni ham, Yagʻusni ham, Yaʼuqni ham va Nasrni ham tark qilmang», dedilar. (Shayton vasvasasi tufayli kishilar haykallarga sigʻinishining bayoni ushbu oyatda nozil qilingandir.)","Darhaqiqat ular koʻplarini adashtirdilar va sen zolimlarga zalolatdan boshqani ziyoda qilma», dedi. (Koʻrinib turibdiki, Nuh alayhissalomning bu duolari nihoyatda alamli duo. Nuh alayhissalom oʻz qavmlariga qilgan ushbu duoibandni Alloh subhanahu va taolo u zotga sening qavmingdan hozir iymonga kelganlaridan oʻzgasi zinhor iymonga kelmas, deb xabar berganidan soʻng, ularning iymonlaridan noumid boʻlib turib qolganlar.)","Ular xatolari tufayli gʻarq qilindilar, bas, doʻzaxga kiritildilar. Bas, oʻzlariga Allohdan oʻzga yordamchi topa olmadilar.","Va Nuh: «Ey Robbim, yer yuzida kofirlardan birorta ham harakatlanuvchini qoʻymagin.","Albatta sen ularni tek qoʻysang, bandalaringni adashtirurlar va fojiru kofirdan boshqa tugʻmaslar.","Robbim, meni magʻfirat qilgin, mening ota-onamni ham va uyimga moʻmin boʻlib kirganlarni va moʻminlaru moʻminalarni ham. Va zolimlarga halokatdan oʻzga narsani ziyoda qilmagin», dedi. (Nuh alayhissalomning duolari qabul boʻldi. Alloh taolo kofirlarni bitta ham qoʻymay halok qildi. Chunki ular insoniyat badaniga tushgan qorason kasalidek edilar. Ularni kesib tashlamasa boʻlmas edi.)"],"72":["Sen ayt: «Menga vahiy qilindiki, Albatta jinlardan (bir necha) nafari quloq osdilar va dedilar: «Biz ajoyib Qurʼonni eshitdik.","U toʻgʻri yoʻlga hidoyat qilur. Bas, biz unga iymon keltirdik va oʻz Robbimizga birovni shirk keltirmasmiz. (Jinlar oʻz aql-farosatlari ila Qurʼonni tushirgan Alloh ularning Robilari ekanligi va unga sherik boʻlishi mumkin emasligini ham tushunib yetadilar. Makka mushriklariga oʻxshab Allohga shirk keltirmasliklarini taʼkidlaydilar.)","Va, albatta, Robbimizning azamati yuksak boʻldi. U oʻziga xotin va farzand tutgani yoʻq!","Va albatta esi pastimiz Allohga nohaq gaplarni aytardi.","Va, albatta, biz, ins ham, jin ham Allohga (nisbatan) yolgʻon gapirmas, deb oʻylardik.","Albatta, insdan baʼzi kishilar, jinlarning baʼzi kishilaridan panoh soʻrardilar. Bas, bu(jin)lar u(ins)larning gunoh va xorligini ziyoda qildilar.","Va albatta u(ins)lar xuddi sizlar gumon qilganingizdek, Alloh biror kishini oʻlgandan soʻng tiriltirmas, deb gumon qilardilar.","Va albatta biz osmonga (yetishni) talab qildik. Bas, uni kuchli qoʻriqchilarga va uchqunlarga toʻlgan holda koʻrdik.","Va, alabatta, biz u(osmon)da tinglashga qulay joylarga joylashib olar edik. Endi esa, kim quloq solsa, oʻzini poylab turgan uchqunga duchor boʻladir.","Va, albatta, biz yer yuzidagilarga yomonlik iroda qilindimi yoki Robbilari ularga rushdni iroda qildimi-bilmasmiz.","Va, albatta, bizdan solihlar ham va boshqalar ham bor. Turli guruhlar boʻlgan edik.","Va, albatta, biz Allohni yer yuzida ojiz qoldira olmasligimizga va undan qochib qutila olmasligimizga ishondik.","Va, albatta, biz hidoyatni eshitgan paytimizda unga iymon keltirdik. Kimki oʻz Robbisiga iymon keltirsa, savobi ozayib qolishdan ham, unga ogʻir yuk yuklanishidan ham qoʻrqmas.","Va, albatta, bizdan musulmonlar va bizdan adashganlar bor. Kimlar Islomga kirsa, bas, ular haq yoʻlni tanlabdilar.","Va, ammo, adashganlar, bas, jahannamga oʻtin boʻlibdilar. (Oyatda yoʻldan adashganlar jahannamga yoqilgʻi boʻlishliklari ham aniq, ochiq-oydin aytilmoqda.)","Va agar ular toʻgʻri yoʻlda mustaqim boʻlsalar, albatta, Biz koʻp suv ila sugʻoramiz.","U ila ularni sinash uchun. Va kimki oʻz Robbisi zikridan yuz oʻrigsa, uni U zot qiyin azobga soladir.","Va, alabatta, masjidlar Allohnikidir. Bas, Allohdan boshqaga duo qilmang. (Masjidlar Allohga ibodat qilish uchun bino qilingan joylardir, shuning uchun ham ular «Baytulloh» –Allohning uyi deb ataladi. Boshqa din vakillari oʻz ibodatxonalarida Allohga shirk keltirishar, yagona Allohdan oʻzgaga ham ibodat, duo qilishardi. Alloh taolo bu oyatda Oʻz Paygʻambari va moʻmin-musulmonlarni tavhidga-faqat Allohning Oʻziga ibodat qilishga chaqiradi.)","Va, albatta, Allohning bandasi Unga ibodat qilib turganda ular uning atrofida ot yolidek toʻplanib, bosib yuboray deyishdi. (Bu oyatda jinlarning Paygʻambar alayhissalom huzurlariga ikkinchi bor kelib Qurʼon eshitganlari payti tasvirlanyapti.)","Sen: «Albatta, men faqat oʻz Robbimga ibodat qilaman va Unga hech kimni shirk keltirmasman», deb ayt.","Sen: «Albatta, men sizlar uchun zararga ham, manfaatga ham molik emasman»-deb ayt.","Sen: «Albatta, meni hech kim Alloh(azobi)dan saqlab qola olmas va hargiz Allohdan oʻzga pushti panoh topa olmasman.","Mening vazifam, faqat, Allohning topshiriqlarini yetkazishdir. Kimki Allohga va Uning Paygʻambariga boʻysunmasa, unga jahannam otashi bor, unda abadiy qolajaklar.","Toki ularga vaʼda qilingan narsani koʻrganlarida, kimning yordamchisi zaifu, kimning soni ozligini ham bilarlar», deb ayt.","Sen: «Sizlarga vaʼda qilingan narsa yaqinmi yoki Robbim unga uzoq muddat qilganmi–bilmayman.","U gʻaybni biluvchidir va hech kimni Oʻz gʻoybidan xabardor qilmaydi.","Magar Oʻzi rozi boʻlgan Paygʻambarlar. Albatta Alloh uning oldidan ham, ortidan ham kuzatib yuruvchi qoʻyib qoʻyadir.","Paygʻambarlar oʻz Robbilari risolalarini darhaqiqat yetkazganliklarini bilish uchun va Alloh bandalar huzuridagi barcha narsani ixota qilib olganligini va hamma narsani adadi, hisobini qilganligini bilish uchun», deb ayt. (Paygʻambarlar muhofazasi uchun qoʻyilgan farishtalar bir yoʻla, ularning Allohning dinini odamlarga qandoq yetkazayotganlariga guvoh ham boʻlib turadilar. Alloh hamma narsani Oʻz ixtiyoriga olib oʻragani, hamma narsaning hisob-kitobini qilib turishiga ham shohiddirlar.)"],"73":["Ey oʻranib yotuvchi!","Kechani ozginasidan boshqasini (ibodatda) tik turib oʻtkaz!","Yarmini yoki undan bir oz qisqarogʻini.","Yoki u(yarim)ga yana qoʻsh va Qurʼonni tartil bilan tilovat qil. (Qurʼonni tartil bilan oʻqish deb uni dona-dona qilib, har bir harfini oʻz oʻrnidan chiqarib, oyatlarini alohida-alohida qilib, tajvid qoidalari asosida oʻqishga aytiladi.)","Albatta, Biz ustingga ogʻir soʻzni tashlarmiz.","Albatta, kechasigi ibodat koʻproq muvofiq keladir va qiroati toʻgʻriroq boʻladir.","Albatta, kunduzi sening uzoq ishlashing bor.","Va Robbingning ismini zikr et va Uning ibodatiga butunlay ajralib chiq.","U mashriqu magʻribning Robbisidir. Undan oʻzga ibodatga sazovor iloh yoʻq. Bas, Uni oʻzingga vakil tut.","Va ularning gaplariga sabr qil va ulardan chiroyli chetlashla, chetlab tur.","Ahli neʼmat boʻlgan, yolgʻonga chiqaruvchilarni Oʻzimga qoʻyib qoʻy va ularga ozgina muhlat ber.","Albatta, Bizda ogʻir kishanlar va jahannam bor.","Va (tomoqqa) tiqiladigan taom va alamli azob bor.","Bir kundaki, unda yeru togʻlar larzaga keladir va togʻlar oquvchi qumtepalarga aylanadir.","Albatta, Biz sizlarga, xuddi Firʼavnga Rasul yuborganimizdek, siz haqingizda guvohlik beruvchi Rasulni yubordik.","Bas, Firʼavn Rasulga osiy boʻldi va Biz uni shiddatli azob bilan tutdik.","Agar kofir boʻlsangiz, bolalarning sochini oqartib yuboradigan kundan qanday saqlanasiz?! («bolalarning sochini oqartib yuboradigan kun»–qiyomat kuni ekani hammaga maʼlum.)","Unda osmon parchalanuvchidir, U zotning vaʼdasi amalga oshadir.","Albatta, bular eslatmadir, Kim xohlasa, oʻz Robisi tomon yoʻl oladir.","Albatta, Robbing seni kechaning uchdan biridan ozrogʻini, yo yarmini, yo uchdan birini qoim boʻlib oʻtkazayotganingni va sen bilan birga boʻlganlardan ham bir toifa (shundoq qilayotganlarini) biladir. Va Alloh kechayu kunduzni Oʻzi oʻlchaydir. U sizlar hech chiday olmasligingizni bilib, sizlarga (yengillikni) qaytardi. Bas (endi), Qurʼondan muyassar boʻlganicha oʻqinglar. Sizlardan kelajakda kasallar boʻlishini ham bildi. Boshqalar yer yuzida yurib, Allohning fazlini axtarishini, yana boshqalar esa, Allohning yoʻlida jihod qilishlarini (ham bildi). Bas, undan muyassar boʻlganicha qiroat qilinglar. Va namozni qoim qilinglar, zakot beringlar va Allohga yaxshi qarz beringlar. Oʻzingiz uchun nima yaxshilik qilgan boʻlsangiz, Allohning huzurida undan yaxshirogʻini va ulkanroq ajrni toparsizlar. Allohga istigʻfor aytinglar. Albatta, Alloh magʻfirat qiluvchi va rahmdildir. (Bu oyat bilan Alloh taolo suraning avvalidagi oyatlarga binoan farz qilingan kechasi qoim boʻlishni bekor qildi. Shundan soʻng kechada farz namozlardan tashqari ibodat qilish ixtiyoriyga alanadi. Islom taʼlimotlari har bir narsada yuksak insoniy fazilatlar hukm surishini yoʻlga qoʻyib kelgan va inshaalloh shunday boʻlib qoladi.)"],"74":["Ey burkanib yotgan!","Tur va ogohlantir!","Va Robbingni ulugʻla!","Va kiyimingni pokla!","Va azob(sababchisi)dan chetlan!","Va koʻp (ish)qilgan boʻlsang ham, minnat qilma!","Va Robbing uchun sabr qil!","Va qachonki dudga puflansa.","Oʻshal kun, qiyin kundir.","U kofirlarga oson emasdir.","Meni, Oʻzim yakka yaratgan kimsa bidan qoʻyib qoʻy.","Va unga koʻplab molu dunyo.","Va hoziru nozir farzandlar berib qoʻydim.","Va unga (hamma narsani) osonlashtirib qoʻydim.","Soʻngra, yana ziyoda qilishimni tamaʼ qiladir.","Yoʻq! Chunki, u Bizning oyatlarimizga sarkash edi.","Tezda uni mashaqqatli chiqishla horitarman.","Albatta, u tafakkur qildi va chamalab koʻrdi.","Laʼnat boʻlsin unga, qandoq ham chamalab koʻrdi!","Soʻngra yana laʼnat boʻlsin unga, qandoq ham chamalab koʻrdi.","Soʻngra nazar soldi.","Soʻngra yuzini burishtirdi va qavogʻini soldi.","Soʻngra yuz oʻgirdi va takabburlik qildi.","Bas, bu asar qolgan sehrdan oʻzga hech narsa emas.","Bu bashar soʻzidan oʻzga hech narsa emas, dedi.","Tezda uni saqar (doʻzaxi)ga kiritaman.","Va saqar nimaligini senga nima bildirdi?","U (saqar) boqiy qoldirmas va tark ham qilmas.","U terini koʻp kuydiruvchidir.","Uning ustida oʻn toʻqqizta (farishta) bordir.","Doʻzax sohiblarini farishtalardan qilganimiz va ularning adadi ham faqat kofirlarni sanash uchundir. Kitob berilganlar ishonch hosil qilishlari uchundir. Va iymonlilarning iymoni ziyoda boʻlishi uchundir. Kitob berilganlar va moʻminlar shak-shubha qilmasliklari uchundir va qalblarida kasali bor(munofiq)lar va kofirlar, Alloh bu bilan nima misolni iroda qilmoqchi, deyishlari uchundir. Shundoq qilib Alloh xohlagan kimsani adashtiradir va xohlagan kimsani hidoyatga soladir. Robbingning askarlarini Oʻzidan boshqa hech kim bilmaydir. Va u (doʻzax) bashariyat uchun eslatmadan oʻzga hech narsa emasdir.","Yoʻq! Oy bilan qasam.","Va chekinayotgan tun bilan qasam.","Va yorishayotgan tong bilan qasam.","Albatta u(doʻzax) ulkan(azob) larning biridir.","Bashariyat uchun ogohlantiruvchidir.","Sizlardan peshqadam boʻlishni yoki ortda qolishni xohlayotgan kimsalar uchun hamdir.","Har bir shaxs oʻz kasbining garovidir.","Magar oʻng taraf sohiblari mustasnodir.","Ular jannatlarda soʻrarlar.","Gunohkorlardan.","Sizlarni doʻzaxga nima kiritdi?","Ular: «Namoz oʻqiydiganlardan boʻlmagan edik.","Va miskinlarga taom bermagan edik.","Va botilga shungʻuvchilar bilan birga shoʻngʻir edik.","Va qiyomat kuni yolgʻonga chiqargan edik.","Toki bizga oʻlim kelgunicha», derlar.","Bas, ularga shafoatchilarning shafoati manfaat bermas.","Ularga ne boʻldiki, eslatmadan yuz oʻrirurlar?!","Xuddi qattiq qoʻrqqan eshaklar.","Arslondan qochgani kabi.","Balki ulardan har biri oʻziga nashr qilingan sahifalar berilishini iroda qiladir.","Yoʻq! Balki ular oxiratdan qoʻrqmaslar.","Yoʻq! Albatta u(Qurʼon) eslatmadir.","Bas, kim xohlasa uni eslaydir.","Va faqat Alloh xohlasagina eslaydilar. U zot taqvo ahlidir va magʻfirat ahlidir."],"75":["Qiyomat kuni bilan qasam.","Va malomatchi nafs bilan qasam.","(Kofir) Inson Bizni, uning suyaklarini jamlay olmas, deb oʻylarmi?","Ha, Biz uning barmoq uchlarini ham asl holiga keltirishga qodirmiz.","Balki inson kelajakda fisqu fujur qilishni xohlaydir.","U: «Qiyomat kuni qachon?» deb soʻraydir.","Qachonki koʻz dahshatda lol qolsa.","Va oy tutilsa.","Va quyosh bilan oy jamlansa.","Oʻshal kunda inson, qochar joy qayda? deb qolar.","Yoʻq! Qochadigan joy yoʻq!","U kunda istiqror faqat Robbing huzurida boʻlar.","U kunda insonga avvalu oxir qilganining xabari berilar.","Ha, inson oʻz nafsiga qarshi oʻzi shohiddir.","Garchi uzr-maʼzurlarini toʻkib soladir.","Sen shoshilib, u(Qurʼon) bilan, tilingni qimirlatma.","Albatta, uni jamlash va oʻqib berish Bizning zimmamizdadir.","Bas, Biz uni oʻqisak, qiroatiga zehn solib tur.","Soʻngra uni bayon qilib berish ham Bizning zimmamizdadir.","Yoʻq! Balki sizlar shoshar dunyoni yaxshi koʻrasizlar.","Va oxiratni tark etasizlar.","U kunda bor chiroyli yuzlar.","Robbisiga nazar soluvchilar.","Va u kunda bor tirishib-burishgan yuzlar.","Oʻziga umurtqasin sindirar ish boʻlishiga ishonar.","Yoʻq! jon halqumga kelganda.","Va, qutqaruvchi kim? deganda.","Va, albatta, u firoqligin bilganda.","Va boldirlar bir-biriga almashganda.","U kunda haydab borar joy faqat Robbinggadir. (Yaʼni, joni halqumiga kelib qolganda, uni hayotda olib qolish uchun barcha chora koʻriladi, Kim qutqararkin, deb iltijo qilinadi. Lekin iloji boʻlmay firoq vaqti kelganiga ishonch hosil boʻladi. Jon chiqqanda esa oyoqlar jonsiz boʻlib bir-biriga chalmashadi.)","Bas, u tasdiqlamadi va namoz oʻqimadi.","Va lekin yolgʻonga chiqardi va yuz oʻgirdi.","Soʻng oʻz ahliga kerilib bordi.","Holingga voy boʻlsin sening, voy boʻlsin!","Yana holingga voy boʻlsin sening, voy boʻlsin!","Inson behuda tark qilinishning hisobini qilurmi?","U maniydan oqqan nutfa boʻlmaganmidi?","Soʻng alaqa boʻldi. Bas bekamu-koʻst etib yaratdi.","Bas undan juftni–erkak va ayolni yaratdi.","Shunday zot oʻliklarni tiriltirishga qodir emasmi?!"],"76":["Haqiqatda insonga, u esga olinadigan narsa boʻlmagan bir zamon kelmadimi?","Albatta, Biz insonni aralash nutfadan yaratdik. Sinash uchun, bas, uni eshitadigan, koʻradigan qildik.","Albatta, Biz unga yoʻl koʻrsatdik. (U esa) yoki shukr qiluvchi, yoki kufr qiluvchi boʻldi.","Albatta, Biz kofirlar uchun zanjirlar, kishanlar va yonib turgan olovni tayyorlab qoʻydik.","Albatta, yaxshilar kaafur aralashtirilgan qadahdan icharlar. (Kaafur–ichimlikni xushboʻ va xushtaʼm qiluvchi modda boʻlib arablar u aralashgan sharobni eng yaxshi sharob hisoblashadi.)","Bir buloqdaniki, undan Allohning bandalari otiltirib icharlar.","Ular nazrga vafo qilarlar va yomonligi keng tarqaladigan kundan qoʻrqarlar.","Oʻzlari taomni yaxshi koʻrib tursalar ham, uni miskin, yetim va asirga berarlar. (Abrorlarning xislati nima ekan! Ular hattoki oʻzlariga taom kerak boʻlib, hojatlari tushib tursa ham, miskin, yetim, asirlarni oʻzlaridan ustun qoʻyib, taomni ularga beradilar.)","«Albatta, Biz sizlarni faqat Allohning roziligi uchun ovqatlantiramiz. Buning evaziga sizlardan mukofot yoki tashukkur xohlasmiz.","Albatta, biz qoʻrqinchli, shiddatli, uzun kunda oʻz Robbimizdan qoʻrqamiz», (derlar).","Bas, ularni Robbilari oʻshal kun sharridan saqladi va ularga xushroʻylik hamda xursandchilik ato qildi.","Va sabr qilganliklari uchun ularni bogʻu rogʻ va ipaklar bilan mukofotladi.","U yerda soʻrilarda suyangan holdalar. U yerda quyoshni ham, sovuqni ham koʻrmaslar.","Va ustilariga u(jannat)ning soyalari yaqindir hamda uning mevalari juda ham oson qilingandir.","Va ularga kumush idishlar va billurlardan boʻlgan qadahlar aylantirib turilar.","Billurlar, kumushsiymon, (soqiylar) oʻlchovini keltirar.","Va ular u yerda aralashmasi zanjabil boʻlgan qadahdan sugʻorilar","Uyerdagi salsabiyl, deb nomlangan buloqdan. (Zanjabiyl–yerga tomir otgan oʻsimlik turi boʻlib, tomiri tuyilib xushboʻy modda yasaladi: arablar undan oʻz ichimliklariga qoʻshib ichishni juda-juda sevadilar. Ichuvchining tomogʻidan huzur bagʻishlab, osonlik bilan oʻtuvchi sharobni arablar salsabiyl deb ataydilar. «Salsabiylan» deyilganda shunga ishora qilinyapti.)","Va ularning atrofida abadiy yosh bolalar aylanurlar, agar ularni koʻrsang, sochilgan marjon, deb oʻylarsan.","Va agar koʻrsang, u yerda neʼmatni va ulkan mulkni koʻrarsan.","Ularning ustilarida yashil sundusdan (yupqa ipakdan) va istobraqdan (qalin ipakdan) kiyimlar bor va kumush bilakuzuklar-la yasanganlar va Robbilari ularni pok sharob bilan sugʻorar.","Albatta, bu sizga mukofot boʻldi, va amalingiz qabul boʻlmshdir.","Albatta, Biz senga Qurʼonni boʻlak-boʻlak qilib tushirdik.","Bas, Robbing hukmiga sabr qil va ulardan gunohkor yoki kofirlariga itoat qilma.","Ertayu kech Robbing ismini zikr qil.","Va kechasida ham Unga sajda qil va uzoq kechalarda Unga tasbih ayt. (Tafsirchilar «bukratan»dan murod Bamdod namozi, «asiylo»dan murod peshin va asr namozi, «Va minal layli» Shom va Xufton namozlari. «Laylan toviylo»dan murod kechasi bedorlik bilan oʻqilgan namoz deganlar.)","Albatta, anavilar shoshgan dunyo)ni yaxshi koʻrarlar va ogʻir kunni ortlarida qoldirarlar.","Biz ularni yaratdik va yaratilishlarini mstahkam qildik. Va agar xohlasak ularning oʻrinlariga oʻxshashlarini keltirurmiz.","Albatta, bu(sura)eslatmadir. Bas, kim xohlasa oʻz Robbisiga yoʻl oladir.","Va Alloh xohlasagina, sizlar ham xohlarsiz. Albatta, Alloh biluvchi va hikmatli zotdir.","U kimni xohlasa Oʻz rahmatiga kiritadir va zolimlar uchun alamli azoblar tayyorlab qoʻygandir."],"77":["Ket-ket yuborilganlar bilan qasam.","Qattiq esuvchi shamollar bilan qasam.","Va (shariatni) taratuvchilar bilan qasam.","Farqlovchilar bilan qasam.","Vahiyni tashuvchilar bilan qasam.","Uzrni yoki ogohlantirishni (ham).","Albatta, sizga vaʼda qilinayotgan narsa voqeʼ boʻluvchidir.","Bas, vaqtiki yulduzlar oʻchirilsa.","Va vaqtiki, osmon yorilsa.","Va vaqtiki, togʻlar koʻchirilsa.","Va vaqtiki, Paygʻambarlarga vaqt belgilansa.","Qandoq kunga surilgan-a?","Ajratish kuniga.","Ajratish kunini senga nima bildirdi?","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Avvalgilarni halok qilmadikmi?","Soʻngra keyingilarini ularga ergashtirmadikmi?","Gunohkorlarni shundoq qilamiz.","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Sizlarni haqir suvdan yaratmdikmi?","Bas, uni mustahkam qarorgohga joylamadikmi?","Maʼlum vaqtga qadar.","Bas, Biz qodir boʻldik va qandoq ham yaxshi qodir boʻluvchimiz. (Yuqorida aytilgan ishlarga qodir boʻldik, nihoyatda ajoyib, insoniyat tafakkuridan ustun bir holatda, qodir boʻldik, deyapti Parvardigor.)","Oʻshal kunda yolgʻonga chiqavchilarga vayl boʻlsin!","Yerni oʻziga tortuvchi qilmadikmi?","Tiriklarni va oʻliklarni?","Va Biz unda yukasak togʻlar qildik va sizlarni zilol suv bilan sugʻordik.","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Yuringiz! Oʻzingiz yolgʻonga chiqargan narsaga qarab.","Yuringiz! Uchta shoʻbasi bor «soya»ga qarab.","U salqin qiluvchimas va olovni ham qaytarmas.","Albatta u (jahannam) qasrdek uchqunlarni otadir.","U (uchqun) xuddi qoramtir-sargʻish tuyalarga oʻxshaydir.","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Bu ular gapira olmaydigan kundir.","Va ularga uzr aytishga izn berilmaydir.","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Bu ajratish kuni, sizlarni va avvalgilarni jamladik.","Bas, sizlarning hiylangiz boʻlsa, menga ishlatib koʻring-chi?","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Albatta taqvodorlar soyalar va buloqlardadir.","Va oʻzlari xohlagan mevalardadir.","Yenglar va ichinglar, osh boʻlsin. Qilgan amallaringiz sababidandir.","Albatta, Biz muhsinlarni shunday mukofotlarmiz.","Oʻshal kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Yenglar va mazza qilinglar, ozginagina. Albatta, sizlar gunohkorsizlar.","Oʻshal kunda yolgʻonga chiqavurchilarga vayl boʻlsin!","Va agar ularga rukuʼ qilinglar deyilsa, rukuʼ qilmaslar.","Oʻshal kunda yolgʻonga chiqaruvchilvarga vayl boʻlsin!","Bas, undan keyin, qaysi soʻzga ishonarlar?!"],"78":["Nima haqida soʻrashadi?","Ulkan, muhim xabar haqida (soʻrashadi).","Shunday xabarki, u(mushrik)lar) uning haqida ixtilof qilarlar.","Yoʻq! Ular tezda bilarlar!","Yana yoʻq! Ular tezda bilarlar! (Mushriklar azobni tortganlarida qayta tirilish nima ekanligini, uning boʻlishi hech shubhasiz haq ekanini albatta biladilar.)","Yerni toʻshab qoʻymadikmi?","Va togʻlarni qoziq (qilib qoʻymadikmi?).","Va sizlarni juft qilib yaratdik.","Va uyqularingizni rohat qilib qoʻydik.","Va kechasini libos qilib qoʻydik.","Va kunduzni tiriklik qildik.","Tepalarngizga yetti mustahkam (osmon)ni bino qildik.","Va shuʼla taratuvchi chiroq ham qildik.","Va siqilgan(bulut)lardan oquvchi suvlar tushirdik.","U(suv) bilan don va nabotot chiqarishimiz uchun.","Va daraxtlari bir-biriga kirishgan boʻstonlar.","Albatta, ajrim kuni vaqti belgilangan edi.","U kunda surga puflanur va sizlar toʻp-toʻp boʻlib kelursizlar.","Osmon yorilib, eshik-eshiklar ochilur.","Togʻlar oʻrnidan koʻchirilib, sarobga aylanur.","Albatta, jahannam poylab turuvchi edi.","Tugʻyonga ketganlarga qaytar joydir.","Ular unda zamonlar boʻyi qoluvchilardir.","Ular unda sovuqni ham, sharobni ham tatiy olmaslar.","Magar qaynoq suv va yiringni (tatirlar).","Muvofiq jazo oʻlaroq.","Chunki ular hisob-kitob boʻlishiga ishonmasdilar.","Va Bizning oyatlariimizni yolgʻon deyishgan edi, yolgʻon!.","Biz barcha narsani kitobga jamlab qoʻyganmiz.","Bas, tatib koʻringlar, sizlarga azobdan boshqa hech narsani ziyoda qilmasmiz.","Albatta, taqvodorlarga yutuq bordir:","Bogʻ-rogʻlar, uzumzorlar bordir.","Va yangi boʻyi yetgan bir xil yoshdagi qizlar bordir.","Va toʻldirilgan qadahlar bordir.","U yerda bekorchi gaplarni ham, yolgʻon gaplarni ham eshitmaslar.","Robbingdan mukofot, sovgʻa hisobidandir.","U osmonlar, yer va ularning orasidagi barcha narsalarning Robbisi, Rohmandir, Uning huzurida hech kim xitob qilishga qodir boʻlmas.","Oʻsha kunda Ruh va farishtalar saf boʻlib turadir. Rohman izn berganlar va toʻgʻri soʻzlaganlardan oʻzgalar gapira olmaslar.","U haq kundir. Kim xohlasa, oʻz Robbisiga qaytar yoʻl oladir.","Albatta, Biz sizlarni yaqin kelajakdagi azobdan qoʻrqitdik. U kunda, har kishi (qoʻli) taqdim qilgan narsaga nazar soladir. Va kofir «koshki tuproq boʻlib ketsam», –deydir."],"79":["Shiddat bilan (kofir) jonni sugʻurib oluvchi(farishta)lar bilan qasam.","Yumshoqlik bilan (moʻmin) jonni oluvchi (farishta)lar bilan qasam.","Suzib yuruvchi (farishta)lar bilan qasam.","Oʻzishda musobaqa qiluvchi (farishta)lar bilan qasam.","Amrning tadbirini qiluvchi (farishta)lar bilan qasam.","Iztirobga tushuvchi iztirobga tushgan kunda.","Unga ergashuvchi ergashar.","Oʻsha kunda qalblar xavfga toʻlar.","Ularning koʻzlari qoʻrqinchga toʻlar.","Ular: «Biz ortga qaytarilamizmi?","Chirigan suyak boʻlganimizdan keyin ham-a?","Agar shundoq boʻlsa, bu hasratiy qaytish-ku?» derlar.","Albatta, u(qiyomat) bir qichqiriqdan boshqa narsa emas.","Koʻribsizki, ular qiyomat maydonida turibdi-da.","Senga Musoning xabari keldimi?","Qachonki Robbisi unga muqaddas Tuva vodiysida nido qildi:","«Firʼavn huzuriga bor, albatta u tugʻyonga ketdi.","Bas unga ayt: «Senda poklanishga (ragʻbat) bormi?","Va seni Robbingga hidoyat qilsam, shoyadki (Undan) qoʻrqsang», deb»","Va unga ulkan alomatni koʻrsatdi.","Ul uni yolgʻonga chiqardi va osiy boʻldi.","Soʻng ortiga oʻgirilib tezlab ketdi.","Keyin (odamlarni) toʻplab nido qildi.","Va, men sizlarning eng oliy Robbingizman, dedi.","Bas Alloh uni avvalgi va oxirgi gunohlari uchun azobga oldi.","Albatta, bunda qoʻrqadiganlar uchun ibrat bordir.","Sizlarni yaratish qiyinmi yoki U zot bino qilgan osmonnimi?","Uning shiftini yuqori koʻtardi va bekamu koʻst, mustahkam qilib qoʻydi.","Kechasini qorongʻu va kunduzini yorugʻ qildi.","Va undan soʻng yerni tuxum shaklida qildi.","Undan suvni, oʻt-oʻlanlarni chiqardi.","Va togʻlarni sobit qildi.","Sizlarga va chorvalaringizga manfaat boʻlsin uchun.","Vaqtiki katta gʻolib (qiyomat) kelsa.","U kuni inson qilgan ishlarini eslaydir.","Va jahannam koʻradiganlarga zohir qilinadir.","Ammo kimiki tugʻyonga ketib, haddidan oshgan boʻlsa","Va bu dunyo hayotini ustun qoʻygan boʻlsa,","Bas, albatta, Jahiym oʻrin boʻladir.","Va, ammo kim Robbisining maqomidan qoʻrqqan va oʻz nafsini havolanib ketishidan qaytargan boʻlsa.","Bas, albatta, jannat oʻrin boʻladir.","Sendan, qiyomat qachon boʻlur? deb soʻrarlar.","Uning zikrini sen qandoq bilarding.","Uning intihosi Robbingga xosdir.","Albatta sen un(qiyomat)dan qoʻrqqanlarga ogohlantiruvchisan, xolos.","Uni koʻrgan kunlari xuddi bu dunyoda bir kecha yoki kunduzdan boshqa turmaganga oʻxsharlar."],"80":["Aftini burishtirdi va yuz oʻgirdi.","Koʻzi koʻr kishi huzuriga kelganda.","Qayerdan bilasan, ehtimol, u poklanar.","Yoki nasihat olar va mavʼiza unga manfaat berar.","Ammo istigʻno qilganga boʻlsa...","Sen u tomonga intilasan.","U poklanmasa, seni hech kim malomat qilmas.","Ammo huzuringga shoshilib kelgan.","Va (Allohdan) qoʻrqqan holda boʻlgandan esa...","Bas, Sen undan mashgʻul boʻlasan.","Yoʻq! Albatta u(oyat)lar eslatmadir.","Kim xohlasa uni eslaydir.","Hurmatlangan sahifalardadir.","Oliy qadardirlar, poklangandirlar.","Elchi(farishta)lar qoʻllaridadir.","Ular hurmatlangan va oʻta yaxshidirlar.","(Kofir) insonga laʼnat boʻlsin, uning kofirligi qandoq shiddatli boʻldi.","Uni qaysi narsadan yaratdi?","Nutfadan yaratdi. Uni yaratdi va unni oʻlchovli qildi.","Soʻngra chiqish yoʻlini oson qildi.","Soʻngra oʻldirdi va qabrga kiritdi.","Soʻngra qachon xohlasa, uni qayta tiriltiradi.","Yoʻq undoq emas! U oʻziga U zot qilgan amrni bajarmadi.","Inson oʻz taomiga nazar solsin.","Albatta, Biz suvni rosa quyib qoʻydik.","Soʻngra yerni oʻziga xos yordik.","Biz unda don oʻstirib qoʻydik.","Va uzum va koʻklarni ham.","Va zaytun va xurmolarni ham.","Va tigʻiz bogʻlarni ham.","Va mevalarni va oʻt-oʻlanlarni ham.","Sizlarga va chorvalaringizga manfaat boʻlsin, deb.","Vaqtiki quloqlarni kar qiluvchi ovoz kelsa.","U kunda kishi qochadir; oʻz aka-ukasidan.","Va onasi va otasidan.","Va xotini va bola-chaqasidan.","U kunda ulardan har bir shaxsni ovora qiluvchi oʻz ishi bor.","U kunda porloq chehralar bor.","Ular kulgu bilan toʻla, yetgan xushxabardan xursand.","U kunda gʻubor bosgan chehralar bor.","Ustini zulmat qoplagan.","Ular, ana oʻshalar, kofirlar va fojirlardir."],"81":["Vaqtiki, quyoshni buklab, oʻralsa.","Va, vaqtiki, yulduzlar sochilib ketsa.","Va, vaqtiki, togʻlar sayr qildirilsa.","Va, vaqtiki, homilasiga oʻn oy toʻlgan tuyalar qarovsiz qolsa.","Va, vaqtiki, vahshiy hayvonlar bir joyga toʻplansa.","Va, vaqtiki, dengizlar alanga olib yonsa.","Va vaqtiki, nafslar juftlashtirilsa. (Yaʼni, ruh tanaga qaytarilib, ikkovlari birlashsalar.)","Va vaqtiki, tiriklay koʻmilgan qizdan soʻralsa.","U nima gunoh uchun oʻldirilgan?","Va, vaqtiki, sahifalar nashr qilinsa.","Va, vaqtiki, osmon qoʻporilsa.","Va, vaqtiki, jahannam qizdirilsa.","Va, vaqtiki, jannat yaqinlashtirilsa.","Har bir jon nima hozirlanganini biladi.","(Kunduzi) maxfiy boʻluvchi(yulduz)lar bilan qasam.","(Kechalari) yuruvchi, berkinuvchi(yulduz)lar bilan qasam.","Qorongʻuligi bilan kirib kelgan kecha bilan qasam.","Nafas olib, kirib kelgan tong bilan qasam.","Albatta u(Qurʼon) karamli Rasulning soʻzidir.","U quvvatlidir. Arsh egasi huzurida martabasi oliydir.","Itoat qilingan, omonatli.","Sizning sohibingiz majnun emas.","Batahqiq ul ani ochiq-oydin ufqda koʻrdi. (Muhammad s. a. v. Jibroilni ochiq-oydin ufqda oʻz koʻzlari bilan asl yaratilishida koʻrdilar.)","Va u gʻaybga baxil emas.","Va u(Qurʼon) toshboʻron qilingan shaytonning soʻzi emas.","Bas, qayoqqa ketmoqdasiz?!","U (Qurʼon) olamlarga eslatmadan boshqa narsa emas.","Sizlardan mustaqim boʻlishni xohlovchilar uchun.","Olamlarning Robbisi Alloh xohlamasa, sizlar xohlay olmassizlar. (Har bir narsa Allohning xohishiga bogʻliq. Har bir narsa Alloh taoloning xohishi ila boʻladi.)"],"82":["Vaqtiki, osmon yorilsa.","Va, vaqtiki, yulduzlar sochilib ketsa.","Va, vaqtiki, dengizlar portlatilsa.","Va, vaqtiki, qabrlar ostin-ustin boʻlsa.","Har bir jon nimani taqdim qildiyu, nimani taʼxir qildi- biladi.","Ey Inson! Seni karamli Robbing haqida nima gʻururga ketkazdi?!","U seni toʻla-toʻkis va moʻtadil qilib yaratgan zotdir.","Oʻzi xohlagan suratda seni tarkib qildi.","Yoʻq! Balki, siz jazoni yolgʻonga chiqarmoqdasiz!","Holbuki, ustingizdan kuzatib turuvchilar bordir.","Ular hurmatli, yozib turguvchilardir.","Ular nima qilayotganingizni biladir.","Albatta, yaxshilar jannatdadir.","Va albatta, fojirlar jahannamdadir.","Ular u yerga qiyomat kuni kiradir.","Va ular undan gʻoyib boʻla olmaydir.","Va jazo kuni nima ekanini senga nima bildirdi?","Soʻng jazo kuni nima ekanini senga nima bildirdi?","Oʻsha kunda hech bir jon boshqa bir jon uchun biror narsa qilish imkoniga molik emasdir. U kunda barcha ish Allohning Oʻziga xosdir."],"83":["Vayl (voy) boʻlsin, oʻlchovdan urib qoluvchilarga.","Ular odamlardan narsa oʻlchab olsalar, toʻliq olarlar.","Va agar odamlarga oʻlchab yoki tortib bersalar, kamaytirarlar.","Ana shular, albatta, qayta tiriltirilishlarini oʻylamaydilarmi?","Ulugʻ bir kunda.","U kunda, odamlar olamlar Robbisi huzurida tik turarlar.","Yoʻq! Albatta fojirlarlarning kitobi «sijjin»dadir.","«Sijjin» qanday narsa ekanini senga nima bildirdi?! (Sijjin nima ekanini qayerdan ham bilarding, uning mohiyati shundoq kattaki, sen uni idrok eta olmaysan. Bilib qoʻy!)","U yozilgan kitobdur.","Oʻsha kunda yolgʻonga chiqaruvchilarga vayl boʻlsin!","Ular jazo kunini yolgʻonga chiqararlar.","U kunni haddan oshuvchi va oʻta gunohkorlardan boshqalar yolgʻonga chiqarmaslar.","Qachon unga oyatlarimiz tilovat qilinsa, «avalgilarning afsonalari», der.","Yoʻq! Ularning qilgan kasblari qalblariga mogʻor boʻlib oʻrnashib qolgan, xolos.","Yoʻq! Albatta, ular oʻsha kunda oʻz Robbilarini koʻrishdan toʻsilarlar.","Soʻngra ular albatta jahiymga kiruvchidirlar.","Soʻngra, mana bu, sizlar yolgʻonga chiqarib yurgan narsa, deyilar.","Yoʻq! Albatta abrorlarning kitobi «Illiyyun»dadir.","«Illiyyun» qandoq narsa ekanini senga nima bildirdi?!","U yozilgan kitobdur.","Unga muqarrab(farishta)lar shohid boʻlarlar.","Albatta, abrorlar jannati nayimdadirlar.","Pardali baland soʻrilar ustida nazar solib turarlar.","Ularning chehralaridan jannat ravnaqini bilib olarsan.","Ular muhrlangan, nihoyatda pok, sharobdan icharlar.","U(sharob)ning xotimasi miskdir. Va shu narsa uchun musobaqa qiluvchilar musobaqa qilsinlar.","U(sharob)ning aralashmasi «tasnim»dandir.","U(Tasnim) bir buloqdirki, undan muqarrablar icharlar.","Albatta jinoyat qilganlar iymon keltirganlar ustidan kular edilar.","Agar ul(moʻmin)lar alarning yonidan oʻtsalar, masxaralab, ishoralar qila edilar.","Agar u(kofir)lar oʻz ahllari huzuriga qaytib borsalar, huzurlanib qaytib borar edilar.","Va agar u(moʻmin)larni koʻrsalar, «albatta anovilar adashganlar», der edilar.","Holbuki, ular a(moʻmin)lar ustidan kuzatuvchi qilib yuborilgan emaslar!","Endi, bu Kunda iymon keltirganlar kofirlar ustidan kularlar.","Pardali, baland soʻrilar ustida nazar solib turarlar.","Kofirlar qilgan ishlarining «savobini» olar mikanlar?!"],"84":["Vaqtiki, osmon yorilsa.","Va u (osmon) oʻz Robbisiga quloq osdi va shundoq boʻlishi kerak edi.","Va, vaqtiki, yer choʻzilsa.","Va oʻz ichidagi narsalarni otib chiqarib, xoli qolsa.","Va u (yer) oʻz Robbisiga quloq osdi va shundoq boʻlishi kerak edi.","Ey inson! Albatta sen Robbingga yoʻliqquningcha, harakatu urinishda boʻlarsan va oxiri unga yoʻliqarsan.","Ammo kimning kitobi oʻng tarafdan berilsa.","Tezda, osongina hisob qilinar.","Va ahli huzuriga xursand holda qaytib borar.","Va, ammo, kimning kitobi orqa tarafdan berilsa.","U tezda oʻziga halokatni chaqirar.","Va qizib turgan doʻzaxga kirar.","Chunki, u(bu dunyoda) oʻz ahli bilan xursand boʻlib oʻtgan edi. (Oxiratni hech ham oʻylamagan edi. Faqat ayshu ishrat, koʻngilxushi payidan boʻlgan edi. Gʻofil boʻlib, oʻz ahli ila besh kunlik dunyoning matohiga erishish uchun harakat qilgan edi. Shuning uchun endi qizib turgan doʻzaxda azoblanmoqda.)","Chunki, u hech qachon orqaga qaytmaslikni oʻylagan edi.","Ha! Albatta, Robbisi uni doim koʻrib turuvchi edi.","Shafaq bilan qasamki.","Kechasi va u oʻrab olgan narsalar bilan qasamki.","Va toʻlin oy bilan qasamki.","Albatta, sizlar tabaqama-tabaqa minasizlar.","Nima boʻlgan ularga, iymon keltirmaslar?!","Va agar ularga Qurʼon oʻqilsa, sajda qilmaslar?! (Kimki bu oyatlarni oʻqib yoki eshitib sajda qilmagan odam gunohkor boʻladi.)","Balki kofirlar yolgʻonga chiqararlar.","Ular qalblarida nimani saqlayotganlarini Allohning Oʻzi bilar.","Ularga alamli azobning «bashoratini» ber.","Magar iymon keltirganlarga va yaxshi amallar qilganlarga, ularga minnatsiz, uzluksiz ajrlar bordir."],"85":["Burjlar egasi boʻlgan osmon bilan qasam.","Va vaʼda qilingan kun bilan qasam.","Guvohlik beruvchi va guvohlik berilgan bilan qasam.","«Uxdud» egalariga laʼnat boʻlsin.","U (Uxdud) yoqilgʻisi koʻp, qattiq isigan olovdir.","U(kofir)lar a(chuqur)lar atrofida oʻtiribdilar.","Va ular moʻminlarga qilayotgan narsalariga oʻzlari hozirdirlar.","Va (ular) moʻminlardan Aziz, Hamid Allohga boʻlgan iymondan boshqa «ayb» topa olmadilar.","U shunday zotki, osmonlaru yerning mulki Unga xosdir va Alloh har bir narsaga Oʻzi guvohdir.","Albatta, moʻmin va moʻminalarni fitna qilib, soʻngra tavba qilmaganlarga, ana oʻshalarga, jahannam azobi va kuydiruvchi azob bor.","Albatta, iymon keltirgan va solih amal qilganlarga, ularga, ostidan anhorlar oqib turgan jannat bor. Bu esa nihoyatda ulkan yutuqdir.","Albatta, Robbingning changali juda ham shiddatlidir.","Albatta, U Oʻzi boshlar va qaytarar. (Yoʻqdan bor qilar va oʻlganni hayotga qaytarar)","Va U magʻfirat qiluvchi, muhabbati zoʻr zotdir.","U Arsh egasi hamda qadri ulugʻ zotdir.","U nimani xohlasa, qila oluvchi zotdir.","Senga askarlarning xabari keldimi?","Firʼavn va Samudning.","Balki kofirlar yolgʻonga chiqarishdadir?","Holbuki, Alloh ularning ortidan ihota qilib turuvchidir.","Yoʻq! U Qurʼoni majiddur.","U Lavhul- Mahfuzdadir. (Lavhul- Mahfuz Allohni huzurida boʻlib, unga hech qanday oʻzgarish kirishi mumkin emas.)"],"86":["Osmon bilan qasam va toriq bilan qasam.","Toriq nimaligini senga ne bildirdi?","U nur sochib turuvchi yulduzdir.","Hech bir jon yoʻqki, uning hifz qilib turuvchisi boʻlmasa.","Inson nimadan yaralganiga nazar solsin.","U otilib chiquvchi suvdan yaratilgandir.","U (suv) sulb (umurtqa) va taroib (koʻkrak suyagi) orasidan chiqadir.","Albatta U zot uni qayta tiriltirishga qodirdir.","Sirlar fosh boʻladigan kundadir.","Bas, (oʻshanda) u(inson)da quvvat ham, nusrat beruvchi ham boʻlmaydir.","Qaytuvchi (yomgʻir) sohibi boʻlgan osmon bilan qasam.","Yorib chiquvchi egasi boʻlgan yer bilan qasam.","Albatta u(Qurʼon) ajratuvchi soʻzdir.","Va u hazil emasdir.","Albatta ular hiyla-nayrang qilarlar.","Va Men ham hiyla qilurman. (Yaʼni, hiylasiga yarasha jazo berurman.)","Muhlat ber kofirlarga, ularga ozgina muhlat ber. (Yaʼni, ularga azob kelmayotganidan shoshilma, hammasining vaqti, soati bor.)"],"87":["Oliy qadar boʻlgan Robbing ismini poklab yod et.","U yaratgan va mutanosib qilgan zotdir.","U oʻlchovli qilgan va hidoyatga boshlagan zotdir.","U oʻt-oʻlanni chiqargan zotdir.","Bas, U uni qoraygan xashak qilgan zotdir.","Biz senga qiroat qildiramiz, bas, esdan chiqarmayssan.","Magar Alloh xohlaganini. Albatta, U oshkorni ham, maxfiy narsani ham biladir.","Va seni oson yoʻlga muyassar qilarmiz.","Bas, agar eslatish manfaat bersa, eslatgin.","Albatta, qoʻrqqan esga oladir.","Va badbaxt undan chetda boʻladir.","U katta olovga kiradir.","Soʻngra uning ichida oʻlmay ham, tirilmay ham qoladir.","Batahqiq, kim pok boʻlsa, yutuq topadir.","Va Robbisi ismini zikr qilsa va namoz oʻqisa hamdir.","Lekin, sizlar dunyo hayotini ustun qoʻyasizlar.","Holbuki, oxirat yaxshiroq va boqiyroqdir.","Albatta, bu avvalgi sahifalarda bordir.","Ibrohim va Muso sahifalaridadir."],"88":["Batahqiq senga gʻoshiya xabari keldi.","Oʻshal kunda bir chehralar qoʻrquvchidir.","Ular amal qiluvi va charchavchidir.","Ular oʻta qizigan olovga kirarlar.","Ular qaynab turgan buloqdan sugʻorilarlar.","Ularga tikandan boshqa taom yoʻq.","U na semirtirmas va na ochlikni ketkazmas.","Oʻshal kunda bir chehralar neʼmatlanuvchidir.","Ular oʻz ishlaridan rozidir.","Ular oliy jannatdadir.","Unda ular bekorchi gapni eshitmasdir.","Unda oqib turgan buloqlar bor.","Unda baland-baland soʻrilar bor.","Va tayyorlab qoʻyilgan qadahlar bor.","Va saf-saf tizilgan yostiqlar bor.","Hamma yoqqa toʻshalgan gilamlar bor.","Ular nazar solmaslarmi; Tuyaning qanday yaratilganiga?","Va osmonni qandoq koʻtarilganiga?","Va togʻlarning qandoq oʻrnashtirilganiga?","Va yerni qandoq tekislab qoʻyilganiga?","Bas, eslatgin, sen, albatta, eslatuvchidirsan.","Sen ular ustidan hukmingni oʻtkazuvchi emassan.","Lekin, kim yuz oʻgirsa va kofir boʻlsa.","Bas, uni Alloh katta azob bilan azoblaydir.","Albatta ularning qaytishi Bizgadir.","Soʻngra, albatta, ularning hisob-kitobi ham Bizdadir."],"89":["Fajr bilan qasam.","Va oʻn kecha bilan qasam. (Ulamolarimiz, ushbu oyatdagi oʻn kechadan murod Ramazon oyining oxirgi oʻn kechasi, ularda Laylatul qadr kechasi ham bor, deganlar.)","Juftu toq bilan qasam.","Va yurilgan tun bilan qasam.","Mana shularda aql egasi uchun (qanoatlantiruvchi) qasam bordir?!","Sen Robbing Odga qanday (muomala) qilganinni bilmadingmi?","Baland ustunli «Iram»ga.","Uning misli boshqa diyorlarda xalq qilinmaganga.","Va vodiyda xarsang toshlarni kesgan Samudga. ( Robbing nima qilganini bilmadingmi?)","Va koʻp askarlari bor Firʼavnga. (Robbing nima qilganini bilmadingmi?)","Ular turli oʻlkalarda tugʻyonga ketgan edilar.","Ular u(oʻlka)larda buzgʻunchilikni koʻpaytirdilar.","Bas, Robbing ularning boshiga turli azoblarni quydi.","Albatta, Robbing kuzatib turuvchidir. (U kim nima qilayotganini oʻta aniqlik bilan kuzatib turadi. Kuzatib turib tugʻyonga ketgan, haddidan oshgan va zulm qilganlarning jazosini beradi.)","Bas, qachon insonni Robbisi sinash uchun ikrom qilsa va neʼmat bersa: «Meni Robbim ikrom qildi», deydir.","Bas, qachon Robbisi sinash uchun rizqini tor qilib qoʻysa: «Robbim meni xorladi», deydir.","Yoʻq! Balki Sizlar yetimlarni ikrom qilmassizlar.","Bir-biringizni miskinlarga taom berishga undamassizlar.","Va merosni shiddatla yeysizlar.","Va molni koʻp yaxshi koʻrasizlar.","Yoʻq! Vaqtiki, yer zilzilaga tushib parcha-parcha boʻlib ketsa.","Va Robbing va farishtalar saf-saf boʻlib kelsa.","Va oʻsha kunda jahannamni keltirilsa, oʻsha kunda inson eslaydir. Lekin bu eslashdan endi ne foyda?!","U, afsuski, (oxirat) hayotimga ham biror narsa taqdim qilsam boʻlar ekan, deydir.","Bas, oʻsha kunda Allohning azobiga oʻxshash azobla hech kim azoblamas.","Va Uning bogʻlashiga oʻxshash hech kim bogʻlamas.","Ey xotirjam nafs!","Robbingga sen Undan, U sendan rozi boʻlgan holingda qayt!","Bas, bandalarim ichiga kirgin!","Va jannatimga kirgin!"],"90":["Mana shu shahar bilan qasam.","Sen muqim turgan bu shaharla.","Va volid va undan tarqagan valadlar bilan qasam.","Batahqiq, Biz insonni mashaqqatda yaratdik.","U inson unga hech kimning kuchi yetmaydi, deb hisoblaydimi?","U, koʻplab mol-dunyo nafaqa qildim, deydir. (Mol-dunyo bilan gʻururga ketganlarga yaxshilik yoʻlida ehson qil, deb aytilsa, yuqoridagi gapni aytishadi. Vaholanki, yaxshilik yoʻlida hech narsa sarflamagan boʻladi.)","U inson uni birov koʻrmadi, deb oʻylaydimi?","Biz unga ikki koʻzni bermadikmi?","Va tilni va ikki labni (bermadikmi?)","Va Biz uni ikki: (yaxshi va yomon) yoʻlga yoʻllab qoʻydik.","Bas, u dovon oshib oʻtmadi.","Dovon qandoq narsa ekanini senga nima bildirdi?","U qul ozod qilishdir.","Yoki ocharchilik kunida taom berishdir.","Qarindosh yetimlarga.","Yoki tuproqqa qorigan miskinlarga.","Soʻngra iymon keltirganlar va bir-birini sabrga, mehr-shafqatga chaqirganlar boʻlsa.","Ana oʻshalar oʻng tomon egalaridir.","Oyatlarimizga kufr keltirganlar, ular, chap tomon egalaridir.","Ularni chiqib boʻlmaydigan oʻt-olov oʻrab olgandir."],"91":["Quyosh bilan va uning ziyosi bilan qasam.","Uning ortidan keladigan Oy bilan qasam.","Va u(quyosh)ni ravshan koʻrsatgan nahor bilan qasam.","Va u(quyosh)ni qoplagan tun bilan qasam.","Va osmon bilan va uning bino qilinishi bilan qasam.","Va yer bilan va uning toʻshalishi bilan qasam.","Va nafs bilan va uning bekam-koʻst qilib yaratilishi bilan qasam.","Bas, u(nafs)ga fujurini va taqvosini bildirdi.","Batahqiq, kim u(nafs)ni poklasa, yutuqqa erishadi.","Va batahqiq, kim u(nafs)ni kirlasa, noumid boʻladi.","Samud qavmi oʻz tugʻyoni ila ( Pay gʻambarini) yolgʻonga chiqardi.","Vaqtiki, (undagi) eng badbaxt shaxs shoshilib turdi.","Bas, ularga Allohning Rasuli «Allohning tuyasiga va uning suviga tegmanglar», dedi.","Bas, uni yolgʻonchiga chiqarishdi va ul(tuyani) soʻyishdi.","Va U zot bu ishning oqibatidan qoʻrqmaydi. (Bu dunyoning podshohlari oʻzlarining qilgan ishlaridan, oqibati nima boʻlarkin, deb hadiksirab turadilar. Alloh subhanahu va taolo esa bunday xavfdan mustasnodir.)"],"92":["Tunning qoplab kelayotgan payti bilan qasam.","Nahorning tajalli payti bilan qasam.","Erkak va urgʻochining yaratilishi bilan qasam.","Albatta, sizlarning ishlaringiz turlichadur.","Ammo kimki (ato) bersa va taqvo qilsa.","Va goʻzal(soʻz)ni tasdiq qilsa.","Bas, Biz uni osonga muyassar qilamiz.","Ammo kimki baxillik va istigʻno qilsa.","Va goʻzal(soʻz)ni yolgʻonga chiqarsa.","Bas, Biz uni qiyinga muyassar qilamiz.","U qulagan vaqtda unga mol-mulki foyda bermas.","Albatta, hidoyatga boshlash Bizning zimmamizdadir.","Albatta, ham oxirat va ham bu dunyo Biznikidir.","Bas, Men sizlarni (alangasi avj olib turgan) oʻtdan ogohlantirdim.","U(oʻt)ga badbaxtdan boshqa hech kim kirmas.","Oʻsha yolgʻonga chiqargan va yuz oʻgirgan edi.","Va albatta, undan taqvodor banda chetda qoladi.","U boyligini sarflaydi va oʻzini poklaydi.","Unda biror kishining qaytarilishi lozim yaxshiligi yoʻq edi.","Faqatgina oliy maqom Robbisining roziligini soʻrab qiladi.","Va u albatta tezda rozi boʻladi."],"93":["Choshgoh bilan qasam.","Sukunatga choʻmgan tun bilan qasam.","Robbing seni tark qilmadi va gʻazab ham qilmadi. (Ushbu oyati karima mushriklar, Muhammadning Robbisi unga gʻazab qildi, uni tark etdi, deb gap tarqatganlarida raddiya sifatida tushgandir.)","Va, albatta, oxirat sen uchun bu dunyodan yaxshidir.","Va tezda Robbing senga ato qiladir va sen rozi boʻlursan.","U seni yetim topib, joylab qoʻymadimi?","Va U seni hayron topib, hidoyatga boshlamadimi?","Va U seni kambagʻal topib, boy qilmadimi?","Ammo yetimga qahr qilma.","Va, ammo, «soil»ga zajr qilma. («Soil» kelganda–biror narsasi boʻlsa berishi, boʻlmasa yaxshi muomala qilishi kerak.)","Va, ammo, Robbingning bergan neʼmati haqida soʻzla."],"94":["Sening koʻksingni keng qilib qoʻymadikmi?","Va sening yukingni yengillatmadikmi?","U sening yelkangni bosib turgan edi.","Va sening zikringni yuqori koʻtardik.","Bas, albatta, bir qiyinchilik bilan osonchilik bordir.","Albatta, bir qiyinchilik bilan osonchilik bordir.","Forigʻ boʻlsang, ibodatiga uringin.","Va faqat Robbingga ragʻbat qil."],"95":["Anjir bilan qasam va zaytun bilan qasam.","Va Turi Siyno bilan qasam.","Va mana bu, eminlik yurti (Makka) bilan qasam.","Batahqiq, Biz insonni eng yaxshi suratda yaratdik.","Soʻngra uni asfala safilinga qaytardik. (Inson Yaratganiga ibodatda boʻlsa, farishtadan ham afzalroq martabaga erishdi. Ammo havoi nafsi, hayvoniy xirslari aqlidan ustun kelib nafsning aytganidan yuradigan boʻlsa, hayvondan ham battar holatga tushadi. Ana oʻshanda asfala safilinni koʻraveradi.)","Magar iymon keltirganlar va yaxshi amallar qilganlarga minnatsiz va uzluksiz ajrlar bordir.","Bas, seni nima oxiratni yolgʻonga chiqarishga olib keladi (ey kofir)?","Alloh hukm qilguvchilarning eng hikmatlisi emasmi?!"],"96":["Yaratgan Robbing nomi bilan oʻqi.","U insonni alaqdan yaratdi.","Oʻqi! Va Robbing eng karamlidir!","U qalam bilan ilm oʻrgatgandir.","U insonga u bilmagan narsani oʻrgatdi.","Yoʻq! Albatta inson tugʻyonga ketadir.","Oʻzini boy koʻrgani uchun.","Albatta, qaytib borish Robbingadir.","Qaytarganni koʻrdingmi?!","Bandani namoz oʻqiyotganida?! (Makka mushriklari rahbari Abu Jahl, Muhammadni Kaʼba yonida namoz oʻqiyotganini koʻrsam, boʻynidan oyogʻim bilan bosaman, degan ekan. Shunga binoan bu oyatlardagi namoz oʻquvchidan murod Muhammad sollallohu alayhi vasallam, namozdan qaytaruvchi esa Abu Jahldir.)","Ayt-chi, agar oʻsha hidoyatda boʻlsa.","Yoki taqvoga amr qilsa.","Ayt-chi, oʻsha yolgʻonga chiqarsa va yuz oʻgirsa.","Albatta Alloh uni koʻrishini bilmasmi?!","Yoʻq! Agar qaytmasa, peshonasidan shiddatla tutamiz.","Yolgʻonchi, xatokor peshonasidan.","Bas, oʻz toʻpini chaqirsin.","Biz ham zaboniyalarni chaqiramiz. (Yaʼni, doʻzaxiylarni azoblovchi farishtalarni.)","Yoʻq! Sen unga itoat qilma! Sajda qil va qurbat hosil qil. (Ushbu oyat sajda oyatlaridandir. Imom Muslim ulkan sahobiy Abu Hurayra r. a. dan rivoyat qilgan hadisi sharifda Paygʻambarimiz sollallohu alayhi vasallam: «Banda Allohga eng yaqin boʻlgan payti–sajda paytidir, u paytda duoni koʻp qilinglar», –deganlar.)"],"97":["Albatta, Biz u(Qurʼon)ni Laylatul Qadr da tushirdik.","Laylatul Qadr qandoq narsa ekanini senga nima bildirdi?","Laylatul Qadr ming oydin yaxshiroqdir.","Unda farishtalar va Ruh Robbilari izni bilan barcha ishlar uchun tushadir.","U to tong otguncha salom boʻlib turadir."],"98":["Ahli kitob va mushriklardan boʻlgan kufr keltirganlarga «bayyina» kelmaguncha ajralmasdilar.","U (bayyina) Alloh tarafidan yuborilgan Rasul boʻlib, poklangan sahifalarni tilovat qiladir.","Ularda ajoyib bitiklar bordir.","Kitob berilganlar ularga «bayyina» kelganidan soʻnggina boʻlinib ketishdi.","Holbuki, ular faqat Allohgagina ibodat qilishga, Uning dinigagina ixlos qilishga, boshqa dinlarga moyil boʻlmaslikka, namozni toʻliq oʻqishga, zakot berishga buyurilgan edilar. Ana shu toʻgʻri millatning dinidir. (Yahudiy va nasorolar Tavrot va Injilda faqat Alloh taoloning Oʻzigagina ibodat qilishga amr etilgan edilar.)","Albatta, ahli kitob va mushriklardan boʻlgan kufr keltirganlar jahannam oʻtidadurlar, u yerda abadiy qolurlar. Ana oʻshalar xaloyiqning eng yomonlaridir.","Albatta, iymon keltirganlar va solih amallarni qilganlar, ana oʻshalar, xaloyiqning eng yaxshilaridir.","Ularning mukofotlari Robbilari huzuridagi ostidan anhorlar oqib turgan jannat «adn»dir. U yerda abadul abad qolajaklar. Alloh ulardan rozi boʻldi, ular ham U zotdan rozi boʻldilar. Bu Robbisidan qoʻrqqanlar uchundir."],"99":["Vaqtiki, yer oʻziga xos zilzilaga tushsa.","Va yer oʻz yuklarini otib chiqarsa.","Va inson, unga nima boʻldi?!, desa.","Oʻsha kunda u(yer) oʻz xabarini aytadir.","Sening Robbing unga vahiy yuborganini.","Oʻsha kunda odamlar guruh-guruh boʻlib, amallarini koʻrish uchun joylaridan qoʻzgʻaladir.","Bas, kim zarra ogʻirligida yaxshilik qilsa ham koʻradir.","Va kim zarra ogʻirligida yomonlik qilsa ham koʻradir. (Yaxshilikning ham, yomonlikning ham katta-kichigi boʻlmaydi. Hammasining hisob-kitobi boʻladi, qiyomatda javob berish kerak. Har doim yaxshilikni qilib, agar u koʻzga koʻrinmas zarra miqdorida boʻlsa ham yomonlikdan qochish kerak.)"],"100":["Harsillab chopuvchiotlar bilan qasam.","Oʻt chaqnatib chopuvchi otlar bilan qasam.","Tong chogʻida gʻorat qiluvchi otlar bilan qasam.","Oʻsha paytda chang qoʻzgʻotdilar.","Va u ila jamoa oʻrtasiga (yorib) kirdilar.","Albatta, inson oʻz Robbisiga noshukrdir.","Va albatta, u ana shunga oʻzi guvohdir.","Albatta, u mol-dunyoga haddan tashqari oʻchdir.","U bilmasmi?! Qabrdagilar qoʻzgʻatilganda.","Va koʻkraklaridagi oshkor boʻlganda.","Oʻsha kunda Robbilari ulardan, xabardor ekanini?!"],"101":["Al-Qoriʼatu.","Qoriʼatu nima?","Qoriʼat qandoq narsa ekanligini senga nima bildirdi?","U kunda odamlar toʻzib ketgan kapalakka oʻxshab qolarlar.","Va togʻlar titilgan junga oʻxshab qolar.","Kimning torozusi ogʻir kelsa...","Bas, u rozilik hayotidadir.","Va ammo kimning tarozusi yengil kelsa...","Bas, uning onasi doʻzaxdir. (Odatda ona doim panoh boʻlgan. Inson ayniqsa ogʻir paytlarda onasiga intilganday, qiyomatda ham onasini qoʻmsaganda jahannam ularni ona oʻrnida kutib olarkan. Mehr-muhabbat, shafqat izlab turganda, koni azobga, qiynoqqa, dahshatli olovda yonishga duch kelishi nihoyatda katta baxtsizlik.)","U qandoq narsa ekanligini senga nima bildirdi?","U qattiq qizigan oʻtdir."],"102":["Kimniki koʻp sizni mashgʻul qildi.","To qabrlarni ziyorat qilguningizcha","Yoʻq! Sizlar tezda bilasizlar.","Yana yoʻq! Sizlar tezda bilasizlar.","Yoʻq! Agar sizlar aniq ilm ila bilganingizda edi.","Albatta, jahannamni koʻrasizlar.","Va yana, albatta, uni ishonch koʻzi bilan koʻrasizlar.","Soʻngra oʻsha kunda, albatta, berilgan neʼmatlardan soʻralasizlar. (Yaʼni, qiyomatda har bir neʼmatni nimaga, qandoq sarf qilganingiz haqida soʻraladi. Ha, kattayu kichik har bir neʼmat haqida soʻralasiz. Har bir neʼmatga shukr qildingizmi, yoʻqmi - soʻralasiz. Alloh taolo sizga bergan molu dunyo neʼmatini nimaga sarfladingiz, halolgami haromga, Allohni rozi qiladigan yoʻlgami, gʻazabini qoʻzgʻatadigan yoʻlgami hamma-hammasi haqida soʻralasiz.)"],"103":["Asr bilan qasam.","Albatta, inson xusrondadir. (Xusron-magʻlubiyat, yutqiziq va nuqson maʼnolarini anglatadi.)","Magar iymon keltirganlar va solih amallar qilganlar, bir-birlarini haqga chaqirganlar va bir-birlarini sabrga chaqirganlar mustasnodir. (Maʼlum boʻldiki, inson ikki dunyoda badbaxt boʻlib qolmaslik uchun toʻrtta sifatga ega boʻlishi kerak ekan: Allohga iymon keltirishi. Solih amallar qilishi. Haq amallar qilishi. Sabrga chaqirishi.)"],"104":["Har bir obroʻ toʻkuvchi va ayblovchiga «vayl» boʻlsin.","U mol jamladi va uni sanab turdi.","U, albatta, uni abadiy qoldirur, deb hisoblar.","Yoʻq! Albatta u «hutoma»ga xor-zor etib tashlanar.","«Hutoma» qandoq narsa ekanini senga nima bildirar?","U Allohning shiddatli, oʻchmas olovidir.","Qalbgacha yetib boradir.","Albatta, u ularni ustidan qoplangandir.","Uzun-uzun ustunlarga bogʻlangandirlar."],"105":["Robbing fil sohiblarini qandoq qilganini bilmadingmi?","Ularning makru hiylasini zoye ketkazmadimi?","Va ularning ustiga toʻp-toʻp qushlarni yubormadimi?","Loydan pishirilgan toshlarni otadiganlarni?","Bas, ularni qurt yeb tashlagan oʻsimlikka oʻxshatib yubormadimi?. Muhammad alayhissalom «Fil yili»da tugʻilganlar deyilishining sababi ham shu."],"106":["Qurayshning lozim tutishi qanday yaxshi!","Ularning qish va yoz safarlarini oʻzlariga lozim tutishlari qanday yaxshi!","Bas, ular mana shu Baytning Robbisiga ibodat qilsinlar!","U zot ularini ochlikdan toʻq qilgan, xavfdan omon qilgandir."],"107":["Jazo kunini yolgʻonga chiqaruvchini koʻrdingmi?","Ana oʻsha, yetimni qoʻpollik bilan haydaydir.","Va miskinlarga taom berishga qiziqtirmaydir.","«Namozxonlar»ga vayl boʻlsin.","Ular oʻz namozlarini unituvchilardir.","Ana oʻshalar riyo qiladiganlardir.","Va maoʼunni man qiladiganlardir."],"108":["Albatta, Biz senga Kavsarni berdik.","Bas, Robbingga namoz oʻqi va jonlik soʻy.","Albatta, seni yomon koʻrib, ayblovchining orqasi kesikdir."],"109":["Ayt: «Ey kofirlar!","Men siz ibodat qilgan narsalarga ibodat qilmasman.","Va sizlar ham men ibodat qiladiganga ibodat qiluvchimassiz.","Va men siz ibodat qilgan narsaga ibodat qiluvchimasman.","Va siz ham men ibodat qilganga ibodat qiluvchimassiz.","Sizga oʻz diningiz, menga oʻz dinim. (Bu surada Islom eʼlon qilgan aqida erkinligi oʻz aksini topgan. 1400 yil avval eʼlon qilingan bu hurriyat oyoq osti qilinganda, insoniyat ulkan zararlar tortdi.)"],"110":["Vaqtiki, Allohning nusrati va fath kelsa...","Va odamlarning Allohning diniga toʻp-toʻp boʻlib kirayotganini koʻrsang...","Bas, Robbingni poklab yod et va Unga istigʻfor ayt. Albatta, U tavbalarni koʻplab qabul etuvchidir."],"111":["Abu Lahabning ikki qoʻli halok boʻlsin, halok!","Unga moli va kasb qilgan narsalari foyda bermadi.","U tezda choʻgʻi qizib turgan oʻtga kiradi.","Va uning xotini, oʻtin koʻtargan ayol ham.","U(ayol)ning boʻynida eshilgan arqon bor holda."],"112":["Ayt: «U Alloh yagonadir».","Alloh somaddir. (Hojatlarni va ragʻbatlarni qondiruvchidir.)","U tugʻmagan va tugʻilmagan.","Va Unga hech kim teng boʻlmagan. (Alloh taologa biror zot na zotida, na sifatida va na amalida teng boʻlgan emas, boʻlolmaydi ham.)"],"113":["Tong Robbisidan panoh soʻrayman.","U yaratgan narsalar yomonligidan.","Va kirib kelgan qorongʻulik yomonligidan.","Va tugunlarga dam soluvchilar yomonligidan. (Sehrgarlar birovni sehrlab zarar yetkazmoqchi boʻlsa, ip olib, oʻqiydigan narsasini oʻqib, dam solib, ipni bir tugib, yana bir dam solib, yana tugib, oxiriga yetkazar ekan.)","Va hasad qilgan hasadchining yomonligidan, deb ayt."],"114":["Odamlar Robbisidan.","Odamlar Podshohidan.","Odamlar Ilohidan panoh soʻrayman.","Berkinib, koʻrinib turuvchi vasvosning.","Odamlar qalbiga vasvasa soladiganning.","Jinlardan va odamlardan boʻlganning yomonligidan, deb ayt. (Oyatda zikr qilingan «berkinib, koʻrib turuvchi»dan murod shaytondir.)"]};
